  Stage_116404_Name = {Text = "進階2"},
  Stage_118130_Desc = {
    Text = "世界向它的愛人掀開了它無垠的面紗。\n它變小了，小如一個永恆的吻，小如一首永恆的歌。"
  },
  Stage_118130_Name = {
    Text = "永恆面紗"
  },
  Stage_118131_Desc = {
    Text = "騎士厲兵秣馬、披堅執銳，斬向飛馳而來的風車。"
  },
  Stage_118131_Name = {
    Text = "風車騎士"
  },
  Stage_118132_Desc = {
    Text = "在命運的狹縫間，亡命的共犯十指相扣——\n相信我，跟上我，我們一定一定一定能逃出去。\n我們一起，奔向自由。"
  },
  Stage_118132_Name = {
    Text = "飛躍與自由"
  },
  Stage_118133_Desc = {
    Text = "在漫長調查的尾聲，為撫慰調查員疲憊的靈魂，彌薩格大學有一項傳統：為他們奉上一段由海風與陽光款待的悠閒假日。\n\n而今天，這份來自守密人的贈禮，專為神母而備。"
  },
  Stage_118134_Desc = {
    Text = "在漫長調查的尾聲，為撫慰調查員疲憊的靈魂，彌薩格大學有一項傳統：為他們奉上一段由海風與陽光款待的悠閒假日。\n\n而今天，這份來自守密人的贈禮，專為神母而備。"
  },
  Stage_118135_Desc = {
    Text = "自如遊走於漩渦臨界，只是脆弱船隻的幻覺。\n在肉眼不可見的渦流之中，蘊藏著足以吞噬和絞殺所有心懷僥倖者的龐大吸力。"
  },
  Stage_118135_Name = {Text = "漩渦"},
  Stage_118136_Desc = {
    Text = "跳吧，跳下去吧，親愛的長髮公主。\n在那墜落之地，定會有騎士溫暖堅毅的懷抱。"
  },
  Stage_118137_Desc = {
    Text = "此處名為「樂園號」，是蹈海者教會永恆而唯一的海上據地。\n是她的靈魂寄託之地，觸手可及的理想鄉。"
  },
  Stage_118137_Name = {
    Text = "「樂園號」"
  },
  Stage_118138_Desc = {
    Text = "「我不說我的愛如何高尚，我只說想到你的夜晚我能安然入睡。」"
  },
  Stage_118139_Desc = {
    Text = "聖女高高地站上祭壇，俯瞰著熊熊燃燒的火焰。\n那躍動的火舌在她眼中映照出的，不是恐懼，而是終於到來的宿命。\n她能聽見柴薪爆裂的劈啪聲，和體內神諭漸逝的迴響。\n這一刻，她不再是被縛的囚徒。"
  },
  Stage_118139_Name = {
    Text = "引航典儀"
  },
  Stage_118140_Desc = {
    Text = "騎士厲兵秣馬、披堅執銳，斬向飛馳而來的風車。"
  },
  Stage_118140_Name = {
    Text = "風車騎士"
  },
  Stage_118141_Desc = {
    Text = "她有一千個一萬個從未出口的問題。\n她有唯一一個無論如何都想要知道答案的問題。"
  },
  Stage_118141_Name = {Text = "誕妄"},
  Stage_118142_Desc = {
    Text = "她被什麼束縛？\n職責、命運與愛。"
  },
  Stage_118142_Name = {Text = "枷鎖"},
  Stage_118143_Desc = {
    Text = "漂流不定的夢，總是環繞著一個隱藏的主題。\n那便是核心，是不可明言的恐懼，是難宣於口的欲望。"
  },
  Stage_118144_Desc = {
    Text = "「在祂的女兒黑暗的@1中，偉大的@2降臨於世。」"
  },
  Stage_118144_Name = {
    Text = "神誕七日"
  },
