  Stage_119838_Desc = {
    Text = "你聽到了群星的歌謠，在這無垠的宇宙裡。\n但真空無法傳聲，因此無論是你的呐喊，還是他們的狂嘯，都寂靜無音。"
  },
  Stage_119838_Name = {
    Text = "死寂韻律"
  },
  Stage_119839_Desc = {
