  },
  Stage_122177_Desc = {
    Text = "神啊，請告訴我正確的道路，讓我不至於迷途，能夠堅定無畏的走向那被引導的正路。"
  },
  Stage_122178_Name = {
    Text = "蒙蔽雙眼·癲狂"
  },
  Stage_122179_Desc = {
    Text = "永遠追求理想，追求光明，追求希望。\n哪怕這代價是獻祭自己。\n神啊，我只希望我正堅定無畏走向的那條路，是你引導的正路。"
  },
  Stage_122179_Name = {
    Text = "以自身為獻祭"
  },
