  },
  Stage_122186_Desc = {
    Text = "平凡的日常就如無用的闌尾，是時候切割掉了~"
  },
  Stage_122186_Name = {
    Text = "切割闌尾·之一"
  },
  Stage_122601_Name = {
    Text = "茉夏試玩關卡"
  },
  Stage_123112_Desc = {
    Text = "迷霧遮住了我的眼睛，令我失去了與自己世界的聯繫，但透過你的雙眸，我看見了那些再回不去的過往，再無法見到的人。\n我們是相似的。"
  },
  Stage_123112_Name = {
    Text = "透過你的雙眸"
  },
  Stage_123113_Desc = {
    Text = "迷霧遮住了我的眼睛，令我失去了與自己世界的聯繫，但透過你的雙眸，我看見了那些再回不去的過往，再無法見到的人。\n我們是相似的。"
  },
  Stage_123113_Name = {
    Text = "透過你的雙眸"
  },
  Stage_125199_Desc = {
    Text = "唯有耽於愛的蟲豸，才如此脆弱，如此堅韌，如此可笑，又如此非凡。\n哎呀，與妾身去看看更美妙的東西吧， 你們將彼此照應，你們將從此緊密相連。"
  },
  Stage_125199_Name = {
    Text = "羅織·之三"
  },
  Stage_125200_Desc = {
    Text = "情熱總有歸處，不總是歸於偕老，歸於枉死的時候或許更多。\n有時枉死的是愛，有時枉死的是你。"
  },
  Stage_125200_Name = {
    Text = "枉死·癲狂"
  },
  Stage_125201_Desc = {
    Text = "舊愛已離你而去，你為何此時才開始痛悔？\n嘻嘻，不遲，不急，看呀——郎君。只要日頭落下，每一盞燈，每一根紅燭， 都會在窗後映出她的形，她的影。"
  },
  Stage_125201_Name = {
    Text = "窗後影·之二"
  },
  Stage_125202_Desc = {
    Text = "「……如蟬留皮換骨，謂之尸解而登仙……」\n哦，其實不是， 那是一段荒唐謬聞，但有什麼關係呢？她們以血淚祈願，於是令人戰慄的美與恐懼從中蘇生。"
  },
  Stage_125203_Desc = {
    Text = "舊愛已離你而去，你為何此時才開始痛悔？\n嘻嘻，不遲，不急，看呀——郎君。只要日頭落下，每一盞燈，每一根紅燭， 都會在窗後映出她的形，她的影。"
  },
  Stage_125203_Name = {
    Text = "窗後影·之一"
  },
  Stage_125204_Desc = {
    Text = "祂們共同跪伏於香案供桌之下，那無相的玄女無可探知，無從界定，無法違逆。\n獻上所有，依從所有，登臨唯一的極樂，永遠的混亂。"
  },
  Stage_125204_Name = {
    Text = "極樂·癲狂"
  },
  Stage_125205_Desc = {
    Text = "妾身喜歡你的氣味，妾身會替你嘗一嘗你的仇人。"
  },
  Stage_125206_Desc = {
    Text = "那神秘的結社遊離於東方古國的史書之外，它無法被探知，無法被界定，唯有極少數迄今仍未消亡，永居在無夢鄉的個體，曾經獲知過它所祭拜的神明的名諱。\n她被喚作——「@4」"
  },
  Stage_125206_Name = {
    Text = "臃容眾·之一"
  },
  Stage_125207_Desc = {
    Text = "祂們共同跪伏於香案供桌之下，那無相的玄女無可探知，無從界定，無法違逆。\n獻上所有，依從所有，登臨唯一的極樂，永遠的混亂。"
  },
  Stage_125207_Name = {
    Text = "極樂·之六"
  },
  Stage_125208_Desc = {
    Text = "喀啦——吸溜——咕啾——唔——\n我們會永遠廝守，我們會永遠廝守。\n我們會永遠永遠永遠廝守廝守廝守廝守廝守守守守守守守@4"
  },
