  },
  Stage_125245_Desc = {
    Text = "舊愛已離你而去，你為何此時才開始痛悔？\n嘻嘻，不遲，不急，看呀——郎君。只要日頭落下，每一盞燈，每一根紅燭， 都會在窗後映出她的形，她的影。"
  },
  Stage_125245_Name = {
    Text = "窗後影·之四"
  },
  Stage_125246_Desc = {
    Text = "「……如蟬留皮換骨，謂之尸解而登仙……」\n哦，其實不是， 那是一段荒唐謬聞，但有什麼關係呢？她們以血淚祈願，於是令人戰慄的美與恐懼從中蘇生。"
  },
  Stage_125247_Desc = {
    Text = "噓，他們在騙你。\n寶貝，寶貝，醒來，去搶所有你能搶到的東西。\n軟弱的人才會藏在夢裡。"
  },
  Stage_125247_Name = {Text = "不夢"},
  Stage_125248_Desc = {
    Text = "事情總是開始於一次鍾情，一場雨，一方絲帕，抑或一次月下相會。"
  },
  Stage_125248_Name = {
    Text = "愛怨相生·癲狂"
  },
  Stage_125249_Desc = {
    Text = "見卻不可見，求卻無處求。\n股且戰戰，淚又墜墜，哎呀，小囡囡，老嗲的來。"
  },
  Stage_125249_Name = {Text = "忽來哉"},
  Stage_125250_Desc = {
    Text = "情熱總有歸處，不總是歸於偕老，歸於枉死的時候或許更多。\n有時枉死的是愛，有時枉死的是你。"
  },
