  },
  Stage_125254_Desc = {
    Text = "「……如蟬留皮換骨，謂之尸解而登仙……」\n哦，其實不是， 那是一段荒唐謬聞，但有什麼關係呢？她們以血淚祈願，於是令人戰慄的美與恐懼從中蘇生。"
  },
  Stage_125255_Desc = {
    Text = "喀啦——吸溜——咕啾——唔——\n我們會永遠廝守，我們會永遠廝守。\n我們會永遠永遠永遠廝守廝守廝守廝守廝守守守守守守守@4"
  },
  Stage_125255_Name = {
    Text = "吮·癲狂"
  },
  Stage_125256_Desc = {
    Text = "祂們共同跪伏於香案供桌之下，那無相的玄女無可探知，無從界定，無法違逆。\n獻上所有，依從所有，登臨唯一的極樂，永遠的混亂。"
  },
  Stage_125256_Name = {
    Text = "極樂·之一"
  },
  Stage_125257_Desc = {
    Text = "那神秘的結社遊離於東方古國的史書之外，它無法被探知，無法被界定，唯有極少數迄今仍未消亡，永居在無夢鄉的個體，曾經獲知過它所祭拜的神明的名諱。\n她被喚作——「@4」"
  },
  Stage_125257_Name = {
    Text = "臃容眾·之四"
  },
  Stage_125258_Desc = {
    Text = "「……如蟬留皮換骨，謂之尸解而登仙……」\n哦，其實不是， 那是一段荒唐謬聞，但有什麼關係呢？她們以血淚祈願，於是令人戰慄的美與恐懼從中蘇生。"
  },
  Stage_125259_Desc = {
    Text = "大馬路、二馬路、三馬路、四馬路……\n嘻嘻，哦喲~\n小聲點，四馬路可是個說不得的去處。\n"
  },
  Stage_125259_Name = {
    Text = "美人骨，銷金窟"
  },
  Stage_125260_Desc = {
    Text = "喀啦——吸溜——咕啾——唔——\n我們會永遠廝守，我們會永遠廝守。\n我們會永遠永遠永遠廝守廝守廝守廝守廝守守守守守守守@4"
  },
  Stage_125261_Desc = {
