  },
  Stage_125261_Name = {
    Text = "尸解·癲狂"
  },
  Stage_125262_Desc = {
    Text = "妾身喜歡你的氣味，妾身會替你嘗一嘗你的仇人。"
  },
  Stage_125263_Desc = {
    Text = "妾身喜歡你的氣味，妾身會替你嘗一嘗你的仇人。"
  },
