  },
  Stage_125269_Name = {
    Text = "愛怨相生·之一"
  },
  Stage_125638_Desc = {
    Text = "舞台的歡迎詞是：賓至如歸。"
  },
  Stage_125638_Name = {
    Text = "霧都未醒"
  },
  Stage_125639_Desc = {
    Text = "卡德林莊園熱衷於看到輝煌與衰落的戲碼。只有懂得取悅莊園的人，才能得到請柬。"
  },
  Stage_125639_Name = {
    Text = "莊園的請柬"
  },
  Stage_125640_Desc = {
    Text = "除了記憶，我們一無所有。"
  },
  Stage_125641_Desc = {
    Text = "除了記憶，我們一無所有。"
  },
  Stage_125642_Desc = {
    Text = "演員登場，作者不詳。"
  },
  Stage_125643_Desc = {
    Text = "舞台的歡迎詞是：賓至如歸。"
  },
  Stage_125643_Name = {
    Text = "霧都未醒"
  },
  Stage_125644_Desc = {
    Text = "從憐憫與欺騙中歸來吧，親愛的孩子們。\n那無光的遺棄之所，才是真正屬於你們的地方。"
  },
  Stage_125644_Name = {Text = "重圓"},
  Stage_125645_Desc = {
    Text = "其實，遙遠的神明從不渴望甦醒。"
  },
  Stage_125646_Desc = {
    Text = "帷幕業已落下，但敬業的演員從不退場。"
  },
  Stage_125647_Desc = {
    Text = "從憐憫與欺騙中歸來吧，親愛的孩子們。\n那無光的遺棄之所，才是真正屬於你們的地方。"
  },
  Stage_125647_Name = {Text = "重圓"},
  Stage_125648_Desc = {
    Text = "親愛的囚徒，與一切告別吧。命運的判決從不需要律法。"
  },
  Stage_125648_Name = {Text = "判決"},
  Stage_125649_Desc = {
    Text = "大洋彼岸的颶風，其實從來就與那隻蝴蝶的選擇無關。"
  },
  Stage_125649_Name = {Text = "槍火"},
  Stage_125650_Desc = {
    Text = "其實，遙遠的神明從不渴望甦醒。"
  },
  Stage_125651_Desc = {
    Text = "比尖刺與火焰更苦難的刑罰。"
  },
  Stage_125651_Name = {
    Text = "溫柔的枷鎖"
  },
  Stage_125652_Desc = {
    Text = "最美的舞姿，永遠在死亡與破碎中綻放。"
  },
  Stage_125652_Name = {
    Text = "天鵝翱翔"
  },
  Stage_125653_Desc = {
    Text = "90分鐘午夜，15英寸假面，10加侖夢境，2盎司酒精——快樂的唯一配方。"
  },
  Stage_125653_Name = {
    Text = "假面派對"
  },
  Stage_125654_Desc = {
    Text = "一場精心排練的新劇，免費觀看，禁止離席。"
  },
  Stage_125654_Name = {Text = "劇中人"},
  Stage_125655_Desc = {
    Text = "歡笑！高歌！我的朋友！命運的舞台上，歡愉是唯一的主角。"
  },
  Stage_125655_Name = {
    Text = "即興喜劇"
  },
  Stage_125656_Desc = {
    Text = "踏入劇場之時，屬於我們的角色早已無從選擇。"
  },
  Stage_125656_Name = {
    Text = "觀眾，演員，作者"
  },
  Stage_125657_Desc = {
    Text = "比尖刺與火焰更苦難的刑罰。"
  },
  Stage_125657_Name = {
    Text = "溫柔的枷鎖"
  },
  Stage_125658_Desc = {
    Text = "最美的舞姿，永遠在死亡與破碎中綻放。"
  },
  Stage_125658_Name = {
