  },
  Stage_125662_Name = {Text = "槍火"},
  Stage_125663_Desc = {
    Text = "不朽的牢籠，由囚徒親手織就。\n她們永世編織。她們從未逃離。"
  },
  Stage_125663_Name = {Text = "繭"},
  Stage_126202_Desc = {
    Text = "鮮花，歡呼，掌聲。世界重新回到它身邊。\n敘事的魔術師完成了它的表演，觀眾的記憶在優雅的謝幕中消散。\n沒有任何的秘密，能從舞台的廢墟上離開。"
  },
  Stage_126202_Name = {
    Text = "請勿劇透·之四"
  },
  Stage_126203_Desc = {
    Text = "迎接吧，故事的高潮！一切的伏筆都是燃料，一切的準備，都是為了點燃舞台的這一刻。"
  },
  Stage_126203_Name = {
    Text = "燃燒·之四"
  },
  Stage_126204_Desc = {
