  Stage_129163_Name = {
    Text = "疾馳的歡愉專列·普通"
  },
  Stage_129164_Name = {
    Text = "疾馳的歡愉專列・困難"
  },
  Stage_129165_Name = {
    Text = "疾馳的歡愉專列·癲狂"
  },
  Stage_129500_Desc = {
    Text = "磐龍古國的每個祈歲節、無論天南海北、家家戶戶都要團圓。\n他們在祈歲節將至時登上通往遠方的列車、懷抱著憧憬的心期盼著久別重逢的時刻。"
  },
  Stage_129500_Name = {
    Text = "祈歲列車"
  },
  Stage_129501_Desc = {
    Text = "別害怕、這只是一場遊戲。\n一場殘忍的、惡劣的遊戲。"
  },
  Stage_129501_Name = {
    Text = "遊戲開始"
  },
  Stage_129502_Desc = {
    Text = "別停下、別退讓。\n如果善意的人放下了手中的槍、那麼邪惡便會乘勝追擊。"
  },
  Stage_129503_Desc = {
    Text = "這是屬於正義的絕地反擊……嗎？"
  },
  Stage_129503_Name = {
    Text = "隱藏的殺招"
  },
  Stage_129504_Desc = {
    Text = "那支拉桿經常在你夢裡出現。\n推動它、還是拉下它、這是一個問題。"
  },
  Stage_129504_Name = {
    Text = "常暗之廂"
  },
  Stage_129505_Desc = {
    Text = "焰火連天辭舊歲、往日湮灰不可追。"
  },
  Stage_130109_Desc = {
    Text = "人要上學，喚醒體也要上學。\n現在她是喚醒體了，她當然也要上學。\n請務必注意安全。"
  },
  Stage_130109_Name = {
    Text = "學校·之二"
  },
  Stage_130110_Desc = {
    Text = "如何成為傳奇調查員？首先，每一口深井都藏著許許多多的秘密。\n其次，闖進井底之前，記得散彈槍並不一定非得合法持有。"
  },
  Stage_130111_Desc = {
    Text = "如何成為傳奇調查員？首先，每一口深井都藏著許許多多的秘密。\n其次，闖進井底之前，記得散彈槍並不一定非得合法持有。"
  },
  Stage_130112_Desc = {
    Text = "沒錯，即便是傳奇調查員，也未必每次都能獲得勝利。\n……但沒關係，伏特加還剩最後一滴。"
  },
  Stage_130112_Name = {
    Text = "最後的小酌·之四"
  },
