    Text = "把天花板塗成喜歡的顏色，把牆壁塗成喜歡的顏色。\n把冰箱裝滿喜歡的食物，養我們都喜歡的寵物。\n這是隻屬於你和我的家。"
  },
  Stage_130157_Desc = {
    Text = "把天花板塗成喜歡的顏色，把牆壁塗成喜歡的顏色。\n把冰箱裝滿喜歡的食物，養我們都喜歡的寵物。\n這是隻屬於你和我的家。"
  },
  Stage_130158_Desc = {
    Text = "醫院是一個不可思議的地方，同時匯聚了新生、離世、重生、世間最大的痛苦，和世間最大的喜悅。\n然而，人們的喜悅、悲傷，以及所有的情感，卻彼此之間完全無法相通。"
  },
  Stage_130158_Name = {
    Text = "醫院·之六"
  },
  Stage_130159_Desc = {
    Text = "人要上學，喚醒體也要上學。\n現在她是喚醒體了，她當然也要上學。\n請務必注意安全。"
  },
  Stage_130159_Name = {
    Text = "學校·之四"
  },
  Stage_130160_Desc = {
    Text = "醫院是一個不可思議的地方，同時匯聚了新生、離世、重生、世間最大的痛苦，和世間最大的喜悅。\n然而，人們的喜悅、悲傷，以及所有的情感，卻彼此之間完全無法相通。"
  },
  Stage_130160_Name = {
    Text = "醫院·之三"
  },
  Stage_130161_Desc = {
    Text = "在一千一萬個夢境中，你牽起她的手。\n隱秘的電流從你們的鏈接中穿行而過，形成永不消逝的循環。\n聆聽它的呼喚，尋找她，找到她。\n即使被血肉吞沒。"
  },
  Stage_130162_Desc = {
    Text = "人要上學，喚醒體也要上學。\n現在她是喚醒體了，她當然也要上學。\n請務必注意安全。"
