  Stage_130819_Desc = {
    Text = "陽光穿過窗戶、灑向散發橡木香氣的課桌。\n書本散落一旁、莫絲懶洋洋地趴在桌上。\n「諾締拉Zzz……小煤球Zzz……開心~」\n長久的冰冷和孤獨已經結束。\n接下來是更更好的明天。"
  },
  Stage_130819_Name = {
    Text = "好、更好、更更好"
