  Stage_131105_Desc = {
    Text = "不朽的牢籠，由囚徒親手織就。\n她們永世編織。她們從未逃離。"
  },
  Stage_131105_Name = {Text = "繭"},
  Stage_132466_Desc = {
    Text = "內部測試專用"
  },
  Stage_132466_Name = {
    Text = "測試環境·忘卻篇"
  },
  Stage_139577_Desc = {
    Text = "太好了，這些……不不不，我是說這些黑貓太壞了！"
  },
  Stage_139578_Desc = {
    Text = "銀芯和金券裝滿口袋，得勝的將軍滿載而歸。"
  },
  Stage_139578_Name = {
    Text = "滿載而歸"
  },
  Stage_139579_Desc = {
    Text = "你盯上了最大的那隻貓，而牠也盯上了你。"
  },
  Stage_139580_Desc = {
    Text = "不過貓還有很多，讓我們再來……最後一次？"
  },
  Stage_139580_Name = {
    Text = "再來一次"
  },
  Stage_139581_Desc = {
    Text = "當第一縷銀色閃耀在漆黑的海洋裡時，你手上的捕貓網揮得更有力氣了。"
  },
  Stage_139581_Name = {
    Text = "第一桶銀芯"
  },
  Stage_139582_Desc = {
    Text = "黑貓反抗你，說明你做對了。"
  },
  Stage_139583_Desc = {
    Text = "網越大，貓越多，大貓就得用大網，收！"
  },
  Stage_139583_Name = {
    Text = "收網！收網！"
  },
  Stage_140299_Desc = {
    Text = "綻放吧，飛舞吧。\n你已決意無論前路如何艱險，你永遠不會選擇放開她的手。\n當你我作別的瞬間，讓倒錯的世界佈滿「真實」。"
  },
  Stage_140299_Name = {Text = "告別"},
