  Stage_141235_Desc = {
    Text = "你喜歡玩遊戲，你把一切都視為鬧劇。所以我們會割開那些信徒的喉管，踩碎他們的脊梁，讓他們知道自己在信仰多麼愚蠢可笑的髒東西。\n一直逃吧，否則，你就會發現連湮滅都只是美妙的妄想。"
  },
  Stage_141235_Name = {
    Text = "追逃遊戲·之一"
  },
