  Stage_141288_Desc = {
    Text = "他被比海洋更古老的存在選中了，他留在了那個他回不去的地方。"
  },
  Stage_141289_Desc = {
    Text = "祂不易察覺，祂悄無聲息，祂突如其來。\n人們在蓬勃的日子裡事不關己地提起祂的名字，直到人們察覺，祂已成為如影隨形的朋友。\n"
  },
  Stage_141290_Desc = {
    Text = "最熱鬧的食物，最適合慶祝的食物，我們舉杯，我們相聚。\n沒有人在意一具具軀殼下是不是同一個意志，沒有人在意一具具空殼下還有沒有靈魂."
