  },
  Stage_141747_Desc = {
    Text = "是的，是的，人是可以倒霉到這個地步的。\n她的一生除了謊言什麼都沒有，她這一次相信，下一次依舊，她就因為一點點希望，吞下了所有謊言的苦果。\n所以在這場謊言的盡頭，在她一生的盡頭……\n我們在她的眼睛裡，除了仇恨，什麼都找不到。"
  },
  Stage_141747_Name = {
    Text = "眼睛·癲狂"
  },
  Stage_141748_Desc = {
    Text = "故事進行到這裡，你開始有一些躊躇。\n線索明明在一開始已經出現，命運牽引你來見證什麼呢？絲線的彼端，連接著什麼樣的真相呢？\n雪下面埋藏著什麼，到底有幾個人能夠所願得償？\n你不知道，旅途還未過半，你只能繼續順應它的指引。"
  },
  Stage_141748_Name = {
    Text = "絲線·之六"
  },
  Stage_141749_Desc = {
    Text = "♬~~♫~~♪~~♫~~♪~~♫~~\n有一隻尋找同伴的孤號鳥，他的同伴失去了翅膀，他的同伴被拔光了羽毛。\n他試圖實現實現不了的願望，他的同伴連與他的回憶都忘掉。\n ♬~~♫~~♪~~♫~~♪~~♫~~\n沒關係，沒關係。他們還有甜美的、甜美的、共同的歸宿。他們會進入安寧的、安寧的、永不被打擾的夢鄉。"
  },
  Stage_141750_Desc = {
    Text = "哦，小小的神明的碎片，卡達斯的救世主，一切毀滅的希望，一切絕境中的新生，彌薩格唯一的守密人。\n你緊緊握住了陪你走到至今的鑰匙，你的內心充滿了決心。\n好的，那句話怎麼說來著……？願銀鑰指引我們！"
  },
  Stage_141750_Name = {
    Text = "鑰匙·之三"
  },
  Stage_141751_Desc = {
    Text = "♬~~♫~~♪~~♫~~♪~~♫~~\n小小的女孩在路上太久太久啦，孤獨壓在她的肩膀上，思念蠶食著她的心。\n她在哪裡都找不到，每一個辦法都不奏效。\n♬~~♫~~♪~~♫~~♪~~♫~~\n沒關係，沒關係，女孩想找的一切都在鏡子裡，鏡子映照著天上的月亮，月亮落入了鏡中的漣漪。"
  },
  Stage_141751_Name = {
    Text = "鏡子·之一"
  },
  Stage_141752_Desc = {
    Text = "其他的事情我們都清楚，但王冠為什麼會在這個地方出現？？是誰這麼不小心，著了騙子的道？\n這顯然不是這部分我們要考慮的內容，欲知後事如何……\n下一個故事的時候再解釋吧！"
  },
  Stage_141753_Desc = {
    Text = "故事進行到這裡，你開始有一些躊躇。\n線索明明在一開始已經出現，命運牽引你來見證什麼呢？絲線的彼端，連接著什麼樣的真相呢？\n雪下面埋藏著什麼，到底有幾個人能夠所願得償？\n你不知道，旅途還未過半，你只能繼續順應它的指引。"
  },
  Stage_141753_Name = {
    Text = "絲線·之二"
  },
  Stage_141754_Desc = {
    Text = "喜歡我的故事嗎？不喜歡？誒？！到底要怎麼說你才會相信嘛，好啦，不要再追根究底啦，那樣會很讓人傷心的哦？\n來咬一口這個蘋果吧，超級甜，我保證是真的！\n就和這個故事裡的每一個字一樣真！"
