    Text = "其他的事情我們都清楚，但王冠為什麼會在這個地方出現？？是誰這麼不小心，著了騙子的道？\n這顯然不是這部分我們要考慮的內容，欲知後事如何……\n下一個故事的時候再解釋吧！"
  },
  Stage_141788_Desc = {
    Text = "是的，是的，人是可以倒霉到這個地步的。\n她的一生除了謊言什麼都沒有，她這一次相信，下一次依舊，她就因為一點點希望，吞下了所有謊言的苦果。\n所以在這場謊言的盡頭，在她一生的盡頭……\n我們在她的眼睛裡，除了仇恨，什麼都找不到。"
  },
  Stage_141789_Desc = {
    Text = "♬~~♫~~♪~~♫~~♪~~♫~~\n小小的女孩在路上太久太久啦，孤獨壓在她的肩膀上，思念蠶食著她的心。\n她在哪裡都找不到，每一個辦法都不奏效。\n♬~~♫~~♪~~♫~~♪~~♫~~\n沒關係，沒關係，女孩想找的一切都在鏡子裡，鏡子映照著天上的月亮，月亮落入了鏡中的漣漪。"
  },
  Stage_141789_Name = {
    Text = "鏡子·之四"
  },
  Stage_141790_Desc = {
    Text = "♬~~♫~~♪~~♫~~♪~~♫~~\n有一隻尋找同伴的孤號鳥，他的同伴失去了翅膀，他的同伴被拔光了羽毛。\n他試圖實現實現不了的願望，他的同伴連與他的回憶都忘掉。\n ♬~~♫~~♪~~♫~~♪~~♫~~\n沒關係，沒關係。他們還有甜美的、甜美的、共同的歸宿。他們會進入安寧的、安寧的、永不被打擾的夢鄉。"
  },
  Stage_142924_Desc = {
    Text = "模擬戰鬥"
  },
  Stage_142924_Name = {
    Text = "模擬戰測試"
  },
  Stage_143314_Desc = {
    Text = "他在她身上犯了一個錯誤。\n他在他身上絕不會犯同樣的錯誤。"
  },
  Stage_143315_Desc = {
    Text = "他在她身上犯了一個錯誤。\n他在他身上絕不會犯同樣的錯誤。"
  },
  Stage_143876_Desc = {
    Text = "如何成為傳奇調查員？首先，每一口深井都藏著許許多多的秘密。\n其次，闖進井底之前，記得散彈槍並不一定非得合法持有。"
  },
  Stage_143877_Desc = {
    Text = "人要上學，喚醒體也要上學。\n現在她是喚醒體了，她當然也要上學。\n請務必注意安全。"
  },
  Stage_143877_Name = {
    Text = "學校·之六"
  },
  Stage_143878_Desc = {
    Text = "沒錯，即便是傳奇調查員，也未必每次都能獲得勝利。\n……但沒關係，伏特加還剩最後一滴。"
  },
  Stage_143878_Name = {
    Text = "最後的小酌·之六"
  },
  Stage_143879_Desc = {
    Text = "世界會在頃刻之間變成煉獄——果真如此嗎？\n有沒有可能它從來沒有過任何變化，只不過在此之前，你一直在忍耐。"
  },
