    Text = "臨時文本"
  },
  Stage_145312_Desc = {
    Text = "歡迎！歡迎來到星天之鯨的鬥獸場！歡迎來到這座殺戮的殿堂！\n將軍，刺客，賞金獵人，角鬥士……所有活著的傳奇都在此相聚。\n廝殺，結盟，背叛，用盡你所有的手段吧，倖存者。\n規則只有一條： 只有最後站著的那個人，才能推開那扇門。"
  },
  Stage_145312_Name = {
    Text = "殺戮殿堂·之四"
  },
  Stage_145313_Desc = {
    Text = "榮譽、公正、尊嚴……這些都是弱者為自己編織的鎖鏈。\n她只對更強的東西感興趣。在這座血色的鬥獸場裡，值得她莊重以待的，或許尚有一個。"
  },
  Stage_145314_Desc = {
    Text = "取悅星天之鯨的方法非常簡單：足夠多的血，足夠強大的力量，足夠強烈的欲望……\n當你踏過千萬人的屍骨，恭喜你，你獲得了資格，來參與這場角逐。"
  },
  Stage_145314_Name = {
    Text = "覲獻·之三"
  },
  Stage_145315_Desc = {
    Text = "歡迎！歡迎來到星天之鯨的鬥獸場！歡迎來到這座殺戮的殿堂！\n將軍，刺客，賞金獵人，角鬥士……所有活著的傳奇都在此相聚。\n廝殺，結盟，背叛，用盡你所有的手段吧，倖存者。\n規則只有一條： 只有最後站著的那個人，才能推開那扇門。"
  },
