    Text = "殺戮殿堂·之三"
  },
  Stage_145316_Desc = {
    Text = "取悅星天之鯨的方法非常簡單：足夠多的血，足夠強大的力量，足夠強烈的欲望……\n當你踏過千萬人的屍骨，恭喜你，你獲得了資格，來參與這場角逐。"
  },
  Stage_145316_Name = {
    Text = "覲獻·之一"
  },
  Stage_145317_Desc = {
    Text = "在所有的危險裡，猛獸是最溫柔的一環。"
  },
  Stage_145317_Name = {
    Text = "困獸·之五"
  },
  Stage_145318_Desc = {
    Text = "終於，你得到了你想要的一切。力量，財富，榮耀，永不枯竭的權力。\n鮮血自王冠落下，染紅你的雙眼。痛快地歡笑吧，偉大的新王。在這權慾的鮮血裡，等待你注定到來的腐爛。"
  },
