  Stage_145320_Name = {
    Text = "權慾王冠·之六"
  },
  Stage_145321_Desc = {
    Text = "歡迎！歡迎來到星天之鯨的鬥獸場！歡迎來到這座殺戮的殿堂！\n將軍，刺客，賞金獵人，角鬥士……所有活著的傳奇都在此相聚。\n廝殺，結盟，背叛，用盡你所有的手段吧，倖存者。\n規則只有一條： 只有最後站著的那個人，才能推開那扇門。"
  },
  Stage_145321_Name = {
    Text = "殺戮殿堂·之五"
  },
  Stage_145322_Desc = {
    Text = "終於，你得到了你想要的一切。力量，財富，榮耀，永不枯竭的權力。\n鮮血自王冠落下，染紅你的雙眼。痛快地歡笑吧，偉大的新王。在這權慾的鮮血裡，等待你注定到來的腐爛。"
  },
  Stage_145322_Name = {
    Text = "權慾王冠·之五"
  },
  Stage_145323_Desc = {
    Text = "匐下你的身軀，低下你的頭顱。\n那是螻蟻面對神明時，唯一得體的姿勢。"
  },
  Stage_145323_Name = {Text = "螻蟻"},
  Stage_145324_Desc = {
    Text = "她的身後一無所有，她的前方永無盡頭。她慶幸如此。"
  },
  Stage_145324_Name = {
    Text = "王冠之輕"
  },
  Stage_145325_Desc = {
    Text = "你站在鏡子面前，看到你最深愛的那個人。父母，孩子，摯友，或是自己……\n愛，利維坦憎惡這個詞。代行者的靈魂不容一絲累贅。\n舉起刀，殺了它。 \n從此你將再無軟肋。\n從此你將再無歸途。"
  },
