  Stage_145354_Name = {
    Text = "覲獻·之六"
  },
  Stage_146229_Desc = {
    Text = "入席者已齊，沉睡的神明終於發出笑聲。\n你們從來不是赴宴的賓客。"
  },
  Stage_146230_Desc = {
    Text = "雪山只有一條規矩：無論你聽見什麼，不要回答。"
  },
  Stage_146231_Desc = {
    Text = "七枚祭品，七座基座，一扇通往世界原點的門。\n願望從來不是免費的饋贈。"
  },
  Stage_146231_Name = {
    Text = "無願的尖峰"
  },
  Stage_146232_Desc = {
    Text = "飛鳥終於尋回另一隻飛鳥。\n今日遠行，不問歸期。"
  },
  Stage_146232_Name = {
    Text = "飛鳥今日遠行"
  },
  Stage_146233_Desc = {
    Text = "澄澈的湖面倒映星空，也倒映那些不願被承認的渴望。\n謊言被投入火中，留下的未必就是真相。"
  },
  Stage_146233_Name = {
    Text = "未凍的月亮"
  },
  Stage_146234_Desc = {
    Text = "傳說中，冥王叮嚀俄耳普斯，萬勿回頭，回頭則永失愛妻。\n但他若忍心無視愛人的呼喚，又怎麼會為了苦苦尋她，抱著琴渡過死河、穿越幽谷，走入黑暗的冥府？"
  },
  Stage_146235_Desc = {
    Text = "風雪封住了來路，也送來一位陌生的旅伴。\n黑暗深處窸窣作響，彷彿整座雪山正在窺視誤入其中的人們。"
  },
  Stage_146236_Desc = {
    Text = "隨行者亦是先行者，她比你們更早抵達雪線之上。\n直面吧，從最開始，那就是無法逃離的存在。"
  },
  Stage_146237_Desc = {
    Text = "斗篷被風雪掀開，藏匿已久的秘密終於振翅。\n有些羽翼生來並非為了飛翔。"
  },
  Stage_146237_Name = {Text = "離巢日"},
  Stage_146238_Desc = {
    Text = "風雪封住了來路，也送來一位陌生的旅伴。\n黑暗深處窸窣作響，彷彿整座雪山正在窺視誤入其中的人們。"
  },
  Stage_146239_Desc = {
    Text = "人們清點食物、燃料、繩索與氧氣，卻沒有人稱量過藏在行囊裡的願望。"
  },
  Stage_146240_Desc = {
    Text = "火光照亮眾人的面孔，也照亮他們各自懷藏的願望。\n長夜未盡之時，就讓我們再享一寢安歇。"
  },
  Stage_146240_Name = {
    Text = "圍爐夜話"
  },
  Stage_146241_Desc = {
    Text = "不要溫和地走入那個良夜。"
  },
  Stage_146242_Desc = {
    Text = "隨行者亦是先行者，她比你們更早抵達雪線之上。\n直面吧，從最開始，那就是無法逃離的存在。"
  },
  Stage_146243_Desc = {
    Text = "真話不能剖開神明的腹腔。\n於是騙子與受騙者圍坐在黑暗裡，共同編織一個撕裂歸途的謊言。"
  },
  Stage_146243_Name = {
    Text = "謊言同盟"
  },
