  Stage_146928_Desc = {
    Text = "落難公主被騎士拯救，這是一個家喻戶曉的傳統故事。"
  },
  Stage_146929_Desc = {
    Text = "巨龍甦醒，仇恨再度激起。野獸的氣息從岩石中噴湧而出，戰爭的毒液熊熊燃燒，至今未熄。\n大地轟然雷鳴。"
  },
  Stage_146929_Name = {Text = "龍巢"},
  Stage_146930_Desc = {
    Text = "騎士走上了陌生的道路，行過荒蕪的原野與山丘，唯有影子相隨。\n或許他早已死去，然而無人作證，便也忘記。\n世界是如此悄無聲息。"
  },
  Stage_146930_Name = {Text = "墓塚"},
  Stage_146931_Desc = {
    Text = "四十晝夜的大雨降在地上，我們無法繼續，我們仍將繼續。"
  },
  Stage_146931_Name = {Text = "蘋果島"},
  Stage_146932_Desc = {
    Text = "巨龍甦醒，仇恨再度激起。野獸的氣息從岩石中噴湧而出，戰爭的毒液熊熊燃燒，至今未熄。\n大地轟然雷鳴。"
  },
  Stage_146932_Name = {Text = "龍巢"},
  Stage_146933_Desc = {
    Text = "那是天堂花園的根與花，是世間一切願望的冠冕，永不枯竭的豐足。\n飲下杯中酒吧，你會看見你最渴望的東西。"
  },
  Stage_146933_Name = {Text = "聖杯"},
  Stage_146934_Desc = {
    Text = "巨龍甦醒，仇恨再度激起。野獸的氣息從岩石中噴湧而出，戰爭的毒液熊熊燃燒，至今未熄。\n大地轟然雷鳴。"
  },
  Stage_146934_Name = {Text = "龍巢"},
