  },
  Stage_148732_Name = {
    Text = "負誓·奧吉爾試玩關卡"
  },
  Stage_20089_Desc = {
    Text = "她履行了自己的諾言，你們終於可以一起回家了。"
  },
  Stage_20089_Name = {Text = "黃金頭"},
  Stage_20090_Desc = {
    Text = "沙龍展是西岱最重要的藝術盛會。\n在這裡，籍籍無名者渴望成功，功成名就者渴望永恆。"
  },
  Stage_20092_Desc = {
    Text = "恩斯特·克勞岱爾曾是貝桑松的領主。\n直到今天，這個家族依舊在當地富有名望。"
  },
  Stage_20092_Name = {
    Text = "見信如唔"
  },
  Stage_20426_Desc = {
    Text = "結局終究已經註定，無論你如何嘗試，她如何掙扎，過去都無法改變。"
  },
  Stage_20426_Name = {
    Text = "絢爛的終局"
  },
  Stage_20427_Desc = {
    Text = "夢境不會永遠美滿，正如美妙的歌謠不會永遠奏響。"
  },
  Stage_20427_Name = {
    Text = "曲終人散"
  },
  Stage_20428_Desc = {
    Text = "國王被禁錮在高高的王座裡。\n世界在變，唯有他的悲傷始終如一。"
  },
  Stage_20428_Name = {Text = "她的國"},
  Stage_20429_Desc = {
    Text = "她漫無目的地行走在記憶的切片裡。\n無所知，無所感，周而復始……"
  },
  Stage_20429_Name = {
    Text = "記憶屏障"
  },
  Stage_20430_Desc = {
    Text = "迷宮的盡頭是什麼？白晝、黑夜，還是無邊無際的虛無？\n她需要自己找到答案。"
  },
  Stage_20430_Name = {
    Text = "迷宮的盡頭"
  },
  Stage_20431_Desc = {
    Text = "子嗣，更多的子嗣，源源不斷的子嗣……\n它們是她唯一的愛人。"
  },
  Stage_20431_Name = {
    Text = "意識集群"
  },
  Stage_20432_Desc = {
    Text = "永遠不要打開不屬於你的那扇門……"
  },
  Stage_20432_Name = {Text = "門"},
  Stage_20433_Desc = {
    Text = "夢境不會永遠美滿，正如美妙的歌謠不會永遠奏響。"
  },
  Stage_20433_Name = {
    Text = "曲終人散"
  },
  Stage_20434_Desc = {
    Text = "恩斯特·克勞岱爾曾是貝桑松的領主。\n直到今天，這個家族依舊在當地富有名望。"
  },
  Stage_20434_Name = {
    Text = "見信如唔"
  },
  Stage_20435_Desc = {
    Text = "他已經做了所有能做的，接下來，就讓時間去譜寫新的歌謠。"
  },
  Stage_20435_Name = {
    Text = "新的歌謠"
  },
  Stage_20436_Desc = {
    Text = "一段令人懷念的記憶，還是一場無法遺忘的夢境？"
  },
  Stage_20436_Name = {
    Text = "過往的絲線"
  },
  Stage_20437_Desc = {
    Text = "子嗣，更多的子嗣，源源不斷的子嗣……\n它們是她唯一的愛人。"
  },
  Stage_20437_Name = {
    Text = "意識集群"
  },
  Stage_20438_Desc = {
    Text = "夢境不會永遠美滿，正如美妙的歌謠不會永遠奏響。"
  },
  Stage_20438_Name = {
    Text = "曲終人散"
  },
  Stage_20439_Desc = {
    Text = "這是你們之間的秘密，它將烙印在靈魂上，伴隨永世。"
  },
  Stage_20439_Name = {
    Text = "夢，或理想"
  },
  Stage_20440_Desc = {
    Text = "爆炸後的世界一片黑暗，你在精神世界中徘徊，不知道等著你和艾瑞卡的究竟是什麼。"
  },
  Stage_20440_Name = {
    Text = "聲音如是說"
  },
  Stage_20441_Desc = {
    Text = "又一個夢境，又一段過去——這一次，你看到的是擁有血肉之軀的艾瑞卡。"
  },
  Stage_20441_Name = {
    Text = "啟動測試"
  },
  Stage_20442_Desc = {
    Text = "爆炸後的世界一片黑暗，你在精神世界中徘徊，不知道等著你和艾瑞卡的究竟是什麼。"
  },
