  },
  Stage_20444_Desc = {
    Text = "恩斯特·克勞岱爾曾是貝桑松的領主。\n直到今天，這個家族依舊在當地富有名望。"
  },
  Stage_20444_Name = {
    Text = "見信如唔"
  },
  Stage_20445_Desc = {
    Text = "子嗣，更多的子嗣，源源不斷的子嗣……\n它們是她唯一的愛人。"
  },
  Stage_20445_Name = {
    Text = "意識集群"
  },
  Stage_20697_Desc = {
    Text = "每時每刻都有一個人死去，正如每時每刻都有一個人誕生。\n唯有影子是不同的。它被時間吞噬，被這片苦難的大地束縛。\n生生世世，不死，不生。"
  },
  Stage_20697_Name = {
    Text = "影子頌歌"
  },
  Stage_20698_Desc = {
    Text = "神說，他們生來便該歷經苦難，流盡鮮血。\n就像太陽本該升起，雨水本該墜落。\n一切都是最好的安排。"
  },
  Stage_20699_Desc = {
    Text = "我們前進，是為了勝利的凱旋。\n我們活著，是為了完美的死去。"
  },
  Stage_20699_Name = {
    Text = "來自遠方"
  },
  Stage_20700_Desc = {
    Text = "它是這裡唯一的活物，它所見的一切由它統治。\n——它是至高無上的國王。"
  },
  Stage_20700_Name = {
    Text = "野獸王國"
  },
  Stage_20701_Desc = {
    Text = "他們跨越生死，隔著墓碑再度重逢。\n臉貼著臉，手握著手，呼吸間都是腐爛的味道。"
  },
  Stage_20701_Name = {
    Text = "孤獨的重逢"
  },
  Stage_20702_Desc = {
    Text = "我們是蟲豸、骨頭與眼淚的集合。\n今夜我們在此相聚，隻為一見那流淌著無數彩虹的河流。"
  },
  Stage_20702_Name = {
    Text = "獵顱集會"
  },
  Stage_20703_Desc = {
    Text = "當影子潛入黑夜，水滴匯入雨水。\n屬於獵殺的時刻即將來臨……"
  },
  Stage_20703_Name = {
    Text = "暴雨將至"
  },
  Stage_20704_Desc = {
    Text = "他們跨越生死，隔著墓碑再度重逢。\n臉貼著臉，手握著手，呼吸間都是腐爛的味道。"
  },
