  Stage_20711_Desc = {
    Text = "嚴格意義來講，這並非一出悲劇。\n戰士的字典裡沒有「悲劇」。"
  },
  Stage_20711_Name = {
    Text = "悲劇的謝幕"
  },
  Stage_20712_Desc = {
    Text = "沙龍展是西岱最重要的藝術盛會。\n在這裡，籍籍無名者渴望成功，功成名就者渴望永恆。"
  },
  Stage_20713_Desc = {
    Text = "迷宮的盡頭是什麼？白晝、黑夜，還是無邊無際的虛無？\n她需要自己找到答案。"
  },
