  Stage_21373_Desc = {
    Text = "索納尼爾號曾以倫蒂尼恩為母港，淹沒在絡繹來往的船隻中。\n在風暴中失去音訊後，它徹底從俗世視野中消失，只留下隻言片語的傳說。"
  },
  Stage_21374_Desc = {
    Text = "索納尼爾號曾以倫蒂尼恩為母港，淹沒在絡繹來往的船隻中。\n在風暴中失去音訊後，它徹底從俗世視野中消失，只留下隻言片語的傳說。"
