  },
  Stage_22313_Desc = {
    Text = "潮水回流，記憶倒灌。\n滿月升起前的一切，都睜開了眼。"
  },
  Stage_22313_Name = {Text = "睜開眼"},
  Stage_23624_Desc = {
    Text = "有些人生來便是冒險題材，有些人則把自己包裝成了唯美的愛情。\n不過說到底，每個人都是自己的導演。"
  },
  Stage_23624_Name = {
    Text = "安迪·約翰遜之力"
  },
  Stage_23625_Desc = {
    Text = "每個人都藏著故事，但不是每個人都有講述的欲望。"
  },
  Stage_23625_Name = {
    Text = "尋找故事"
  },
  Stage_23626_Desc = {
    Text = "以物易物，天經地義。"
  },
  Stage_23627_Desc = {
    Text = "最懷念的人，帶來了最想說出口的願望。"
  },
  Stage_23627_Name = {
    Text = "最懷念的人"
  },
  Stage_23628_Desc = {
