    Text = "「門」已被開啟，幻夢即將清醒。\n噓……不可注視，不可諦聽。"
  },
  Stage_23656_Name = {
    Text = "深海之遺·輪轉間隙Ⅳ"
  },
  Stage_23657_Desc = {
    Text = "「門」已被開啟，幻夢即將清醒。\n噓……不可注視，不可諦聽。"
  },
  Stage_23657_Name = {
    Text = "深海之遺·輪轉間隙Ⅲ"
  },
  Stage_23658_Desc = {
    Text = "「門」即將開啟，你從中窺見一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是渾濁的。"
  },
