  Stage_23662_Name = {
    Text = "血肉之沼·輪轉間隙Ⅳ"
  },
  Stage_24183_Name = {
    Text = "紅夫人試玩關卡"
  },
  Stage_24184_Name = {
    Text = "淤泥之花試玩關卡"
  },
  Stage_24423_Desc = {
    Text = "每個倫蒂尼恩人都不會拒絕一杯新鮮沏好的熱茶。\n哪怕那是一杯七鰓鰻烏龍茶。"
  },
  Stage_24423_Name = {
    Text = "七鰓鰻特調"
  },
  Stage_24424_Desc = {
    Text = "每個被命運選中的人都認為自己是那個例外。\n命運嘲笑機率。"
  },
  Stage_24424_Name = {
    Text = "命運的囚者"
  },
  Stage_24425_Desc = {
    Text = "哢嚓。\n她發誓與過去的生活一刀兩斷。\n就像用剪子把一根飾帶一刀剪成兩截。"
  },
  Stage_24425_Name = {
    Text = "獻給索蕾爾"
  },
  Stage_24426_Desc = {
    Text = "又一次，你成為同情的俘虜，狠狠墮入她的靈魂。"
  },
  Stage_24426_Name = {
    Text = "墜落的審判"
  },
  Stage_24427_Desc = {
    Text = "故事之初，你將見證一場華麗的死亡。\n它雖是開端，卻遠非結束。"
  },
  Stage_24427_Name = {Text = "飲酒歌"},
  Stage_24428_Desc = {
    Text = "女孩名為索蕾爾，是全村的驕傲。\n她很聽話、愛乾淨，一身雪白色，邁著小步，活像那些真正的淑女。\n女孩和那些淑女不同——她從不做夢。"
  },
  Stage_24429_Desc = {
    Text = "邏輯就像威士卡，攝入太多就失去它的益處了。"
  },
  Stage_24429_Name = {
    Text = "假面和聲"
  },
  Stage_24430_Desc = {
    Text = "在祂的悉心養護下，名為權欲的癌細胞終於像薔薇開放一樣擴散開來。"
  },
  Stage_24430_Name = {
    Text = "紅色慶典"
  },
  Stage_24431_Desc = {
    Text = "吸溜。吸溜。\n我們陰暗蠕動，我們竊竊私語。\n肥胖的身軀在月光下拖出彎彎的淚痕——鹹鹹的哦。"
  },
  Stage_24432_Desc = {
    Text = "司康餅、馬卡龍，還有冒著熱氣的可可……\n侍女的心願很簡單：吃得好一點，再好一點。"
  },
  Stage_24432_Name = {
    Text = "侍女的心願"
  },
  Stage_24433_Desc = {
    Text = "當心，當心。\n你們為之傾倒的那位夫人，可不是什麼真正的淑女。\n不過，誰在乎呢？"
  },
  Stage_24434_Desc = {
    Text = "薔薇在鐘聲裡垂下纖瘦的頭顱，禿鷲迷失在腥臭的花叢中。\n無人歌唱，無人訴說。世界因她的死而褪色。"
  },
  Stage_24434_Name = {
    Text = "薔薇的葬禮"
  },
  Stage_24435_Desc = {
    Text = "她汲乾泉水，扼殺純真的鳥兒。\n她帶來金色的風，它們像流星掠過原野。\n她將整個世界置於欲望的火焰上，又將它化為灰燼。"
  },
  Stage_24439_Desc = {
    Text = "當心，當心。\n你們為之傾倒的那位夫人，可不是什麼真正的淑女。\n不過，誰在乎呢？"
  },
