  },
  Stage_24456_Name = {
    Text = "假面和聲"
  },
  Stage_24528_Desc = {
    Text = "不論發生什麼，不論經過多少改變，你的呼喚總會被聽見。"
  },
  Stage_24528_Name = {
    Text = "這不是永別"
  },
  Stage_24529_Desc = {
    Text = "一次，兩次，三次……西西弗斯推著巨石，徒勞地攀登著不可能越過的高山。"
  },
  Stage_24530_Desc = {
    Text = "熟悉的少女變得如此陌生，這個冷漠的人……真的是你認識的拉蒙娜嗎？"
  },
  Stage_24530_Name = {
    Text = "孤注一擲"
  },
  Stage_24531_Desc = {
    Text = "尋常的一天，從不同尋常的夢境開始。"
  },
  Stage_24531_Name = {
    Text = "似雨之淚"
  },
  Stage_24532_Desc = {
    Text = "熟悉的少女變得如此陌生，這個冷漠的人……真的是你認識的拉蒙娜嗎？"
  },
  Stage_24532_Name = {
    Text = "孤注一擲"
  },
  Stage_24533_Desc = {
    Text = "熟悉的少女變得如此陌生，這個冷漠的人……真的是你認識的拉蒙娜嗎？"
  },
  Stage_24533_Name = {
    Text = "孤注一擲"
  },
  Stage_34716_Desc = {
    Text = "急轉直下，突發情節，故事突變——守密人感覺，這似乎在描述有時的自己。"
  },
  Stage_34716_Name = {
    Text = "Ⅲ·情節輪轉"
  },
  Stage_34717_Desc = {
    Text = "這是一個連拉蒙娜都沒有聽過的詞，在某些年邁喚醒體的幫助下，大家才終於明白：有時候，大哭一場才是處理壞情緒的唯一方法。"
  },
  Stage_34718_Desc = {
    Text = "卡茜亞找到的理論書中如此寫道：故事發生的時間不能超過一天，舞臺也不能超過一處……\n守密人聽到這裡時，就放棄了繼續讀下去。畢竟，一天的時間，有時還不夠守密人完成一次「融蝕與災厄處理」的課後作業論文。"
  },
  Stage_34719_Desc = {
    Text = "在卡茜亞找到的理論書中寫道：金字塔模型往往著眼於一場危機的解決。\n但是很可惜，不是每場危機都能在現實中得到解決。它們被和平假像所隱瞞、掩蓋，在暗中滋生，最後爆發為新的「金字塔」。"
  },
  Stage_34719_Name = {
    Text = "Ⅶ·劇作金字塔"
  },
  Stage_34720_Desc = {
    Text = "在故事的結尾，需要體現角色的發展或者變化。可是在生活中，弧光往往會連成一個圓。"
  },
  Stage_34720_Name = {
    Text = "Ⅵ·弧光理論"
  },
  Stage_34721_Desc = {
    Text = "一個提前設定好的場景，幾個互相熟識的演員。剩下的，就交給靈感與碰撞。"
  },
  Stage_34721_Name = {
    Text = "Ⅴ·假面喜劇"
  },
  Stage_34722_Desc = {
    Text = "不要每時每刻都用內容轟炸觀眾的腦子，要給他們留下思考空間，最好是完全靜止的——真希望朵爾在上課時能熟練運用這種技巧，守密人這麼呢喃著，得到了所有人的認同。"
  },
  Stage_34722_Name = {
    Text = "Ⅳ·靜場時刻"
  },
  Stage_34912_Desc = {
    Text = "舊日災厄於此刻蘇生，跨越現世的界碑，引燃墮落的汪洋。"
  },
  Stage_34912_Name = {
    Text = "融災禁區·第1波·Ⅲ級警報"
  },
