  },
  Stage_35099_Desc = {
    Text = "「噓……你猜，我透過你的眼睛看見了什麼？」\n在奧瑞塔被守密人嚇哭以後，守密人房間的第四面牆差點被蘿坦推倒，因為奧瑞塔哭得實在是太讓人心慌了。"
  },
  Stage_35099_Name = {
    Text = "Ⅸ·戲劇的第四壁"
  },
  Stage_35100_Desc = {
    Text = "「不要讓觀眾全身心沉浸在劇情中，要讓他們分析、批判舞臺上正在發生的事情。」\n對這條理論，奧瑞塔如此評價：奧瑞塔不想要被任何人罵！奧瑞塔只想和大家成為好朋友！"
  },
  Stage_35129_Desc = {
    Text = "她是夢境與現實交錯的界限，是每個仰望夜空的靈魂內心深處的反射。"
  },
  Stage_35129_Name = {
    Text = "倒錯的群星"
  },
  Stage_35129_StageInitStateText = {Text = "海魘"},
  Stage_35130_Desc = {
    Text = "她準備好了。"
  },
  Stage_35130_Name = {
    Text = "內化的火苗"
  },
  Stage_35571_Desc = {
    Text = "因為你是奧瑞塔的朋友，所以她要帶你認識她所有的朋友。"
  },
  Stage_35572_Desc = {
    Text = "因為你是奧瑞塔的朋友，所以她要帶你認識她所有的朋友。"
  },
  Stage_35573_Desc = {
    Text = "因為你是奧瑞塔的朋友，所以她要帶你認識她所有的朋友。"
  },
  Stage_35574_Desc = {
    Text = "奧瑞塔喜歡你，所以要你成為能夠加入她平凡一天的朋友。"
  },
  Stage_35574_Name = {
    Text = "寂靜的白日"
  },
  Stage_35575_Desc = {
    Text = "因為大家都陪在奧瑞塔身邊，所以奧瑞塔一點都不害怕睡著。"
  },
  Stage_35575_Name = {
    Text = "水裡的宮殿"
  },
  Stage_35843_Name = {
    Text = "深海淑女試玩關卡"
  },
  Stage_35857_Desc = {
    Text = "群星去向了它們應去之處，相互間以一種超脫於人類理解的方式交流，編織出一張看不見的網，捕捉著流動的時間和逝去的光年。"
  },
  Stage_35857_Name = {
    Text = "未知的星軌"
  },
  Stage_36125_Desc = {
    Text = "不被祝福的孩子在海中吟詠聖歌。\n噓……請保持安靜，切勿驚擾祂的長眠。"
  },
  Stage_36125_Name = {
    Text = "聖胎之詠Ⅲ"
  },
