  },
  Stage_36126_Name = {
    Text = "聖胎之詠Ⅱ"
  },
  Stage_36126_StageInitStateText = {Text = "海魘"},
  Stage_36127_Desc = {
    Text = "雷歐王國的北海，擁有溫和而平靜的仲夏。\n她的冬季看起來也淑靜典雅，但寧靜華美的霞雲之下，往往暗藏著致命的風暴。"
  },
