  },
  Stage_36620_Desc = {
    Text = "女王坐在高高的王座裡。\n陪伴她的有無盡的珍寶、財富，以及一點點沉沒的宇宙廢墟。"
  },
  Stage_36620_Name = {
    Text = "離群的女王"
  },
  Stage_36621_Desc = {
    Text = "災厄前，都城是她野心與欲望的延伸。\n災厄後，都城是黑夜與孤獨的囚籠。"
  },
  Stage_36887_Name = {
    Text = "荊棘女王試玩關卡"
  },
  Stage_38756_Desc = {
    Text = "她閉上雙眼，漫無目的地漂浮在宇宙的虛空裡。\n一年，一百年……終於有一天，她告訴自己：「沒關係。就由我來定義真假。」\n女王和她不朽的城池——伊薩拉烏，就這樣停留在宇宙的茫茫星河中。\n她將伊薩拉烏的故事告訴我，以便它被永遠銘記。"
  },
