  Stage_38769_Name = {
    Text = "海市蜃樓·追憶之四"
  },
  Stage_38770_Desc = {
    Text = "夜晚，女王站在宮殿露台上，凝望著數千英尺下的城池。\n日復一日，每當她想跨出宮殿一步，便會引來眩暈、眼淚、以及大片的記憶空白。\n「準備好了嗎？迎接這個世界的真實。」\n她深吸一口氣，從露台上跳了下去。"
  },
  Stage_38770_Name = {
    Text = "真實·追憶之一"
  },
  Stage_38771_Desc = {
    Text = "夜晚，女王站在宮殿露台上，凝望著數千英尺下的城池。\n日復一日，每當她想跨出宮殿一步，便會引來眩暈、眼淚、以及大片的記憶空白。\n「準備好了嗎？迎接這個世界的真實。」\n她深吸一口氣，從露台上跳了下去。"
  },
  Stage_38771_Name = {
    Text = "真實·追憶之三"
  },
  Stage_38772_Desc = {
    Text = "當她睜開雙眼的時候，世界正在因此而毀滅。\n所有的建築都坍塌了，黑色的粘液舔舐天空，白色的小蒼蘭消散在永恆的虛空裡。\n一切都很安靜。一切都像睡著了。\n只有眼淚是冰涼的，冷冷地貼在她的臉上，浸濕了她的髮梢。"
  },
