    Text = "黃金之城——伊薩拉烏。\n它的財富取之不竭，它的欲望無邊無界。\n它就像一塊海綿，吸汲著不斷湧流的黃金潮水，並隨之膨脹。\n這是我的都城，女王說。她為此而自豪。"
  },
  Stage_38790_Name = {
    Text = "黃金之城·追憶之二"
  },
  Stage_38791_Desc = {
    Text = "黃金之城——伊薩拉烏。\n它的財富取之不竭，它的欲望無邊無界。\n它就像一塊海綿，吸汲著不斷湧流的黃金潮水，並隨之膨脹。\n這是我的都城，女王說。她為此而自豪。"
  },
  Stage_38791_Name = {
    Text = "黃金之城·追憶之一"
  },
  Stage_38792_Desc = {
    Text = "當她睜開雙眼的時候，世界正在因此而毀滅。\n所有的建築都坍塌了，黑色的粘液舔舐天空，白色的小蒼蘭消散在永恆的虛空裡。\n一切都很安靜。一切都像睡著了。\n只有眼淚是冰涼的，冷冷地貼在她的臉上，浸濕了她的髮梢。"
  },
  Stage_38792_Name = {
    Text = "井·追憶之五"
  },
  Stage_38793_Desc = {
    Text = "女王和她不朽的城池——伊薩拉烏。\n宇宙眷顧的雙生子啊，你們被命運的臍帶輕輕纏繞。\n有人說，智慧的女王率領民眾來到伊薩拉烏，就像《啟示錄》裡所描繪的。\n也有人說，伊薩拉烏的河床終年湧動，直到將女王孕育而出。"
  },
