  Stage_38800_Desc = {
    Text = "當她睜開雙眼的時候，世界正在因此而毀滅。\n所有的建築都坍塌了，黑色的粘液舔舐天空，白色的小蒼蘭消散在永恆的虛空裡。\n一切都很安靜。一切都像睡著了。\n只有眼淚是冰涼的，冷冷地貼在她的臉上，浸濕了她的髮梢。"
  },
  Stage_38800_Name = {
    Text = "井·追憶之七"
  },
  Stage_38801_Desc = {
    Text = "「我什麼都沒有了。」瞎了一隻眼的流浪兒說，「只有這支花能獻給您，偉大的女王。」\n她接過白色的小蒼蘭，卻感到困惑。似乎這一幕曾無數次在她的記憶深處輪回。\n循環往復，就像困住米洛陶洛斯的迷宮。"
  },
  Stage_38801_Name = {
    Text = "小蒼蘭·追憶之七"
  },
  Stage_38802_Desc = {
    Text = "夜晚，女王站在宮殿露台上，凝望著數千英尺下的城池。\n日復一日，每當她想跨出宮殿一步，便會引來眩暈、眼淚、以及大片的記憶空白。\n「準備好了嗎？迎接這個世界的真實。」\n她深吸一口氣，從露台上跳了下去。"
  },
  Stage_38802_Name = {
    Text = "真實·追憶之二"
  },
