  Stage_43506_Desc = {
    Text = "永別了。巨人說。\n我要回到歷史裡，在那裡我戰無不勝、無堅不摧。\n我是不朽。"
  },
  Stage_43506_Name = {
    Text = "沉沒號角"
  },
  Stage_43508_Desc = {
    Text = "被時間遺忘的人啊，你要駛向何方？\n——去到那遙遠的無依之地。那裡星月靜寂，海洋無聲。\n世界只剩你和我。"
  },
  Stage_43508_Name = {
    Text = "無依之海"
  },
