    Text = "那些讓他們受益的才是好的，所有未能落在他們身上的祝福都是詛咒。\n「什麼賜福，分明是邪惡的血魔法！」\n「這一定是巫術，他是惡魔！」"
  },
  Stage_44227_Name = {
    Text = "指責·滋長之五"
  },
  Stage_44228_Desc = {
    Text = "對病痛的恐慌讓他們心有不甘。\n「憑什麼只給他賜福？我也生病了！」\n「我才是最嚴重的，我才應該第一個受祝！」"
  },
  Stage_44228_Name = {
    Text = "爭奪·滋長之三"
  },
