    Text = "爭奪·滋長之二"
  },
  Stage_44495_Desc = {
    Text = "漆黑的潮水漫過警戒界限，輕微的波動亦昭示著足以吞噬掉以輕心者的險惡。"
  },
  Stage_44495_Name = {
    Text = "融災禁區·第3波·Ⅰ級警報"
  },
  Stage_44496_Desc = {
    Text = "舊日災厄於此刻蘇生，跨越現世的界碑，引燃墮落的汪洋。"
