  Stage_44508_Name = {
    Text = "融災禁區·第5波·Ⅰ級警報"
  },
  Stage_44509_Desc = {
    Text = "漆黑的潮水漫過警戒界限，輕微的波動亦昭示著足以吞噬掉以輕心者的險惡。"
  },
  Stage_44509_Name = {
    Text = "融災禁區·第4波·Ⅰ級警報"
  },
  Stage_44551_Desc = {
    Text = "仁慈的父神，請寬恕我，讓我得以改過，讓我得以彌補我的過錯。"
  },
  Stage_44551_Name = {
    Text = "我們的過錯"
  },
  Stage_44552_Desc = {
    Text = "塵埃落定，那些有罪的將得到判決，那些前行的將繼續向前。\n明天又是新的一天。"
  },
  Stage_44553_Desc = {
    Text = "這本該是個尋常的下午，但對彌薩格的守密人來說，普通的日常顯然是個奢望。"
  },
  Stage_44553_Name = {Text = "悔過"},
  Stage_44554_Desc = {
    Text = "淨化、淨化……這究竟是一個瘋人的囈語，還是某種錯亂的信仰？"
  },
  Stage_44554_Name = {
    Text = "血腥的符號"
  },
  Stage_44555_Desc = {
    Text = "他們已經被火焰吞沒，失去理智。"
  },
  Stage_44555_Name = {
    Text = "因暴怒瘋狂"
  },
  Stage_44556_Desc = {
    Text = "旁人有的他們也要有，旁人沒有的他們更要有——不管多麼無謂，不管多麼荒唐。"
  },
  Stage_44556_Name = {
    Text = "為嫉妒殺戮"
  },
  Stage_44557_Desc = {
    Text = "停下吧，放鬆吧，你已經足夠操勞；躺下吧，安睡吧，沒有人忍心責怪。"
  },
  Stage_44557_Name = {
    Text = "向倦怠妥協"
  },
  Stage_44558_Desc = {
    Text = "你架著疲憊踏上來時的路，卻撞上饑餓的獠牙。"
  },
  Stage_44558_Name = {
    Text = "把飢腸填滿"
  },
  Stage_44559_Desc = {
    Text = "從鏡子裡看向你的，究竟是一個虛幻的影子，還是真實的欲望？"
  },
  Stage_44559_Name = {
    Text = "將罪惡淨化"
  },
  Stage_44560_Desc = {
    Text = "仁慈的父神，請寬恕我，讓我得以改過，讓我得以彌補我的過錯。"
  },
  Stage_44560_Name = {
    Text = "我們的過錯"
  },
  Stage_44561_Desc = {
    Text = "仁慈的父神，請寬恕我，讓我得以改過，讓我得以彌補我的過錯。"
  },
  Stage_44561_Name = {
    Text = "我們的過錯"
  },
  Stage_44715_Name = {
    Text = "仁愛主祭試玩關卡"
  },
  Stage_45411_Name = {Text = "吻別"},
  Stage_46169_Desc = {
    Text = "她將所有機率銘記於心，卻和經院的神學生一樣困惑。\n因為瘋狂無法預測，並且很不幸，它才是世界的常態。"
  },
  Stage_46169_Name = {
    Text = "滿貫定約"
  },
  Stage_46170_Desc = {
    Text = "她將所有機率銘記於心，卻和經院的神學生一樣困惑。\n因為瘋狂無法預測，並且很不幸，它才是世界的常態。"
  },
  Stage_46170_Name = {
    Text = "滿貫定約"
  },
  Stage_46171_Desc = {
    Text = "咒縛將你變成陷入永久冬眠的蛇類。\n它和你的臍帶一樣古老。"
  },
  Stage_46171_Name = {Text = "苦咒縛"},
  Stage_46172_Desc = {
    Text = "女孩曾是梅森。\n不久之後，她將像尤利西斯一樣，誰都不是。\n不久之後，她將是眾生。"
  },
  Stage_46173_Desc = {
    Text = "咒縛將你變成陷入永久冬眠的蛇類。\n它和你的臍帶一樣古老。"
  },
  Stage_46173_Name = {Text = "苦咒縛"},
  Stage_46174_Desc = {
    Text = "止於此，止於我。\n不可試探你的主。"
  },
  Stage_46174_Name = {Text = "止於此"},
  Stage_46175_Desc = {
    Text = "多年來，朝聖者們在雪山裡刻鑿出一條道路，拖拽住現實。\n他們靜止不動，張大著嘴，彷彿發出連綿的吼聲——"
  },
  Stage_46175_Name = {
    Text = "朝聖者之歌"
  },
  Stage_46176_Desc = {
    Text = "咒縛將你變成陷入永久冬眠的蛇類。\n它和你的臍帶一樣古老。"
  },
  Stage_46176_Name = {Text = "苦咒縛"},
  Stage_46177_Desc = {
    Text = "她將所有機率銘記於心，卻和經院的神學生一樣困惑。\n因為瘋狂無法預測。很不幸，它才是世界的常態。"
  },
  Stage_46177_Name = {
    Text = "滿貫定約"
  },
  Stage_46178_Desc = {
    Text = "她目睹著自己即將佔領世界。\n她注視著那道狹長的陰影，不發一言。"
  },
  Stage_46178_Name = {
    Text = "影子童話"
  },
  Stage_46179_Desc = {
    Text = "她的喜劇獨一無二。它們由無邊寂寥的黑夜、月亮和眼淚組成。"
  },
  Stage_46179_Name = {
    Text = "等待喜劇"
  },
  Stage_46180_Desc = {
    Text = "當萬物沉睡時，蛇會醒來。\n當一切都倒塌時，蛇將恢復原狀。"
  },
  Stage_46181_Desc = {
    Text = "貓咪將自己的情緒切割成一十八塊，併為它們發明了音調不同的「喵嗚」聲。\n這樣，它就能說「我餓了」「快陪我玩」「別打擾我」。\n也能說「我想你了」。"
  },
  Stage_46181_Name = {
    Text = "貓知曉一切"
  },
  Stage_46182_Desc = {
    Text = "伴隨老舊鐘聲響起的，是氣息微弱、不斷消弭的祝福。\n節日快樂。節日快樂。節日快樂。"
  },
  Stage_46182_Name = {
    Text = "金色賦格"
  },
  Stage_46259_Name = {
    Text = "渴血患者試玩關卡"
  },
  Stage_46260_Name = {
    Text = "沉淵者試玩關卡"
  },
  Stage_46261_Name = {
