  },
  Stage_46272_Name = {
    Text = "睡蓮試玩關卡"
  },
  Stage_46273_Name = {
    Text = "奇術師試玩關卡"
  },
  Stage_46274_Name = {
    Text = "竄行者試玩關卡"
  },
  Stage_46275_Name = {
    Text = "原初信徒試玩關卡"
  },
  Stage_46276_Name = {
    Text = "青炎舞者試玩關卡"
  },
  Stage_46277_Name = {
    Text = "空想利刃試玩關卡"
  },
  Stage_46278_Name = {
    Text = "凸月侍女試玩關卡"
  },
  Stage_46540_Desc = {
    Text = "她覺得有無數條蛇像網一樣纏住了自己。\n醒來後，一個影子站在她的床前。它說：\n「無論你到什麼地方，我都要抹掉你，正如你現在抹掉我的臉一樣。」"
  },
