  },
  Stage_46546_Desc = {
    Text = "她覺得有無數條蛇像網一樣纏住了自己。\n醒來後，一個影子站在她的床前。它說：\n「無論你到什麼地方，我都要抹掉你，正如你現在抹掉我的臉一樣。」"
  },
  Stage_46546_Name = {
    Text = "無意識記·湧現之二"
  },
  Stage_46547_Desc = {
    Text = "不知從何時起，她成為了這裡的法官。\n她審理一個隱掉名字的人，判了那人死刑。\n然後她才聽到揭示：「你就是那個人。」\n是的，這裡所有的犯人、法官和祭司都長著同一張臉。"
  },
  Stage_46547_Name = {
    Text = "杏仁體·湧現之四"
  },
  Stage_46548_Desc = {
    Text = "地獄是一個空房間，裡面擺放著無數鏡子。\n她不敢睜開雙眼，因為俯仰皆是她那張蒼白驚懼的臉。\n冥冥中，有個聲音在說：\n這是報應。你生前只有一具皮囊；死後遭報應時有無數具。"
  },
  Stage_46548_Name = {
    Text = "鏡子·湧現之六"
  },
  Stage_46549_Desc = {
    Text = "不知從何時起，她成為了這裡的法官。\n她審理一個隱掉名字的人，判了那人死刑。\n然後她才聽到揭示：「你就是那個人。」\n是的，這裡所有的犯人、法官和祭司都長著同一張臉。"
  },
