    Text = "杏仁體·湧現之三"
  },
  Stage_46551_Desc = {
    Text = "洪積315年12月@2日，她被宣佈為無形。\n她大聲呼喊，卻無人理睬；她偷麵包，卻不被抓住監禁。\n名為忘卻的疾病感染了所有人，唯獨將她遺漏。"
  },
