  Stage_48034_Desc = {
    Text = "水源是沙漠的血脈，綠洲是心臟泵出的河床。"
  },
  Stage_48034_Name = {Text = "綠洲"},
  Stage_48035_Desc = {
    Text = "母樹賜予亞蘭人生命，卻又吞噬亞蘭人的靈魂。"
  },
  Stage_48036_Desc = {
    Text = "黃沙隔絕了外界訊息的傳播，古老的文明得以在此流傳。\n亞蘭人世代生於此。"
  },
  Stage_48037_Desc = {
    Text = "亞蘭文明中，項鍊是戀人間定情的重要信物。"
  },
  Stage_48037_Name = {Text = "項鍊"},
  Stage_48038_Desc = {
    Text = "自樹而來，自源頭而來。"
  },
  Stage_48039_Desc = {
    Text = "注意留心棋盤對面的陰影。\n真正的對手，向來不在棋局之內。"
  },
  Stage_48039_Name = {Text = "對手"},
  Stage_48040_Desc = {
    Text = "曠古的遺骸，藏匿於文明的廢墟。"
  },
  Stage_48040_Name = {Text = "遺骸"},
  Stage_48041_Desc = {
    Text = "風暴如千古的野獸咆哮。"
  },
  Stage_48041_Name = {
    Text = "風暴之壁"
  },
  Stage_48042_Desc = {
    Text = "魔術只是障眼法。\n閉上雙眼就能破除。"
  },
