    Text = "授粉是遙遠的邂逅。\n花枝搖曳邀約共舞的使者，邀約它擷取花粉，流連花叢，在自然的律動中將新生命的源泉送入另一個等待的懷抱。"
  },
  Stage_49363_Name = {
    Text = "授粉·囈語之四"
  },
  Stage_49364_Desc = {
    Text = "授粉是遙遠的邂逅。\n花枝搖曳邀約共舞的使者，邀約它擷取花粉，流連花叢，在自然的律動中將新生命的源泉送入另一個等待的懷抱。"
  },
  Stage_49364_Name = {
    Text = "授粉·囈語之五"
  },
  Stage_49365_Desc = {
    Text = "落果是殘酷的預兆。\n越極端惡劣的環境，生存競爭到來得越早。在新的幼苗觸達大地之前，死亡已經如影隨形。"
  },
  Stage_49365_Name = {
    Text = "落果·囈語之一"
  },
  Stage_49366_Desc = {
    Text = "授粉是遙遠的邂逅。\n花枝搖曳邀約共舞的使者，邀約它擷取花粉，流連花叢，在自然的律動中將新生命的源泉送入另一個等待的懷抱。"
