  },
  Stage_49368_Name = {
    Text = "授粉·囈語之三"
  },
  Stage_49369_Desc = {
    Text = "幼根是莽撞的冒險。\n種子不知曉下一寸天地是豐沃的黑土，還是冰冷的荒沙，種子只是無垠無畏地伸出邁向大地的根梢。"
  },
  Stage_49369_Name = {
    Text = "幼根·囈語之一"
  },
  Stage_50345_Desc = {
    Text = "泰旖絲。\n如蛇般幽魅，如樹般古老，如沙般蒼茫。"
  },
  Stage_50345_Name = {Text = "泰旖絲"},
