  },
  Stage_51077_Desc = {
    Text = "「不要讓觀眾全身心沉浸在劇情中，要讓他們分析、批判舞臺上正在發生的事情。」\n對這條理論，奧瑞塔如此評價：奧瑞塔不想要被任何人罵！奧瑞塔只想和大家成為好朋友！"
  },
