  Stage_51099_Desc = {
    Text = "卡茜亞找到的理論書中如此寫道：故事發生的時間不能超過一天，舞臺也不能超過一處……\n守密人聽到這裡時，就放棄了繼續讀下去。畢竟，一天的時間，有時還不夠守密人完成一次「融蝕與災厄處理」的課後作業論文。"
  },
