  Stage_51646_Desc = {
    Text = "不可見的災難復甦，物理世界的歷史與存在正在墜入深淵。"
  },
  Stage_51646_Name = {
    Text = "融災禁區·第1波·Ⅳ級警報"
  },
  Stage_51761_Desc = {
    Text = "最後一次，她凝視王的雕像曾經矗立的地方。\n那裡沒有雕像，也沒有王。"
  },
  Stage_51761_Name = {
    Text = "夢歸利莫里亞"
  },
  Stage_51762_Desc = {
    Text = "雕像與她遙遙相望。他們之間隔著的，是漫長的時光，和未曾醒來的夢。"
  },
  Stage_51763_Desc = {
    Text = "希望，是利莫里亞最為珍貴的毒藥。\n他們狂歌痛飲，他們甘之如飴。"
  },
  Stage_51763_Name = {
    Text = "祭司之儀"
  },
  Stage_51764_Desc = {
    Text = "群星、命運、神明……在祂們面前，公平二字，不值一提。"
  },
  Stage_51764_Name = {
    Text = "謊言的美德"
  },
  Stage_51765_Desc = {
    Text = "在雨中掙扎。在雨中告別。"
  },
  Stage_51766_Desc = {
    Text = "回應我吧，吾主。我將為您，奉上最珍貴的獻禮。"
  },
  Stage_51766_Name = {
    Text = "王的獻禮"
  },
  Stage_51767_Desc = {
    Text = "享用吧，祂說。享用那些低賤的溫情，享用那被烹製好的命運。"
  },
  Stage_51767_Name = {Text = "魚肉"},
  Stage_51768_Desc = {
    Text = "祂的意志如星辰之網交織，祂在永恆的虛無中候汝入夢。"
  },
  Stage_51768_Name = {
    Text = "於深海禱告"
  },
  Stage_51769_Desc = {
    Text = "祈禱，是利莫里亞人學會的第一件事。"
  },
  Stage_51769_Name = {Text = "預言"},
  Stage_51770_Desc = {
    Text = "在那安寧極樂之地，昔日的摯友們互相凝望。\n他們將攜起對方的手，一同踏上通往神國的階梯。"
  },
  Stage_51770_Name = {Text = "摯友"},
  Stage_51771_Desc = {
    Text = "鮮血。眼淚。祭祀。狂歡。殺戮。\n又一段關於群星的故事開始了，而群星並不關心。\n它們閃耀著，亙古至今。"
  },
  Stage_51771_Name = {
    Text = "聆聽吧，群星"
  },
  Stage_51773_Desc = {
    Text = "喝吧，這甘美的酒。跳吧，這熱烈的舞。\n故國的主祭步入殿堂，撫摸她新的信徒。"
  },
  Stage_51774_Desc = {
    Text = "迷霧遮擋著求道者的面孔。迷霧遮擋著擁王者的心。"
  },
  Stage_51774_Name = {Text = "霧中人"},
  Stage_51775_Desc = {
    Text = "舊日的宮殿已成泡影，舊日的殘夢空留餘音。枯萎的王座上，只剩王的屍骸，仍在講述著古老的寓言。"
  },
  Stage_51775_Name = {
    Text = "舊日泡影"
  },
  Stage_51785_Desc = {
    Text = "不可見的災難復甦，物理世界的歷史與存在正在墜入深淵。"
  },
  Stage_51785_Name = {
    Text = "融災禁區·第1波·Ⅳ級警報"
