  },
  Stage_53376_Name = {
    Text = "融災禁區·第5波·Ⅳ級警報"
  },
  Stage_53775_Desc = {
    Text = "臨行前，傳記作家回望這棟薔薇盛開的美麗宅邸，它遠抵不上主人光芒的萬分之一。\n有關索蕾爾夫人的傳說還在繼續，就在此刻的當下發生，我們都將成為見證。"
  },
  Stage_53775_Name = {
    Text = "終曲·之二"
  },
  Stage_53776_Desc = {
    Text = "她有很多身分：名媛、商人、掮客、收藏家……\n唯獨沒有她自己——很遺憾，薔薇夫人從不為此失落。\n對她而言，原始的、未經雕琢的事物不值一提，複雜與渾濁才是最頂級的審美。"
  },
  Stage_53776_Name = {
    Text = "臉·之六"
  },
  Stage_53777_Desc = {
    Text = "她有很多身分：名媛、商人、掮客、收藏家……\n唯獨沒有她自己——很遺憾，薔薇夫人從不為此失落。\n對她而言，原始的、未經雕琢的事物不值一提，複雜與渾濁才是最頂級的審美。"
  },
