  Stage_53788_Desc = {
    Text = "那天晚上，她夢見了黑霧，夢見它有了生氣，在顫動。\n不是虎和馬的、難以形容的雜種，而兼有那兩種動物的性質。\n同時又是一隻黑貓、一朵薔薇、一場暴風雨。"
  },
  Stage_53788_Name = {
    Text = "薔薇角·之六"
  },
  Stage_53789_Desc = {
    Text = "美貌是無形的線，輕鬆捆住人們的心。她隨意地撥弄絲線，彷彿最漫不經心的天才。\n很快她便厭倦了這個遊戲，因為透過他們醜陋的面容，她窺見自身。"
  },
  Stage_53789_Name = {
    Text = "傀儡遊戲·之五"
  },
  Stage_53790_Desc = {
    Text = "臨行前，傳記作家回望這棟薔薇盛開的美麗宅邸，它遠抵不上主人光芒的萬分之一。\n有關索蕾爾夫人的傳說還在繼續，就在此刻的當下發生，我們都將成為見證。"
