  },
  Stage_53791_Desc = {
    Text = "美貌是無形的線，輕鬆捆住人們的心。她隨意地撥弄絲線，彷彿最漫不經心的天才。\n很快她便厭倦了這個遊戲，因為透過他們醜陋的面容，她窺見自身。"
  },
  Stage_53791_Name = {
    Text = "傀儡遊戲·之四"
  },
  Stage_53792_Desc = {
    Text = "她將按照劇本的指示，演完一場場劇碼，掀起無盡的混亂。\n而她，便是在風暴眼中翩翩起飛的舞者。\n她一向都是最敬業的演員。"
  },
