    Text = "傀儡遊戲·之二"
  },
  Stage_53816_Desc = {
    Text = "插花、刺繡、茶藝……她的生活由一串無意義的符號構成。\n「早安，索蕾爾小姐」「你真棒，索蕾爾小姐」……\n故作愉悅的聲音就像厚厚的魚缸，將她永遠圈養。"
