  },
  Stage_53821_Desc = {
    Text = "臨行前，傳記作家回望這棟薔薇盛開的美麗宅邸，它遠抵不上主人光芒的萬分之一。\n有關索蕾爾夫人的傳說還在繼續，就在此刻的當下發生，我們都將成為見證。"
