  },
  Stage_54558_Desc = {
    Text = "今日，利莫里亞將迎來新王。\n\n自此，一切天災將為之退避。"
  },
  Stage_54804_Desc = {
    Text = "「作為敘述者的我就是兇手」——真是老套的伎倆，毫無美感與技巧。\n很不幸，這次還是被我給撞見了。"
