  Stage_54819_Desc = {
    Text = "她無權決定自己胸腔中被植入的胚胎的歸屬。\n她無權決定向哪裡逃亡，無權決定牽住誰的手，無權決定和誰一起顛沛流離。\n在海上幻境浮浮沉沉的命運面前，誰都只是待宰的羔羊。"
  },
