  Stage_55139_Name = {
    Text = "執手·之三"
  },
  Stage_55140_Desc = {
    Text = "大火清空了一切，所有豔紅的花朵變成了紛飛在空中的灰屑。\n在土地的掩埋下，一卷詩稿靜靜旁觀著一切。\n它曾被怎樣的目光一遍遍翻閱呢？而如今落得蒙塵的境地。\n春天已逝，玫瑰亦被粗暴地拋棄了。\n玫瑰啊，可憐的玫瑰。"
  },
