  Stage_55143_Desc = {
    Text = "小小的花房是屬於她們的小小王國。\n在這渺小的王國裡，她們一無所有，她們甘之如飴。"
  },
  Stage_55143_Name = {
    Text = "渺小王國·之四"
  },
  Stage_55144_Desc = {
    Text = "風靡的詩篇帶來了一切，在好友的讚美中她羞紅了臉。自己的詩，終於能夠讓好友不再為自己受苦了。她這樣想著。\n然而她沒有聽到的是，惡毒的種子早已播種，只待將玫瑰緊緊纏繞、摧毀。"
  },
