  Stage_55167_Desc = {
    Text = "西岱是花與詩的城市，一首好詩能換一束鮮花。\n那是她的第一首詩，那是她種出的第一朵玫瑰。\n當手與手相碰之時，少女明媚的面龐比花與詩更加嬌豔。"
