  Stage_55391_Desc = {
    Text = "「讓我用第一朵玫瑰，換你的第一首詩吧。」"
  },
  Stage_55391_Name = {Text = "詩篇1843"},
  Stage_55392_Desc = {
    Text = "花園是一道謎題，玫瑰是她的答案。"
  },
  Stage_55392_Name = {Text = "餘香"},
  Stage_55393_Desc = {
    Text = "「讓我用第一朵玫瑰，換你的第一首詩吧。」"
  },
  Stage_55393_Name = {Text = "詩篇1843"},
  Stage_55394_Desc = {
    Text = "沒有哀悼，也沒有風。\n只有詩人的餘墨，為花園敲響的喪鐘。"
  },
  Stage_55394_Name = {
    Text = "花園挽歌"
  },
  Stage_55395_Desc = {
    Text = "雕像是國王的修辭，沉默是雕像的修辭。"
  },
  Stage_55395_Name = {
    Text = "雕像修辭學"
  },
  Stage_55396_Desc = {
    Text = "她們隔著花園對視。\n花園中有無數條屬於她們各自的路，每一條路都背道而馳。"
  },
  Stage_55396_Name = {
    Text = "小徑分叉的花園"
  },
  Stage_55397_Desc = {
    Text = "用第一場葬禮告別骸骨，用第二場葬禮告別歲月。"
  },
  Stage_55397_Name = {
    Text = "遲來的葬禮"
  },
  Stage_55398_Desc = {
    Text = "優秀的詩歌，會讓人身臨其境。\n古典的美學理論這樣介紹道。"
  },
  Stage_55398_Name = {Text = "詩中人"},
  Stage_55399_Desc = {
    Text = "西岱的繁花向您發來邀請，邀請您與它們一同走入這場夢境。"
  },
  Stage_55400_Desc = {
    Text = "所謂故鄉，不過是一段曠日持久的謊言。"
  },
  Stage_55400_Name = {Text = "故鄉"},
  Stage_55401_Desc = {
    Text = "「讓我用第一朵玫瑰，換你的第一首詩吧。」"
  },
  Stage_55401_Name = {Text = "詩篇1843"},
  Stage_55551_Desc = {
    Text = "這座雪山擁有生命，山間迴蕩著聲聲呼嘯，那是它在呼喚它的女兒。\n快來吧，快來吧。\n是女兒走向母親，還是母親走向女兒？\n雪山峰頂，兩幅空落落的胃袋終於相見。"
  },
  Stage_55551_Name = {
    Text = "見山·之三"
  },
