  Stage_55558_Name = {
    Text = "見山·之四"
  },
  Stage_55559_Desc = {
    Text = "鏡中的兩頭野獸相遇，它們互相露出獠牙。\n它們額頭相撞，誰都不肯認輸。\n狂妄的你，軟弱的我。\n雙手交疊那一刻，鏡子被打破。\n野獸發出低吼，露出猩紅雙眸。"
  },
  Stage_55559_Name = {
    Text = "鬥獸·之四"
  },
  Stage_55560_Desc = {
    Text = "雪山的凍土乾枯暗淡，滅絕一切生機。\n但生命的意志永遠頑強。\n只等雪山融化之時，冰涼的水滴落入土壤。\n一顆不屈的種子，立刻在山頂發芽。"
  },
  Stage_55561_Desc = {
    Text = "鏡中的兩頭野獸相遇，它們互相露出獠牙。\n它們額頭相撞，誰都不肯認輸。\n狂妄的你，軟弱的我。\n雙手交疊那一刻，鏡子被打破。\n野獸發出低吼，露出猩紅雙眸。"
  },
  Stage_55561_Name = {
    Text = "鬥獸·癲狂"
  },
  Stage_55562_Desc = {
    Text = "風與雪之間，有旅人踽踽走向純白的山巔。\n她是初次到訪的來客，也是回到故鄉的歸人。"
  },
