  Stage_55585_Desc = {
    Text = "雪山的凍土乾枯暗淡，滅絕一切生機。\n但生命的意志永遠頑強。\n只等雪山融化之時，冰涼的水滴落入土壤。\n一顆不屈的種子，立刻在山頂發芽。"
  },
  Stage_56404_Desc = {
    Text = "墨菲聽說自己並非第一位聖女，在數千年的悠久時光中，無數位少女的軀殼內曾經鼓噪過近似的心跳。\n萬千時空中，萬千枚心臟交疊鼓動。"
  },
  Stage_56404_Name = {
    Text = "時空溝壑·癲狂"
  },
  Stage_56404_StageInitStateText = {Text = "海魘"},
  Stage_56405_Desc = {
    Text = "這是所有生命最後的體面歸宿。\n以深海為棺，以天地為席，偉大的神明葬身於洋流。"
  },
  Stage_56405_Name = {
    Text = "裹屍布·癲狂"
  },
  Stage_56405_StageInitStateText = {Text = "海魘"},
  Stage_56407_Desc = {
    Text = "祂無聲亦無心地降臨。\n祂的心臟在她的血脈中，以並不渴求的姿態延續生存的搏動。"
  },
  Stage_56407_Name = {
    Text = "祂的降臨·癲狂"
  },
  Stage_56407_StageInitStateText = {Text = "海魘"},
  Stage_56408_Desc = {
    Text = "她數著高空中的星辰，等待她並不期待的時刻。\n「星辰正位之刻」，群星在海面上升起之時，她將化為群星中的一顆。"
  },
  Stage_56408_Name = {
    Text = "黃色星辰·癲狂"
  },
  Stage_56408_StageInitStateText = {Text = "海魘"},
  Stage_56409_Desc = {
    Text = "她無權決定自己胸腔中被植入的胚胎的歸屬。\n她無權決定向哪裡逃亡，無權決定牽住誰的手，無權決定和誰一起顛沛流離。\n在海上幻境浮浮沉沉的命運面前，誰都只是待宰的羔羊。"
  },
  Stage_56409_Name = {
    Text = "屠戮羔羊·癲狂"
  },
  Stage_56409_StageInitStateText = {Text = "海魘"},
  Stage_56410_Desc = {
    Text = "不必非得斷頭臺來為她處刑。\n手刃她的是她的母親。"
  },
  Stage_56410_Name = {
    Text = "行刑者·癲狂"
  },
  Stage_56410_StageInitStateText = {Text = "海魘"},
  Stage_56411_Desc = {
    Text = "安靜。安靜。安靜。\n冰層之下萬物永恆，連呼吸都被封凍。生存和死亡是同義詞，正如蟄伏與復甦疏無區別。\n艾爾沃斯永遠不會有屬於她的春天。"
  },
  Stage_56411_Name = {
    Text = "蟄伏·癲狂"
  },
  Stage_56411_StageInitStateText = {Text = "海魘"},
  Stage_56843_Desc = {
    Text = "餘音繞樑。\n以生命為代償，他的樂章在祂的殿堂永恆迴響。"
  },
  Stage_56843_Name = {
