  },
  Stage_56902_Desc = {
    Text = "跳吧，跳吧，不要停下你的步伐。\n揚起裙擺，轉開圓圈，因這世界早已在漩渦中不停旋轉。 \n放下顧慮的一切，加入最後的狂歡。\n只要奮力舞蹈，就能看見永恆的夕陽。"
