  Stage_56982_Name = {
    Text = "門扉之內·之五"
  },
  Stage_56983_Desc = {
    Text = "人偶的手中垂下絲線，勾連著世界的零件。\n哢噠、滋啦，動動手指，世界崩壞。\n又是什麼垂在人偶頭頂，使它不斷為虛無獻上舞蹈。"
  },
  Stage_56983_Name = {
    Text = "傀儡線·之三"
  },
  Stage_56984_Desc = {
    Text = "人偶的手中垂下絲線，勾連著世界的零件。\n哢噠、滋啦，動動手指，世界崩壞。\n又是什麼垂在人偶頭頂，使它不斷為虛無獻上舞蹈。"
  },
  Stage_56984_Name = {
    Text = "傀儡線·之一"
  },
  Stage_56985_Desc = {
    Text = "無數人渴求真實，前仆後繼。\n無數人捧著真實的碎片，以為盲眼獲得了光明，便開始鼓吹天堂的美好。\n只有她找到了真實之酒， 將那瓊漿一口飲下。\n咕咚。\n她頹然醉倒，她毒入膏肓。\n果然無數的傻子已然證明，真實只是一杯毒藥。\n飲少者毒發，飲多者身亡。\n如今她已時日無多，只想與你共同品嘗。"
  },
  Stage_56985_Name = {
    Text = "真實毒藥·之四"
  },
  Stage_56986_Desc = {
    Text = "像煙花一樣綻放吧，哪怕燃料是生命。\n既然終點相仿，何不省去漫長苦痛，換來璀璨光芒。"
  },
