  Stage_57395_Desc = {
    Text = "與常識相反：在現實世界中，沒有不在場證明反而會更安全。\n只要沒有確鑿的證據，員警就不能逮捕兇手。\n因此，請兇手們停止你們那些無謂的行徑吧！"
  },
  Stage_57395_Name = {
    Text = "不在場供述·癲狂"
  },
  Stage_57396_Desc = {
    Text = "「作為敘述者的我就是兇手」——真是老套的伎倆，毫無美感與技巧。\n很不幸，這次還是被我給撞見了。"
  },
  Stage_57396_Name = {
    Text = "翻轉詭計·癲狂"
  },
  Stage_57397_Desc = {
    Text = "偵探守則第一條：看上去越是平凡懦弱的委託人，背後的案子越大。\n以貌取人在這裡可行不通。"
  },
  Stage_57397_Name = {
    Text = "不速之客·癲狂"
  },
  Stage_57398_Desc = {
    Text = "若是在案發現場發現了無頭屍、無臉屍，不用懷疑——\n他的身分一定被掉包了。"
  },
  Stage_57398_Name = {
    Text = "無頭屍·癲狂"
  },
  Stage_57399_Desc = {
    Text = "平凡的相貌、經歷和姓名……\n當這些要素都集中在一個人身上，請放心大膽地將他排除在兇手行列吧。\n別問我原因。"
  },
  Stage_57399_Name = {
    Text = "幸運庸眾·癲狂"
  },
  Stage_57400_Desc = {
    Text = "1,2,3……\n直到第5個人被殺害的時候，聰明如我也沒能破案。\n為什麼？因為這首歌謠一共有10句。"
  },
  Stage_57400_Name = {
    Text = "銜樹枝·癲狂"
  },
  Stage_57401_Desc = {
    Text = "機械裝置、兇手在室內、偽裝他殺的自殺……\n說真的，花那麼多功夫來製造密室，不如乾脆僱一個殺手，不是更快嗎？"
  },
  Stage_57401_Name = {
    Text = "密室迷思·癲狂"
  },
  Stage_57402_Desc = {
    Text = "不要排斥你的員警朋友。\n在推理的世界裡，他們通常扮演被兇手耍得團團轉的角色。\n最大的用處：在第一時間為你排除錯誤兇手。"
  },
  Stage_57402_Name = {
    Text = "偵探之友·癲狂"
  },
  Stage_57403_Desc = {
    Text = "如果閱讀了以上推理準則，你成為一名偵探的熱情依舊不減。\n那麼祝你好運，你這個無可救藥的傻蛋。"
  },
  Stage_57403_Name = {
    Text = "後記·癲狂"
  },
  Stage_57673_Desc = {
    Text = "摯友反目、手足相殘、因愛生恨……\n祂以吸食人類的扭曲情感為樂，並自詡為自然主義者。\n「這是最純粹、真實的情感。純天然無加工，口感質樸清爽。」"
  },
  Stage_57673_Name = {Text = "悲劇秀"},
  Stage_57674_Desc = {
    Text = "刨除掉所有的不可能，剩下的只有真相。\n當然，量子物理學家對此持異議態度。"
  },
  Stage_57674_Name = {
    Text = "真相一種"
  },
  Stage_57675_Desc = {
    Text = "「如果……就……」是偵探最討厭的句式。\n它意味著失敗、悔恨與苦澀的松子酒，而他已經戒酒很多年了。"
  },
  Stage_57675_Name = {
    Text = "現實以下"
  },
  Stage_57676_Desc = {
    Text = "被所有人喜歡是一項了不起的成就；被所有人討厭同理。\n而他能毫不費力地做到以上兩點。\n真有你的，下週一先生！"
  },
  Stage_57676_Name = {
    Text = "下週一先生"
  },
  Stage_57677_Desc = {
    Text = "他是昨日，卻也通曉今日。\n他與眾神共居，他的生命永無結期。"
  },
  Stage_57677_Name = {Text = "棺中牆"},
  Stage_57678_Desc = {
    Text = "人是遲鈍的生物。\n只需要在他們之間豎起一塊木板，他們便再也無法辨認彼此的氣息。"
  },
  Stage_57678_Name = {
    Text = "初次會晤"
  },
  Stage_57679_Desc = {
    Text = "八個小士兵，秉燭到夜半；\n懸樑了此生，八個只剩七。"
  },
  Stage_57679_Name = {
    Text = "無人生還"
  },
  Stage_57681_Desc = {
    Text = "他們皆身處死地，又一併嚮往生。"
  },
  Stage_57681_Name = {
    Text = "最後的致意"
  },
  Stage_57682_Desc = {
    Text = "古宅和幽靈的關係，大概就像乳酪與培根。\n很難說究竟誰先誰後，總之當大家反應過來的時候，它們已經牢不可分了。"
  },
  Stage_57682_Name = {
    Text = "幽靈之家"
  },
  Stage_57683_Desc = {
    Text = "不過是從結果或立場倒推所謂的「原因」罷了。\n人類歷史上到處都在發生這樣的滑稽劇。"
  },
  Stage_57684_Desc = {
    Text = "他們皆身處死地，又一併嚮往生。"
  },
  Stage_57684_Name = {
    Text = "最後的致意"
  },
  Stage_57685_Desc = {
    Text = "願好運伴你常在，偵探先生。\n後會有期。"
  },
  Stage_57685_Name = {
    Text = "祝你好運！"
  },
  Stage_57686_Desc = {
    Text = "每當考試來臨，我都期待一場災難。\n洪水、颶風、小行星撞擊……什麼都行，只要能將現實短暫地踢走一小會。\n就一小會。"
  },
  Stage_57687_Desc = {
    Text = "他們皆身處死地，又一併嚮往生。"
  },
  Stage_57687_Name = {
    Text = "最後的致意"
  },
  Stage_58064_Desc = {
    Text = "愚昧的人啊，你們點燃了火焰，將希望與救贖付之一炬。\n當你們在漆黑的死亡中掙扎時，這自詡的正義滋味又如何？"
  },
  Stage_58064_Name = {
    Text = "懺悔·癲狂"
  },
  Stage_58065_Desc = {
    Text = "愚昧的人啊，你們點燃了火焰，將希望與救贖付之一炬。\n當你們在漆黑的死亡中掙扎時，這自詡的正義滋味又如何？"
  },
  Stage_58065_Name = {
    Text = "懺悔·之六"
  },
  Stage_58066_Desc = {
    Text = "他們拒絕理解，拒絕包容。\n他們的世界只有黑與白，儘管他們自己都無法掌控其定義。\n「燒死他，燒死他！」\n「燒死這個異端主教！讓邪惡死亡！」"
  },
  Stage_58066_Name = {
    Text = "偏執·之四"
  },
