  Stage_58364_Name = {
    Text = "遺忘曲線·癲狂"
  },
  Stage_58365_Desc = {
    Text = "「我什麼都沒有了。」瞎了一隻眼的流浪兒說，「只有這支花能獻給您，偉大的女王。」\n她接過白色的小蒼蘭，卻感到困惑。似乎這一幕曾無數次在她的記憶深處輪回。\n循環往復，就像困住米洛陶洛斯的迷宮。"
  },
