  Stage_58371_Name = {
    Text = "小蒼蘭·之六"
  },
  Stage_58372_Desc = {
    Text = "女王和她不朽的城池——伊薩拉烏。\n宇宙眷顧的雙生子啊，你們被命運的臍帶輕輕纏繞。\n有人說，智慧的女王率領民眾來到伊薩拉烏，就像《啟示錄》裡所描繪的。\n也有人說，伊薩拉烏的河床終年湧動，直到將女王孕育而出。"
  },
