  Stage_58378_Name = {
    Text = "啟示錄·之四"
  },
  Stage_58379_Desc = {
    Text = "伊薩拉烏就這樣消失了，彷彿它從未誕生。\n所有的街道、子民都是虛幻。它們從她的夢中誕生，在日復一日的勾勒中不斷具象，然後：\n「砰——」\n夢醒了。她從未睜眼看過伊薩拉烏，正如她從未睜眼看過自己。"
  },
