  },
  Stage_58392_Name = {
    Text = "一段記憶·之二"
  },
  Stage_58393_Desc = {
    Text = "當她睜開雙眼的時候，世界正在因此而毀滅。\n所有的建築都坍塌了，黑色的粘液舔舐天空，白色的小蒼蘭消散在永恆的虛空裡。\n一切都很安靜。一切都像睡著了。\n只有眼淚是冰涼的，冷冷地貼在她的臉上，浸濕了她的髮梢。"
  },
  Stage_58393_Name = {
    Text = "井·癲狂"
  },
