  },
  Stage_58400_Desc = {
    Text = "黃金之城——伊薩拉烏。\n它的財富取之不竭，它的欲望無邊無界。\n它就像一塊海綿，吸汲著不斷湧流的黃金潮水，並隨之膨脹。\n這是我的都城，女王說。她為此而自豪。"
  },
