    Text = "她覺得有無數條蛇像網一樣纏住了自己。\n醒來後，一個影子站在她的床前。它說：\n「無論你到什麼地方，我都要抹掉你，正如你現在抹掉我的臉一樣。」"
  },
  Stage_58437_Name = {
    Text = "無意識記·之四"
  },
  Stage_58438_Desc = {
    Text = "她覺得有無數條蛇像網一樣纏住了自己。\n醒來後，一個影子站在她的床前。它說：\n「無論你到什麼地方，我都要抹掉你，正如你現在抹掉我的臉一樣。」"
  },
  Stage_58438_Name = {
    Text = "無意識記·癲狂"
  },
  Stage_58439_Desc = {
    Text = "她覺得有無數條蛇像網一樣纏住了自己。\n醒來後，一個影子站在她的床前。它說：\n「無論你到什麼地方，我都要抹掉你，正如你現在抹掉我的臉一樣。」"
  },
  Stage_58439_Name = {
    Text = "無意識記·之六"
  },
  Stage_58440_Desc = {
    Text = "它已經成為她靈魂中那個可憎的區域的象徵。\n她同它一起受苦，一起死去，在某種意義上同它一起消失。\n因此她心如鐵石，毫不容情。"
  },
  Stage_58440_Name = {
    Text = "爬蟲腦·之三"
  },
  Stage_58441_Desc = {
    Text = "它已經成為她靈魂中那個可憎的區域的象徵。\n她同它一起受苦，一起死去，在某種意義上同它一起消失。\n因此她心如鐵石，毫不容情。"
  },
  Stage_58441_Name = {
    Text = "爬蟲腦·之二"
  },
  Stage_58442_Desc = {
    Text = "它已經成為她靈魂中那個可憎的區域的象徵。\n她同它一起受苦，一起死去，在某種意義上同它一起消失。\n因此她心如鐵石，毫不容情。"
  },
  Stage_58442_Name = {
    Text = "爬蟲腦·之一"
  },
  Stage_58443_Desc = {
    Text = "它已經成為她靈魂中那個可憎的區域的象徵。\n她同它一起受苦，一起死去，在某種意義上同它一起消失。\n因此她心如鐵石，毫不容情。"
  },
  Stage_58443_Name = {
    Text = "爬蟲腦·癲狂"
  },
  Stage_58444_Desc = {
    Text = "它已經成為她靈魂中那個可憎的區域的象徵。\n她同它一起受苦，一起死去，在某種意義上同它一起消失。\n因此她心如鐵石，毫不容情。"
  },
  Stage_58444_Name = {
    Text = "爬蟲腦·之六"
  },
  Stage_58445_Desc = {
    Text = "它已經成為她靈魂中那個可憎的區域的象徵。\n她同它一起受苦，一起死去，在某種意義上同它一起消失。\n因此她心如鐵石，毫不容情。"
  },
  Stage_58445_Name = {
    Text = "爬蟲腦·之五"
  },
  Stage_58446_Desc = {
    Text = "它已經成為她靈魂中那個可憎的區域的象徵。\n她同它一起受苦，一起死去，在某種意義上同它一起消失。\n因此她心如鐵石，毫不容情。"
  },
  Stage_58446_Name = {
    Text = "爬蟲腦·之四"
  },
  Stage_58449_Desc = {
    Text = "餘音繞樑。\n以生命為代償，他的樂章在祂的殿堂永恆迴響。"
  },
  Stage_58449_Name = {
    Text = "餘音·癲狂"
  },
  Stage_58450_Desc = {
    Text = "大幕垂下。\n他以昂首之姿漸隱於逐步墜落的紅絲絨幕布之後。"
  },
  Stage_58450_Name = {
    Text = "幕落·癲狂"
  },
  Stage_58451_Desc = {
    Text = "此為「第四門」。\n入第四門者，得見「祂」之真容。\n既見宇宙之博大，則了悟自身之渺小。不以螻蟻撼樹。"
  },
  Stage_58451_Name = {
    Text = "知行之門·癲狂"
  },
  Stage_58452_Desc = {
    Text = "歡迎來到人偶之屋，這裡有一千個一模一樣的笑容。\n嘻嘻，哪一個是你曾經的朋友？"
  },
  Stage_58452_Name = {
    Text = "人偶之屋·癲狂"
  },
  Stage_58453_Desc = {
    Text = "這世上本來沒有門。\n想要門的人多了，世上便有了各種各樣的門。\n人人都說自己的門背後才是天堂。\n然而啊，那古老的預言早已言明，這世上從來就沒有門。\n想在人間建立天堂的，終會開啟地獄的大門。"
  },
  Stage_58453_Name = {
    Text = "混沌預言·癲狂"
  },
  Stage_58454_Desc = {
    Text = "人偶的手中垂下絲線，勾連著世界的零件。\n哢噠、滋啦，動動手指，世界崩壞。\n又是什麼垂在人偶頭頂，使它不斷為虛無獻上舞蹈。"
  },
  Stage_58454_Name = {
    Text = "傀儡線·癲狂"
  },
  Stage_58455_Desc = {
    Text = "輕快樂章。\n他們活躍於整片大地，他們抗爭的身姿如此美妙。"
  },
  Stage_58455_Name = {
    Text = "小步舞曲·癲狂"
  },
  Stage_58456_Desc = {
    Text = "此為「第三門」。\n入第三門者，不拘泥於粗淺的理智，得以知曉界限之外的知識。"
  },
  Stage_58456_Name = {
    Text = "理智之門·癲狂"
  },
  Stage_58457_Desc = {
    Text = "跳吧，跳吧，不要停下你的步伐。\n揚起裙擺，轉開圓圈，因這世界早已在漩渦中不停旋轉。 \n放下顧慮的一切，加入最後的狂歡。\n只要奮力舞蹈，就能看見永恆的夕陽。"
  },
  Stage_58457_Name = {
    Text = "狂歡舞會·癲狂"
  },
  Stage_58458_Desc = {
    Text = "奏鳴曲式。\n由一裂變為三，三角之中，圓睜的眼球俯瞰大地。"
  },
  Stage_58458_Name = {
    Text = "快板·癲狂"
  },
  Stage_58459_Desc = {
    Text = "她擁有了王所預言的一切——強大的力量，堅定的信仰。她背負曾質疑王的罪孽，踏上迎接神國的路。"
  },
  Stage_58459_Name = {
    Text = "篤信·癲狂"
  },
  Stage_58459_StageInitStateText = {Text = "海魘"},
  Stage_58460_Desc = {
    Text = "此為「第五門」。\n入第五門者，與寰宇同享無上秘密。\n萬物均為「祂」的一呼一吸所化，亦將因「祂」的吐息而湮沒。"
  },
  Stage_58460_Name = {
    Text = "歸一之門·癲狂"
  },
  Stage_58461_Desc = {
    Text = "她伸出手，邀你做她的舞伴。\n前進，後退，這種默契只你二人獨有。\n輕握她的手掌，跟上她的腳步，不要低下紳士的頭顱。\n哪怕腳下早已是懸崖邊緣。"
  },
  Stage_58461_Name = {
    Text = "邀請·癲狂"
  },
  Stage_58462_Desc = {
    Text = "此為「第六門」。\n入第六門者，貫聯諸世，於萬千維度中得求永恆的存續。"
  },
  Stage_58462_Name = {
    Text = "諸世之門·癲狂"
  },
  Stage_58463_Desc = {
    Text = "抒情樂章。\n哺育，繁衍，生生不息。"
  },
  Stage_58463_Name = {
    Text = "慢板·癲狂"
  },
  Stage_58464_Desc = {
    Text = "啟程吧。\n此行是通往「智慧」還是「愚昧」，只有踏上旅程才能知曉。"
  },
  Stage_58464_Name = {
    Text = "啟程·癲狂"
  },
  Stage_58465_Desc = {
    Text = "交響不是一個人的遊戲。\n絃樂、木管樂、銅管樂、打擊樂。\n編制規整的器樂組低垂著頭顱，等待他給予的指引。"
  },
  Stage_58465_Name = {
    Text = "管絃編制·癲狂"
  },
  Stage_58466_Desc = {
    Text = "他循聲而來，踏上指揮台。\n他步伐穩健，胸有成竹。\n無人知曉他因夢而來，而夢的主人早已陷入迷失。"
  },
  Stage_58466_Name = {
    Text = "迷途夢引·癲狂"
  },
  Stage_58467_Desc = {
    Text = "此為「第一門」。\n入第一門者，需掙脫枷鎖，捨棄本性，遺忘自身。\n囿於個體的視野無力承載荒誕的真實。"
  },
  Stage_58467_Name = {
    Text = "本性之門·癲狂"
  },
  Stage_58468_Desc = {
    Text = "此為「第二門」。\n入第二門者，勿妄斷是非。\n是非只是規則制定者的臆斷，而真理的所在超越一切知識。"
  },
  Stage_58468_Name = {
    Text = "是非之門·癲狂"
  },
  Stage_58469_Desc = {
    Text = "迴旋曲式。\n他將指引末路的方向，直面毀滅。"
  },
  Stage_58469_Name = {
    Text = "終曲·癲狂"
  },
  Stage_58470_Desc = {
    Text = "神國的輪廓在她眼前出現。神國的鐘聲在她耳中敲響。她將踐行王的預言，永不停息。\n她以此言得度此生的茫茫黑夜。"
  },
  Stage_58470_Name = {
    Text = "降臨·癲狂"
  },
  Stage_58470_StageInitStateText = {Text = "海魘"},
  Stage_58471_Desc = {
    Text = "末日到來，世界長滿膿瘡，衰亡的漩渦將席捲所有生靈。\n祈禱吧，尋找吧，那從不存在的求生之門。"
  },
  Stage_58471_Name = {
    Text = "狂災·癲狂"
  },
  Stage_58472_Desc = {
    Text = "失去一切的那天，她終於明白，唯有王能拯救利莫里亞的子民。\n她等待著，在那遙遠的神國，與自己所失去的一切重逢。"
  },
  Stage_58472_Name = {
    Text = "見證·癲狂"
  },
  Stage_58472_StageInitStateText = {Text = "海魘"},
  Stage_58473_Desc = {
    Text = "利莫里亞消亡了。神明從未在意這片土地。\n神國，從未存在過。"
  },
  Stage_58473_Name = {
    Text = "動搖·癲狂"
  },
  Stage_58473_StageInitStateText = {Text = "海魘"},
  Stage_58474_Desc = {
    Text = "為何你仍不肯捨棄？為何你仍愚鈍如初？\n……守護他們嗎。\n如果這便是你的答案，你終將獻出你的骨，你的血，你的靈知，你的一切。"
  },
  Stage_58474_Name = {
    Text = "門扉之內·癲狂"
  },
  Stage_58475_Desc = {
    Text = "有一顆星星掛在黏稠的黑夜中。\n那星星膨脹，發光，變成了無限大的棉花糖。\n這是某人凝聚了一生的愛恨，嘗一嘗，是什麼味道？"
  },
  Stage_58475_Name = {
    Text = "星星·癲狂"
  },
  Stage_58476_Desc = {
    Text = "祈禱是利莫里亞人學會的第一件事，可出現在她面前保護她的，從來不是她的王。"
  },
  Stage_58476_Name = {
    Text = "質疑·癲狂"
  },
  Stage_58476_StageInitStateText = {Text = "海魘"},
  Stage_58477_Desc = {
    Text = "無數人渴求真實，前仆後繼。\n無數人捧著真實的碎片，以為盲眼獲得了光明，便開始鼓吹天堂的美好。\n只有她找到了真實之酒， 將那瓊漿一口飲下。\n咕咚。\n她頹然醉倒，她毒入膏肓。\n果然無數的傻子已然證明，真實只是一杯毒藥。\n飲少者毒發，飲多者身亡。\n如今她已時日無多，只想與你共同品嘗。"
  },
  Stage_58477_Name = {
    Text = "真實毒藥·癲狂"
  },
  Stage_58478_Desc = {
    Text = "像煙花一樣綻放吧，哪怕燃料是生命。\n既然終點相仿，何不省去漫長苦痛，換來璀璨光芒。"
  },
  Stage_58478_Name = {
    Text = "璀璨消亡·癲狂"
  },
  Stage_58479_Desc = {
    Text = "此為「第七門」。\n時間的洪流在此處暫停，永恆的智慧將引領彷徨的探求者走出最深的迷惘。"
  },
  Stage_58479_Name = {
    Text = "窮極之門·癲狂"
  },
  Stage_58480_Desc = {
    Text = "開場，辨明主題。\n他將敘述伊始和終末，吞吐與呼吸。"
  },
  Stage_58480_Name = {
    Text = "序曲·癲狂"
  },
  Stage_58691_Desc = {
    Text = "風銷雪霽，萬物生長。"
  },
  Stage_58691_Name = {
    Text = "一個春天"
  },
  Stage_58692_Desc = {
    Text = "哀悼，或者驚歎。這是一名戰士，面向群山的宣戰。"
  },
  Stage_58693_Desc = {
    Text = "她的衣衫隨風舞動，她的迷茫輕聲作響。她站在你的面前。"
  },
  Stage_58694_Desc = {
    Text = "你們沒有找到敵人，但敵人找到了你們。"
  },
  Stage_58695_Desc = {
    Text = "回來吧，孩子。山呼喚道。\n回應母親親切的召喚，回歸命運安寧的懷抱。"
  },
  Stage_58695_Name = {
    Text = "群山的呼喚"
  },
  Stage_58696_Desc = {
    Text = "他們的故事無人知曉。他們的名字無人悼念。"
  },
  Stage_58697_Desc = {
    Text = "對於你們的禮貌造訪，艾爾沃斯似乎並不那麼歡迎。"
  },
  Stage_58697_Name = {
    Text = "雪原來客"
  },
  Stage_58698_Desc = {
    Text = "在月色與雪色之間，血是第三種色彩。"
  },
  Stage_58699_Desc = {
    Text = "很難判斷，究竟是哪個更危險。"
  },
  Stage_58699_Name = {
    Text = "同伴或敵人"
  },
  Stage_58700_Desc = {
    Text = "哀悼，或者驚歎。這是一名戰士，面向群山的宣戰。"
  },
  Stage_58701_Desc = {
    Text = "哀悼，或者驚歎。這是一名戰士，面向群山的宣戰。"
  },
  Stage_58976_Desc = {
    Text = "「我會看著你，堅定不移地走上這條絕路……我會在你的葬禮上，為你哀悼。」"
  },
  Stage_58976_Name = {
    Text = "存續之道"
  },
  Stage_58977_Desc = {
    Text = "「我喜歡劇院裡的很多橋段。但我最喜歡的，是他們將最美麗的瓷器扔下閣樓的時刻。」"
  },
  Stage_58977_Name = {Text = "父與女"},
  Stage_58978_Desc = {
    Text = "坎坷，漫長，虛無。每個人都有自己將要面對的道路。\n當你終於站在起點，你是否有足夠的勇氣，凝望你的遠方？"
  },
  Stage_58979_Desc = {
    Text = "節拍。旋律。絃樂柔和的泛音充盈你們的腦海。\n觀眾沉默的目光裡，指揮家站上屬於他的舞臺。"
  },
  Stage_58979_Name = {Text = "指揮家"},
  Stage_58980_Desc = {
    Text = "他虛弱的身體被淹沒在沸騰的地底。\n在那虛幻的維度，他獨自與黑池對決。"
  },
  Stage_58980_Name = {Text = "殘軀"},
  Stage_58981_Desc = {
    Text = "走音，缺位……任何一個失誤，都會讓一場演出萬劫不復。\n練習。在無數的練習中，等待屬於你的掌聲。"
  },
  Stage_58981_Name = {Text = "排練"},
  Stage_58982_Desc = {
    Text = "遺忘，是對這世界最終的淨化？彌薩格從不認同。\n這座校園裡的人們，將為銘記而戰。"
  },
  Stage_58982_Name = {
    Text = "遺忘之理"
  },
  Stage_58982_StageInitStateText = {Text = "終末"},
  Stage_58983_Desc = {
    Text = "輕鬆的舞曲，愉悅的諧謔，缺乏變化的庸俗之作。\n沒錯，在第三樂章小憩吧。這裡安全，平靜，毫無意外。"
  },
  Stage_58983_Name = {
    Text = "第三樂章"
  },
  Stage_58984_Desc = {
    Text = "無從哀求。無從逃避。這是這個世界的命運。\n戰勝祂們。殺死祂們。然後，拯救祂們。"
  },
  Stage_58985_Desc = {
    Text = "提前透露的轉折便失去了力度，但他從不在乎。\n他所期待的歡愉，不在此處。"
  },
  Stage_58985_Name = {
    Text = "德克斯特式轉折"
  },
  Stage_58986_Desc = {
    Text = "噓。\n最後的聽眾已然落座，真正的演出，就要開始了。"
  },
  Stage_58986_Name = {Text = "入場"},
  Stage_58987_Desc = {
    Text = "當資訊不對等的時候，越完美，便越錯誤。"
  },
  Stage_58987_Name = {
    Text = "好學生，壞學生"
  },
  Stage_58988_Desc = {
    Text = "「彌薩格獨立於雷歐王國政府及密斯底亞協議審查會的管轄範圍。凡未經授權擅入者，均視作非法入侵，彌薩格有權充分行使自衛權。」"
  },
  Stage_58988_Name = {Text = "校規"},
  Stage_59049_Desc = {
    Text = "節拍。旋律。絃樂柔和的泛音充盈你們的腦海。\n觀眾沉默的目光裡，指揮家站上屬於他的舞臺。"
  },
  Stage_59049_Name = {Text = "指揮家"},
  Stage_59050_Desc = {
    Text = "走音，缺位……任何一個失誤，都會讓一場演出萬劫不復。\n練習。在無數的練習中，等待屬於你的掌聲。"
  },
  Stage_59050_Name = {Text = "排練"},
  Stage_59051_Desc = {
    Text = "「彌薩格獨立於雷歐王國政府及密斯底亞協議審查會的管轄範圍。凡未經授權擅入者，均視作非法入侵，彌薩格有權充分行使自衛權。」"
  },
  Stage_59051_Name = {Text = "校規"},
  Stage_59052_Desc = {
    Text = "「我會看著你，堅定不移地走上這條絕路……我會在你的葬禮上，為你哀悼。」"
  },
  Stage_59052_Name = {
    Text = "存續之道"
  },
  Stage_59053_Desc = {
    Text = "提前透露的轉折便失去了力度，但他從不在乎。\n他所期待的歡愉，不在此處。"
  },
  Stage_59053_Name = {
    Text = "德克斯特式轉折"
  },
  Stage_59054_Desc = {
    Text = "他虛弱的身體被淹沒在沸騰的地底。\n在那虛幻的維度，他獨自與黑池對決。"
  },
  Stage_59054_Name = {Text = "殘軀"},
  Stage_59055_Desc = {
    Text = "坎坷，漫長，虛無。每個人都有自己將要面對的道路。\n當你終於站在起點，你是否有足夠的勇氣，凝望你的遠方？"
  },
  Stage_59056_Desc = {
    Text = "無從哀求。無從逃避。這是這個世界的命運。\n戰勝祂們。殺死祂們。然後，拯救祂們。"
  },
  Stage_59057_Desc = {
    Text = "輕鬆的舞曲，愉悅的諧謔，缺乏變化的庸俗之作。\n沒錯，在第三樂章小憩吧。這裡安全，平靜，毫無意外。"
  },
  Stage_59057_Name = {
    Text = "第三樂章"
  },
  Stage_59058_Desc = {
    Text = "黑色的池水狂躁地舞動，迎接它們最初的、唯一的主人。"
  },
  Stage_59058_StageInitStateText = {Text = "終末"},
  Stage_59059_Desc = {
    Text = "遺忘，是對這世界最終的淨化？彌薩格從不認同。\n這座校園裡的人們，將為銘記而戰。"
  },
  Stage_59059_Name = {
    Text = "遺忘之理"
  },
  Stage_59060_Desc = {
    Text = "走音，缺位……任何一個失誤，都會讓一場演出萬劫不復。\n練習。在無數的練習中，等待屬於你的掌聲。"
  },
  Stage_59060_Name = {Text = "排練"},
  Stage_59061_Desc = {
    Text = "節拍。旋律。絃樂柔和的泛音充盈你們的腦海。\n觀眾沉默的目光裡，指揮家站上屬於他的舞臺。"
  },
  Stage_59061_Name = {Text = "指揮家"},
  Stage_59062_Desc = {
    Text = "「彌薩格獨立於雷歐王國政府及密斯底亞協議審查會的管轄範圍。凡未經授權擅入者，均視作非法入侵，彌薩格有權充分行使自衛權。」"
  },
  Stage_59062_Name = {Text = "校規"},
  Stage_59063_Desc = {
    Text = "提前透露的轉折便失去了力度，但他從不在乎。\n他所期待的歡愉，不在此處。"
  },
