  },
  Stage_59502_Desc = {
    Text = "面對你們最原初的絕望。面對你們最原初的恐懼。\n站在看不見的彼此身邊，然後戰勝祂。"
  },
  Stage_59502_Name = {
    Text = "決勝：原初之影"
  },
  Stage_59503_Desc = {
    Text = "銘記是你的誓言，遺忘是你的祭禮。"
  },
  Stage_59503_Name = {Text = "祭禮"},
  Stage_59504_Desc = {
    Text = "站在夢境的神殿，支撐起坍塌的殘垣。\n守護你身下，那粒承載你所有顧惜與掛念的塵埃。"
  },
  Stage_59504_Name = {
    Text = "夢的崩析"
  },
  Stage_59505_Desc = {
    Text = "「生存，還是毀滅？」"
  },
  Stage_59506_Desc = {
    Text = "銘記是你的誓言，遺忘是你的祭禮。"
  },
