    Text = "夢的崩析"
  },
  Stage_59511_Desc = {
    Text = "銘記是你的誓言，遺忘是你的祭禮。"
  },
  Stage_59511_Name = {Text = "祭禮"},
  Stage_62348_Desc = {
    Text = "這是群星的高潮。這是寰宇的落幕。\n在這闃寂之中，認真聆聽——\n那真正的音符，你聽到了嗎？"
  },
  Stage_62348_Name = {Text = "終曲"},
  Stage_66016_Desc = {
    Text = "祂是無上的意志，宇宙的造物主，萬物的終結者。\n在祂的面前悲泣吧。為你們孱弱的勇氣，為祂無盡的權柄。"
  },
  Stage_66016_Name = {
    Text = "濟貧院·悲泣之視"
  },
  Stage_66017_Desc = {
    Text = "祂是無上的意志，宇宙的造物主，萬物的終結者。\n在祂的面前悲泣吧。為你們孱弱的勇氣，為祂無盡的權柄。"
  },
  Stage_66017_Name = {
    Text = "濟貧院·悲泣之視"
  },
  Stage_66018_Desc = {
    Text = "祂是無上的意志，宇宙的造物主，萬物的終結者。\n在祂的面前悲泣吧。為你們孱弱的勇氣，為祂無盡的權柄。"
  },
  Stage_66018_Name = {
    Text = "濟貧院·悲泣之視"
  },
  Stage_66381_Desc = {
    Text = "無須擔心，恐懼是生物最原始的本能。\n神明從不為難任何一隻螻蟻。祂以甦醒為你們賜福。"
  },
  Stage_66381_Name = {
    Text = "蠟像館·恐懼之視"
  },
  Stage_66382_Desc = {
    Text = "歌詠吧，偉大的造物主！\n在祂入夢時，生民繁榮興盛。\n在祂睜眼時，萬物化為塵埃。"
  },
  Stage_66382_Name = {
    Text = "布里爾珀特·邪信之視"
  },
  Stage_66383_Desc = {
    Text = "感受疼痛吧，感受無上意志最原始的饋贈。\n在疼痛中，窺見造物主的威儀。"
  },
  Stage_66383_Name = {
    Text = "拉伊·刺骨之視"
  },
  Stage_66384_Desc = {
    Text = "不必掙扎。不必抗爭。不必嘗試理解不可理解之物。\n在無上意志的目光中，迎接夢境的終結。"
  },
  Stage_66384_Name = {
    Text = "療養院·詭譎之視"
  },
  Stage_66385_Desc = {
    Text = "祂是無上的意志，宇宙的造物主，萬物的終結者。\n在祂的面前悲泣吧。為你們孱弱的勇氣，為祂無盡的權柄。"
  },
  Stage_66385_Name = {
    Text = "濟貧院·悲泣之視"
  },
  Stage_67123_Desc = {
    Text = "那宏偉的文明，那人間的悲歡，那環繞你遠離你的無數的人，從未存在過。夢境的消解，終將誕臨。\n忘卻吧，守密人們。忘卻是最隆重的苦難。\n忘卻是至福的解藥。"
  },
  Stage_67123_Name = {
    Text = "勒姆瓦希·誕臨之視"
  },
  Stage_67124_Desc = {
    Text = "盲目癡愚的洪流上，秩序的樓閣轟然坍塌。\n理性從未存在過，唯有瘋狂是你們的歸宿。"
  },
  Stage_67124_Name = {
    Text = "索納尼爾號·瘋狂之視"
  },
