  },
  Stage_67914_Desc = {
    Text = "%hisorher%名字與功績將無人知曉。%heorshe%來自遺忘，歸於遺忘。只有墓碑上的箴言與世長存。\n銀鑰曾指引%hisorher%前路。未來的道路，亦願銀鑰指引你我。"
  },
