  Stage_68515_Desc = {
    Text = "不可預知的維度中，那雙沉睡的眼眸睜開。\n世間桑田滄海，一切都是嶄新的模樣。"
  },
  Stage_68515_Name = {
    Text = "神之眸·癲狂"
  },
  Stage_68515_StageInitStateText = {Text = "海魘"},
  Stage_68516_Desc = {
    Text = "鬧劇結束，神王再次陷入沉睡。\n夢中，偉大的利莫里亞人聲鼎沸，一切都是熟悉的模樣。"
  },
  Stage_68517_Desc = {
