  },
  Stage_68523_Desc = {
    Text = "哭喊消失，世界再次恢復死寂。祂用眼眸撫摸國度的廢墟，留下歎息。\n利莫里亞——那是祂回不去的故鄉。"
  },
  Stage_68523_Name = {
    Text = "鄉愁·之三"
