  Stage_70092_Desc = {
    Text = "胚珠是隱秘的前奏。\n新的孕育尚未發生，新的種子尚未成型，奇蹟仍在孕育之中。"
  },
  Stage_70092_Name = {
    Text = "胚珠·囈語癲狂"
  },
  Stage_70093_Desc = {
    Text = "胚珠是隱秘的前奏。\n新的孕育尚未發生，新的種子尚未成型，奇蹟仍在孕育之中。"
  },
  Stage_70093_Name = {
    Text = "胚珠·囈語之六"
  },
  Stage_70094_Desc = {
    Text = "多胚生殖是原始的貪婪。\n以唯一的母體，孕育出最大數量的後代，在荒涸之地頑強地擴張。"
  },
  Stage_70094_Name = {
    Text = "多胚生殖·囈語癲狂"
  },
  Stage_70095_Desc = {
    Text = "多胚生殖是原始的貪婪。\n以唯一的母體，孕育出最大數量的後代，在荒涸之地頑強地擴張。"
  },
  Stage_70095_Name = {
    Text = "多胚生殖·囈語之六"
  },
  Stage_70096_Desc = {
    Text = "年輪是跋涉的計數。\n以晴雨、以風霜、以濕潤的白和緻密的黑，雕刻於無人可見的堅實骨骼，作為流逝歲月的銘記。"
  },
  Stage_70096_Name = {
    Text = "年輪·囈語癲狂"
  },
  Stage_70097_Desc = {
    Text = "年輪是跋涉的計數。\n以晴雨、以風霜、以濕潤的白和緻密的黑，雕刻於無人可見的堅實骨骼，作為流逝歲月的銘記。"
  },
  Stage_70097_Name = {
    Text = "年輪·囈語之六"
  },
  Stage_70098_Desc = {
    Text = "蜜腺是甜美的誘惑。\n它分泌蜜汁，散發甘香，引誘彩蝶與蜂群，將沉醉的迷失者轉化為繁衍的工具。"
  },
  Stage_70098_Name = {
    Text = "蜜腺·囈語癲狂"
  },
  Stage_70099_Desc = {
    Text = "蜜腺是甜美的誘惑。\n它分泌蜜汁，散發甘香，引誘彩蝶與蜂群，將沉醉的迷失者轉化為繁衍的工具。"
  },
  Stage_70099_Name = {
    Text = "蜜腺·囈語之六"
  },
  Stage_70100_Desc = {
    Text = "花萼是無聲的守護。\n它異化自我，托舉花蕾、果實和未來的種子。"
  },
  Stage_70100_Name = {
    Text = "花萼·囈語之六"
  },
  Stage_70101_Desc = {
    Text = "花萼是無聲的守護。\n它異化自我，托舉花蕾、果實和未來的種子。"
  },
  Stage_70101_Name = {
    Text = "花萼·囈語癲狂"
  },
  Stage_70102_Desc = {
    Text = "幼根是莽撞的冒險。\n種子不知曉下一寸天地是豐沃的黑土，還是冰冷的荒沙，種子只是無垠無畏地伸出邁向大地的根梢。"
  },
  Stage_70102_Name = {
    Text = "幼根·囈語癲狂"
  },
  Stage_70103_Desc = {
    Text = "幼根是莽撞的冒險。\n種子不知曉下一寸天地是豐沃的黑土，還是冰冷的荒沙，種子只是無垠無畏地伸出邁向大地的根梢。"
  },
  Stage_70103_Name = {
    Text = "幼根·囈語之六"
  },
  Stage_70104_Desc = {
    Text = "落果是殘酷的預兆。\n越極端惡劣的環境，生存競爭到來得越早。在新的幼苗觸達大地之前，死亡已經如影隨形。"
  },
  Stage_70104_Name = {
    Text = "落果·囈語之六"
  },
  Stage_70105_Desc = {
    Text = "落果是殘酷的預兆。\n越極端惡劣的環境，生存競爭到來得越早。在新的幼苗觸達大地之前，死亡已經如影隨形。"
  },
  Stage_70105_Name = {
    Text = "落果·囈語癲狂"
  },
  Stage_70106_Desc = {
    Text = "抽芽是懵懂的試探。\n嬌嫩地綠芽靜默無聲地頂破堅硬的土壤，迎接未知的考驗。"
  },
  Stage_70106_Name = {
    Text = "出芽·囈語之六"
  },
  Stage_70107_Desc = {
    Text = "抽芽是懵懂的試探。\n嬌嫩地綠芽靜默無聲地頂破堅硬的土壤，迎接未知的考驗。"
  },
  Stage_70107_Name = {
    Text = "出芽·囈語癲狂"
  },
  Stage_70108_Desc = {
    Text = "再生花是永恆的循環。\n生命鼎盛之時，勿要忘記：晝夜的秘密和季節的耳語都將隨著花落凋敝。\n以死亡為終局，便是以誕生為伊始。"
  },
  Stage_70108_Name = {
    Text = "再生花·囈語之六"
  },
  Stage_70109_Desc = {
    Text = "再生花是永恆的循環。\n生命鼎盛之時，勿要忘記：晝夜的秘密和季節的耳語都將隨著花落凋敝。\n以死亡為終局，便是以誕生為伊始。"
  },
  Stage_70109_Name = {
    Text = "再生花·囈語癲狂"
  },
  Stage_70110_Desc = {
    Text = "授粉是遙遠的邂逅。\n花枝搖曳邀約共舞的使者，邀約它擷取花粉，流連花叢，在自然的律動中將新生命的源泉送入另一個等待的懷抱。"
  },
  Stage_70110_Name = {
    Text = "授粉·囈語癲狂"
  },
  Stage_70111_Desc = {
    Text = "授粉是遙遠的邂逅。\n花枝搖曳邀約共舞的使者，邀約它擷取花粉，流連花叢，在自然的律動中將新生命的源泉送入另一個等待的懷抱。"
  },
  Stage_70111_Name = {
    Text = "授粉·囈語之六"
  },
  Stage_70402_Desc = {
    Text = "黑貓陶醉於此時此刻，從喉嚨中發出奧秘的低語，如世界的真理全部彙集於此。\n喵，喵嗷，喵嗚嗚嗷。\n你聽不懂，但這並不妨礙你想讓它閉上那張吵鬧的嘴。"
  },
  Stage_70402_Name = {
    Text = "貓的低語·之一"
  },
  Stage_70403_Desc = {
    Text = "黑貓陶醉於此時此刻，從喉嚨中發出奧秘的低語，如世界的真理全部彙集於此。\n喵，喵嗷，喵嗚嗚嗷。\n你聽不懂，但這並不妨礙你想讓它閉上那張吵鬧的嘴。"
