  },
  Stage_70404_Name = {
    Text = "貓的低語·之三"
  },
  Stage_70405_Desc = {
    Text = "邪惡的黑貓狡詐一笑，你低頭看到錢包破開小口。\n對面貓咪的帽子裡，有銀芯的光芒一閃而過。"
  },
