    Text = "貓的詭計·之二"
  },
  Stage_70407_Desc = {
    Text = "邪惡的黑貓狡詐一笑，你低頭看到錢包破開小口。\n對面貓咪的帽子裡，有銀芯的光芒一閃而過。"
  },
  Stage_70407_Name = {
    Text = "貓的詭計·之一"
  },
  Stage_70408_Desc = {
    Text = "黑貓眯著眼睛看你，在貓的世界中，那是喜愛的意思。\n喜愛著你的黑貓蹦跳著拍打你的小腿，那不是毆打，是愛的玩耍。"
  },
  Stage_70408_Name = {
    Text = "貓的偏愛·之一"
  },
  Stage_70409_Desc = {
    Text = "黑貓眯著眼睛看你，在貓的世界中，那是喜愛的意思。\n喜愛著你的黑貓蹦跳著拍打你的小腿，那不是毆打，是愛的玩耍。"
  },
  Stage_70409_Name = {
    Text = "貓的偏愛·之三"
  },
  Stage_70410_Desc = {
    Text = "黑貓眯著眼睛看你，在貓的世界中，那是喜愛的意思。\n喜愛著你的黑貓蹦跳著拍打你的小腿，那不是毆打，是愛的玩耍。"
  },
  Stage_70410_Name = {
    Text = "貓的偏愛·之二"
  },
  Stage_70411_Desc = {
    Text = "貓耳旋轉，貓爪開花，尾巴起立。\n在與你的恰恰中，貓的快樂溢於言表。"
  },
  Stage_70411_Name = {
    Text = "貓的喜悅·之一"
  },
  Stage_70412_Desc = {
    Text = "貓的腳爪在你面前不停試探，伸出、縮回、伸出、縮回。\n漆黑的爪印踩在了你的校服皮鞋上。\n你忍不住提起了砂鍋大的拳頭。"
  },
  Stage_70412_Name = {
    Text = "貓的爪印·之一"
  },
  Stage_70413_Desc = {
    Text = "熟悉的黑貓顯然也擁有對你的記憶，它摘下禮帽向你致意。\n一隻不知道從哪裡掏出來的白手套被扔在了你的面前，這不是問好，是紳士的決鬥邀請。"
  },
  Stage_70413_Name = {
    Text = "貓的問候·之一"
  },
  Stage_70414_Desc = {
    Text = "熟悉的黑貓顯然也擁有對你的記憶，它摘下禮帽向你致意。\n一隻不知道從哪裡掏出來的白手套被扔在了你的面前，這不是問好，是紳士的決鬥邀請。"
  },
  Stage_70414_Name = {
    Text = "貓的問候·之三"
  },
  Stage_70415_Desc = {
    Text = "熟悉的黑貓顯然也擁有對你的記憶，它摘下禮帽向你致意。\n一隻不知道從哪裡掏出來的白手套被扔在了你的面前，這不是問好，是紳士的決鬥邀請。"
  },
  Stage_70415_Name = {
    Text = "貓的問候·之二"
  },
  Stage_70416_Desc = {
    Text = "今夜多麼歡暢，一切使貓流連難忘！\n讓皎潔的月光透過花窗，照在狂歡的宴會上！\n哦，讚美貓咪！"
  },
  Stage_70416_Name = {
    Text = "貓的狂歡·之二"
  },
