  },
  Stage_70419_Name = {
    Text = "貓的爪印·之二"
  },
  Stage_70420_Desc = {
    Text = "在貓的派對上盡情歌唱吧，請高舉起歡樂的酒杯，讓黑貓為你斟滿瓊漿……什麼，為什麼酒壺裡是魚湯？"
  },
  Stage_70420_Name = {
    Text = "貓的派對·之一"
  },
  Stage_70421_Desc = {
    Text = "黑貓拱起後背，開始舞動自己的四肢。\n看起來這只黑貓剛剛馴服自己的身體。\n奇形怪狀的黑貓伸出手，邀請你加入共舞。"
  },
  Stage_70421_Name = {
    Text = "貓的舞蹈·之一"
  },
  Stage_70422_Desc = {
    Text = "在貓的派對上盡情歌唱吧，請高舉起歡樂的酒杯，讓黑貓為你斟滿瓊漿……什麼，為什麼酒壺裡是魚湯？"
  },
  Stage_70422_Name = {
    Text = "貓的派對·之二"
  },
  Stage_70423_Desc = {
