  },
  Stage_70423_Name = {
    Text = "貓的派對·之三"
  },
  Stage_70424_Desc = {
    Text = "你凝視著黑貓，黑貓亦凝視著你。"
  },
  Stage_70424_Name = {
    Text = "貓的凝視·之二"
  },
  Stage_70425_Desc = {
    Text = "你凝視著黑貓，黑貓亦凝視著你。"
  },
  Stage_70425_Name = {
    Text = "貓的凝視·之三"
  },
  Stage_70426_Desc = {
    Text = "你凝視著黑貓，黑貓亦凝視著你。"
  },
  Stage_70426_Name = {
    Text = "貓的凝視·之一"
  },
  Stage_70427_Desc = {
