  },
  Stage_70428_Desc = {
    Text = "今夜多麼歡暢，一切使貓流連難忘！\n讓皎潔的月光透過花窗，照在狂歡的宴會上！\n哦，讚美貓咪！"
  },
  Stage_70428_Name = {
    Text = "貓的狂歡·之三"
