  Stage_70429_Desc = {
    Text = "貓耳旋轉，貓爪開花，尾巴起立。\n在與你的恰恰中，貓的快樂溢於言表。"
  },
  Stage_70429_Name = {
    Text = "貓的喜悅·之三"
  },
  Stage_70430_Desc = {
    Text = "黑貓為你送上最後的祝福，你能感到這場鬧劇即將結束。\n貓貓有什麼錯呢？它只是想在節日中給你帶來一些熱鬧罷了。"
  },
  Stage_70430_Name = {
    Text = "貓的祝福·之二"
  },
  Stage_70431_Desc = {
    Text = "黑貓為你送上最後的祝福，你能感到這場鬧劇即將結束。\n貓貓有什麼錯呢？它只是想在節日中給你帶來一些熱鬧罷了。"
  },
  Stage_70431_Name = {
    Text = "貓的祝福·之三"
  },
  Stage_70432_Desc = {
    Text = "黑貓拱起後背，開始舞動自己的四肢。\n看起來這只黑貓剛剛馴服自己的身體。\n奇形怪狀的黑貓伸出手，邀請你加入共舞。"
  },
  Stage_70432_Name = {
    Text = "貓的舞蹈·之三"
  },
  Stage_70433_Desc = {
    Text = "黑貓拱起後背，開始舞動自己的四肢。\n看起來這只黑貓剛剛馴服自己的身體。\n奇形怪狀的黑貓伸出手，邀請你加入共舞。"
  },
  Stage_70433_Name = {
    Text = "貓的舞蹈·之二"
  },
  Stage_70434_Desc = {
    Text = "黑貓為你送上最後的祝福，你能感到這場鬧劇即將結束。\n貓貓有什麼錯呢？它只是想在節日中給你帶來一些熱鬧罷了。"
  },
  Stage_70434_Name = {
    Text = "貓的祝福·之一"
  },
  Stage_70435_Desc = {
    Text = "這只黑貓似乎擁有了神奇的力量。\n貓咪打出響指，天空綻放煙花。\n熱鬧的劈啪聲中，你聞到頭頂傳來發絲焦糊的味道。"
  },
  Stage_70435_Name = {
    Text = "貓的魔法·之二"
  },
  Stage_70436_Desc = {
    Text = "這只黑貓似乎擁有了神奇的力量。\n貓咪打出響指，天空綻放煙花。\n熱鬧的劈啪聲中，你聞到頭頂傳來發絲焦糊的味道。"
  },
  Stage_70436_Name = {
    Text = "貓的魔法·之三"
  },
  Stage_70437_Desc = {
    Text = "這只黑貓似乎擁有了神奇的力量。\n貓咪打出響指，天空綻放煙花。\n熱鬧的劈啪聲中，你聞到頭頂傳來發絲焦糊的味道。"
  },
  Stage_70437_Name = {
    Text = "貓的魔法·之一"
  },
  Stage_70924_Desc = {
    Text = "親愛的，讓我們去看看末日。\n與其在絕望中日益衰朽，不如趁著命運尚未降臨，親手建樹終末的偉業。"
  },
  Stage_70924_Name = {
    Text = "未選擇的路"
  },
  Stage_70925_Desc = {
    Text = "數字從來並非名稱，只是符號。\n凡庸的生命不願割捨自身虛構的獨特性，故而抗拒以數字作為自己的代稱。\n她從不在意。"
  },
  Stage_70926_Desc = {
    Text = "可能性不等同於好的結局，但蜃景亦是前行者的餌料。"
  },
  Stage_70927_Desc = {
    Text = "咕嚕，咕嚕，咕嚕。器官發出迫切渴求的悲呼。\n不是肚中饑鳴，它的空虛源自大腦。"
  },
  Stage_70927_Name = {
    Text = "人間食糧"
  },
  Stage_70928_Desc = {
    Text = "雨。綿延不絕的雨。"
  },
  Stage_70929_Desc = {
    Text = "一階一階一階，祂的觸肢探向深夢的底層。"
  },
  Stage_70929_Name = {Text = "深夢"},
  Stage_70930_Desc = {
    Text = "眼睛，我不敢在夢中相遇\n在死亡的夢幻國土"
  },
  Stage_70931_Desc = {
    Text = "人類將唯一定義為真相。\n你所得見的即為世界的真實面貌。"
  },
  Stage_70932_Desc = {
    Text = "你看吶，那圓潤光澤的蘋果多麼誘人。\n輕輕咬上一口，擺脫一切煩惱吧。"
  },
  Stage_70932_Name = {
    Text = "有毒的蘋果"
  },
  Stage_70933_Desc = {
    Text = "全部都和回憶裡一樣。"
  },
  Stage_70933_Name = {
    Text = "親切的與勇敢的"
  },
  Stage_70934_Desc = {
    Text = "逝去的不會再回來。\n除非，是在另一個世界。"
  },
  Stage_70934_Name = {
    Text = "我們已經失去"
  },
  Stage_70935_Desc = {
    Text = "反拍，反拍，音符遊走在預期的旋律節奏之外。"
  },
  Stage_70936_Desc = {
    Text = "逃脫一處陷阱，進入另一個更大的牢籠。"
  },
  Stage_70936_Name = {Text = "逃脫"},
  Stage_70937_Desc = {
    Text = "缸中之腦會夢見機械義體嗎？"
  },
  Stage_70937_Name = {
    Text = "缸中之夢"
  },
  Stage_71748_Desc = {
    Text = "「噓……你猜，我透過你的眼睛看見了什麼？」\n在奧瑞塔被守密人嚇哭以後，守密人房間的第四面牆差點被蘿坦推倒，因為奧瑞塔哭得實在是太讓人心慌了。"
  },
  Stage_71748_Name = {
    Text = "戲劇的第四壁·之七"
  },
  Stage_71749_Desc = {
    Text = "不要每時每刻都用內容轟炸觀眾的腦子，要給他們留下思考空間，最好是完全靜止的——真希望朵爾在上課時能熟練運用這種技巧，守密人這麼呢喃著，得到了所有人的認同。"
  },
  Stage_71749_Name = {
    Text = "靜場時刻·之七"
  },
  Stage_71750_Desc = {
    Text = "在故事的結尾，需要體現角色的發展或者變化。可是在生活中，弧光往往會連成一個圓。"
  },
  Stage_71750_Name = {
    Text = "弧光理論·之七"
  },
  Stage_71751_Desc = {
    Text = "一個提前設定好的場景，幾個互相熟識的演員。剩下的，就交給靈感與碰撞。"
  },
  Stage_71751_Name = {
    Text = "假面喜劇·之七"
  },
  Stage_71752_Desc = {
    Text = "這是一個連拉蒙娜都沒有聽過的詞，在某些年邁喚醒體的幫助下，大家才終於明白：有時候，大哭一場才是處理壞情緒的唯一方法。"
  },
  Stage_71753_Desc = {
    Text = "「不要讓觀眾全身心沉浸在劇情中，要讓他們分析、批判舞臺上正在發生的事情。」\n對這條理論，奧瑞塔如此評價：奧瑞塔不想要被任何人罵！奧瑞塔只想和大家成為好朋友！"
  },
  Stage_71754_Desc = {
    Text = "急轉直下，突發情節，故事突變——守密人感覺，這似乎在描述有時的自己。"
  },
  Stage_71754_Name = {
    Text = "情節輪轉·之七"
  },
  Stage_71755_Desc = {
    Text = "卡茜亞找到的理論書中如此寫道：故事發生的時間不能超過一天，舞臺也不能超過一處……\n守密人聽到這裡時，就放棄了繼續讀下去。畢竟，一天的時間，有時還不夠守密人完成一次「融蝕與災厄處理」的課後作業論文。"
  },
  Stage_71756_Desc = {
    Text = "在卡茜亞找到的理論書中寫道：金字塔模型往往著眼於一場危機的解決。\n但是很可惜，不是每場危機都能在現實中得到解決。它們被和平假像所隱瞞、掩蓋，在暗中滋生，最後爆發為新的「金字塔」。"
  },
  Stage_71756_Name = {
    Text = "劇作金字塔·之七"
  },
  Stage_71810_Desc = {
    Text = "她有很多身分：名媛、商人、掮客、收藏家……\n唯獨沒有她自己——很遺憾，薔薇夫人從不為此失落。\n對她而言，原始的、未經雕琢的事物不值一提，複雜與渾濁才是最頂級的審美。"
  },
  Stage_71810_Name = {
    Text = "臉·之七"
  },
  Stage_71811_Desc = {
    Text = "她的長腿叔叔和旁人不同：他是由霧做成的。\n鑒於女孩早已丟失對人類的信任，霧或者金子、符號做成的人都沒有什麼區別。\n當然，她終將為自己的錯誤判斷付出代價——但那已經是很久以後的故事了。"
  },
  Stage_71811_Name = {
    Text = "長腿叔叔·之七"
  },
  Stage_71812_Desc = {
    Text = "臨行前，傳記作家回望這棟薔薇盛開的美麗宅邸，它遠抵不上主人光芒的萬分之一。\n有關索蕾爾夫人的傳說還在繼續，就在此刻的當下發生，我們都將成為見證。"
  },
  Stage_71812_Name = {
    Text = "終曲·之七"
  },
  Stage_71813_Desc = {
    Text = "插花、刺繡、茶藝……她的生活由一串無意義的符號構成。\n「早安，索蕾爾小姐」「你真棒，索蕾爾小姐」……\n故作愉悅的聲音就像厚厚的魚缸，將她永遠圈養。"
  },
  Stage_71813_Name = {
    Text = "釜底遊魚·之七"
  },
  Stage_71814_Desc = {
    Text = "美貌是無形的線，輕鬆捆住人們的心。她隨意地撥弄絲線，彷彿最漫不經心的天才。\n很快她便厭倦了這個遊戲，因為透過他們醜陋的面容，她窺見自身。"
  },
  Stage_71814_Name = {
    Text = "傀儡遊戲·之七"
  },
  Stage_71815_Desc = {
    Text = "她在生日那天收到了一個禮物：一件精心縫製的白色羅裙。\n然後她被告知，自己將身著這件禮物，變成父母贈予他人的禮物。"
  },
  Stage_71815_Name = {
    Text = "禮物·之七"
  },
  Stage_71816_Desc = {
    Text = "她像磁石一樣緊緊吸引著周圍人的目光。\n豔羨的、驚愕的、嫉恨的、貪婪的……唯獨沒有平靜，一如她今後的命運。"
  },
  Stage_71817_Desc = {
    Text = "那天晚上，她夢見了黑霧，夢見它有了生氣，在顫動。\n不是虎和馬的、難以形容的雜種，而兼有那兩種動物的性質。\n同時又是一隻黑貓、一朵薔薇、一場暴風雨。"
  },
  Stage_71817_Name = {
    Text = "薔薇角·之七"
  },
  Stage_71818_Desc = {
    Text = "她將按照劇本的指示，演完一場場劇碼，掀起無盡的混亂。\n而她，便是在風暴眼中翩翩起飛的舞者。\n她一向都是最敬業的演員。"
  },
  Stage_71818_Name = {
    Text = "未完的劇本·之七"
  },
  Stage_71852_Desc = {
    Text = "他端坐於高高的青石王座，獨享著永恆的崇高與孤獨。"
  },
  Stage_71853_Desc = {
    Text = "我將親手為我戴上，那無限的力量與榮光。"
  },
  Stage_71854_Desc = {
    Text = "除了祈禱神明帶來奇蹟，渺小的人類別無選擇。"
  },
  Stage_71854_Name = {Text = "天災"},
  Stage_71855_Desc = {
    Text = "那頂王冠的重量，早早地便壓在了那群孩子們的身上。"
  },
  Stage_71923_Desc = {
    Text = "黑暗自深淵湧現，闖入者於緊攥心臟的恐懼中掙扎，在被黑暗吞沒之前。"
  },
  Stage_71923_Name = {
