  Stage_71931_Name = {
    Text = "融災禁區·第3波·V級警報"
  },
  Stage_71932_Desc = {
    Text = "黑暗自深淵湧現，闖入者於緊攥心臟的恐懼中掙扎，在被黑暗吞沒之前。"
  },
  Stage_71932_Name = {
    Text = "融災禁區·第2波·V級警報"
  },
  Stage_72063_Desc = {
    Text = "眼睛，我不敢在夢中相遇\n在死亡的夢幻國土"
  },
  Stage_72064_Desc = {
    Text = "人類將唯一定義為真相。\n你所得見的即為世界的真實面貌。"
  },
  Stage_72065_Desc = {
    Text = "你看吶，那圓潤光澤的蘋果多麼誘人。\n輕輕咬上一口，擺脫一切煩惱吧。"
  },
  Stage_72065_Name = {
    Text = "有毒的蘋果"
  },
  Stage_72066_Desc = {
    Text = "全部都和回憶裡一樣。"
  },
  Stage_72066_Name = {
    Text = "親切的與勇敢的"
  },
  Stage_72067_Desc = {
    Text = "逝去的不會再回來。\n除非，是在另一個世界。"
  },
  Stage_72067_Name = {
    Text = "我們已經失去"
  },
  Stage_72068_Desc = {
    Text = "反拍，反拍，音符遊走在預期的旋律節奏之外。"
  },
  Stage_72069_Desc = {
    Text = "逃脫一處陷阱，進入另一個更大的牢籠。"
  },
  Stage_72069_Name = {Text = "逃脫"},
  Stage_72070_Desc = {
    Text = "親愛的，讓我們去看看末日。\n與其在絕望中日益衰朽，不如趁著命運尚未降臨，親手建樹終末的偉業。"
  },
  Stage_72070_Name = {
    Text = "未選擇的路"
  },
  Stage_72071_Desc = {
    Text = "數字從來並非名稱，只是符號。\n凡庸的生命不願割捨自身虛構的獨特性，故而抗拒以數字作為自己的代稱。\n她從不在意。"
  },
  Stage_72072_Desc = {
    Text = "咕嚕，咕嚕，咕嚕。器官發出迫切渴求的悲呼。\n不是肚中饑鳴，它的空虛源自大腦。"
  },
  Stage_72072_Name = {
    Text = "人間食糧"
  },
  Stage_74229_Desc = {
    Text = "你與那一抹飛揚的裙擺不期而遇，那旋轉的舞裙多麼像天鵝翻飛的翅膀，又多麼像一朵燃燒的火焰。"
  },
  Stage_74230_Desc = {
    Text = "這裡不該是藝術的殿堂嗎？否則怎會有那許多令人目眩的優雅舞姿。\n但這裡真是藝術的殿堂嗎？不然又為何充滿那樣多冰冷油膩的視線？"
  },
  Stage_74230_Name = {
    Text = "燃燒的堅冰"
  },
  Stage_74231_Desc = {
    Text = "夢中的天鵝高高飛起，又於獵人的捕網中狠狠摔落在地。"
  },
  Stage_74231_Name = {
    Text = "仲夏夜之夢"
  },
  Stage_74232_Desc = {
    Text = "青色的舞者在舞台上起舞。\n青色的烈焰在火焰中燃烧。\n為慨然赴死的天鵝，敬獻最後的挽歌。"
  },
  Stage_74232_Name = {
    Text = "天鵝挽歌"
  },
  Stage_74242_Desc = {
    Text = "青色的舞者在舞台上起舞。\n青色的烈焰在火焰中燃烧。\n為慨然赴死的天鵝，敬獻最後的挽歌。"
  },
  Stage_74242_Name = {
    Text = "天鵝挽歌"
  },
  Stage_74243_Desc = {
    Text = "青色的舞者在舞台上起舞。\n青色的烈焰在火焰中燃烧。\n為慨然赴死的天鵝，敬獻最後的挽歌。"
  },
  Stage_74243_Name = {
    Text = "天鵝挽歌"
  },
  Stage_74328_Desc = {
    Text = "條件已經就緒，熱血正在沸騰，現在，決鬥開始。"
  },
  Stage_74328_Name = {
    Text = "貫徹意志的決鬥"
  },
  Stage_74329_Desc = {
    Text = "即使身處絕境，也不要放棄希望。因為每個瞬間，都有可能成為逆轉一切的開始。"
  },
  Stage_74329_Name = {
    Text = "逆轉萬象的瞬間"
  },
  Stage_74330_Desc = {
    Text = "一場意外讓相位對弈空間迎來了一位特殊來客。為了奪回對弈空間，你踏上了成為最強卡牌大師的旅途。"
  },
  Stage_74330_Name = {
    Text = "來自異界的客人"
  },
  Stage_74975_Desc = {
    Text = "「它是唯一，它是全部，它是開啟真相之門的希望。」\n無數鑰匙圍成了一個圈。它們自天空中墜落，帶給人們沉甸甸的希望。\n也帶來沉甸甸的墳墓。"
  },
  Stage_74975_Name = {
    Text = "幻夢深潛Ⅵ"
  },
  Stage_74976_Desc = {
    Text = "「它是唯一，它是全部，它是開啟真相之門的希望。」\n無數鑰匙圍成了一個圈。它們自天空中墜落，帶給人們沉甸甸的希望。\n也帶來沉甸甸的墳墓。"
  },
