  },
  Stage_75024_Desc = {
    Text = "坍塌的偶像注視著自己的子民。\n看他們生存、繁衍、互相爭鬥，然後將自己徹底遺忘。\n坍塌的偶像懷念著自己的子民。"
  },
  Stage_75024_Name = {
    Text = "幻夢深潛·癲狂"
  },
  Stage_75025_Desc = {
    Text = "「每把鑰匙都有唯一的編號，只對應唯一的調查員。」\n「因此，每把鑰匙的隕落也對應著唯一的調查員之死。」\n「真好啊。就連死亡都是獨一無二的。」"
  },
