  },
  Stage_75180_Name = {
    Text = "幻夢深潛Ⅳ"
  },
  Stage_75181_Desc = {
    Text = "「每把鑰匙都有唯一的編號，只對應唯一的調查員。」\n「因此，每把鑰匙的隕落也對應著唯一的調查員之死。」\n「真好啊。就連死亡都是獨一無二的。」"
  },
  Stage_75181_Name = {
    Text = "幻夢深潛·癲狂"
  },
  Stage_75182_Desc = {
    Text = "「它是唯一，它是全部，它是開啟真相之門的希望。」\n無數鑰匙圍成了一個圈。它們自天空中墜落，帶給人們沉甸甸的希望。\n也帶來沉甸甸的墳墓。"
