  },
  Stage_75254_Desc = {
    Text = "「每把鑰匙都有唯一的編號，只對應唯一的調查員。」\n「因此，每把鑰匙的隕落也對應著唯一的調查員之死。」\n「真好啊。就連死亡都是獨一無二的。」"
