    Text = "它早已忘記了自己的名字，連與她初次相逢那天的記憶都已開始模糊。\n唯有那雙手，那雙輕輕牽起它的手，始終溫暖著它野蠻而孤獨的靈魂。\n於是它從她的手中接過那美麗的頭顱，自願套上那永恆的面具與枷鎖。"
  },
  Stage_75763_Name = {
    Text = "它與她·之六"
  },
  Stage_75764_Desc = {
    Text = "屍體，血腥氣，不翼而飛的頭顱。\n她會保護你嗎？還是亦將取走你的性命。"
  },
