  Stage_75777_Name = {
    Text = "歸於灰海·之四"
  },
  Stage_7635_Desc = {
    Text = "它們像捉摸不定的魔法師，遊走在時空的夾縫裡。\n沒有仇恨，沒有恐懼，也沒有憐憫。"
  },
  Stage_7635_Name = {
    Text = "維度殘像Ⅱ"
  },
  Stage_7636_Desc = {
    Text = "她以己身承納聖骸，以教義訓導眷眾，以毒牙布散信仰。"
  },
  Stage_7636_Name = {
    Text = "虔誠之握Ⅲ"
  },
  Stage_7637_Desc = {
    Text = "早在群星誕生之前，它們便存在於此。\n它們既是虛無，也是一切。"
  },
  Stage_7637_Name = {
    Text = "渾濁殘像Ⅴ"
  },
  Stage_7638_Desc = {
    Text = "它們無言地守護著海洋的秘密，靈魂和宇宙一樣深沉。"
  },
  Stage_7638_Name = {
    Text = "海淵殘像Ⅴ"
  },
  Stage_76399_Desc = {
    Text = "黑暗自深淵湧現，闖入者於緊攥心臟的恐懼中掙扎，在被黑暗吞沒之前。"
  },
  Stage_76399_Name = {
    Text = "融災禁區·第4波·V級警報"
  },
  Stage_7639_Desc = {
    Text = "它們在黑暗中扭曲、融合，然後被小心翼翼地保管在造像裡。\n這是一次蓄謀已久的重逢。"
  },
  Stage_7639_Name = {
    Text = "超維之旅·間隙Ⅰ"
  },
