  Stage_7646_Name = {
    Text = "幻夢深潛Ⅱ"
  },
  Stage_7647_Desc = {
    Text = "「它是唯一，它是全部，它是開啟真相之門的希望。」\n無數鑰匙圍成了一個圈。它們自天空中墜落，帶給人們沉甸甸的希望。\n也帶來沉甸甸的墳墓。"
  },
  Stage_7647_Name = {
    Text = "幻夢深潛Ⅰ"
  },
  Stage_7648_Desc = {
    Text = "它一刻不停地追逐那些打破規則的僭越者。\n至於何為「規則」，何為「打破」？\n獵犬從不思考——那只會阻礙它奔襲的速度。"
  },
  Stage_7649_Desc = {
    Text = "倫蒂尼恩以燦爛的工業文明，以及籠罩市區的鉛灰色濃霧聞名。\n霧氣無處不在，對路人來說是更像是一種偶然、無意義的不便。"
  },
  Stage_7649_Name = {
    Text = "怪霧之都Ⅱ"
  },
  Stage_7650_Desc = {
    Text = "來歷不明的造像在黑暗中遊蕩、戰慄。\n它們踏著古老的節拍，循著來自遠方的笛聲起舞。"
  },
  Stage_7650_Name = {
    Text = "血肉之沼·間隙Ⅶ"
  },
  Stage_7651_Desc = {
    Text = "一堆粗魯的、未消化的物質。人們稱其為排泄物，或是混沌。 \n世界從排泄物中誕生。"
  },
  Stage_7652_Desc = {
    Text = "蠕動著、流淌著……原生質的腫泡正從枷鎖的縫隙中溜走。\n這是她為「自由」付出的代價。"
  },
  Stage_7652_Name = {
    Text = "漆黑之鏈Ⅲ"
  },
  Stage_7653_Desc = {
    Text = "「門」即將開啟，你從中窺見一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是渾濁的。"
  },
  Stage_7653_Name = {
    Text = "超維之旅·輪轉間隙Ⅰ"
  },
  Stage_7654_Desc = {
    Text = "「門」即將開啟，你從中窺見一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是渾濁的。"
  },
  Stage_7654_Name = {
    Text = "超維之旅·輪轉間隙Ⅰ"
  },
  Stage_7655_Desc = {
    Text = "「門」即將開啟，你從中窺見一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是渾濁的。"
  },
  Stage_7655_Name = {
    Text = "超維之旅·輪轉間隙Ⅰ"
  },
  Stage_7656_Desc = {
    Text = "它以乖巧的姿態靠在床沿，暗淡的紐扣眼睛望著虛空。\n小小的身軀承受了主人的全部眼淚，卻無法出言安慰。"
  },
  Stage_7656_Name = {
    Text = "玩偶之淚Ⅴ"
  },
  Stage_7657_Desc = {
    Text = "它們原本是悲傷、扭曲和懵懂組成的無意識集合，\n卻被打扮成幸福的小孩、大人和寵物。\n因著從未品嘗過幸福的滋味，它們成了最糟糕的演員。"
  },
  Stage_7657_Name = {
    Text = "蠟像之秘Ⅴ"
  },
  Stage_7658_Desc = {
    Text = "「門」已被開啟，幻夢即將清醒。\n噓……不可注視，不可諦聽。"
  },
  Stage_7658_Name = {
    Text = "混沌之域·間隙Ⅳ"
  },
  Stage_7659_Desc = {
    Text = "風雨仍在醞釀，一切尚未終結。"
  },
  Stage_7659_Name = {
    Text = "現實重啟"
  },
  Stage_7660_Desc = {
    Text = "沒有華麗的佈景，也沒有動人的女主角。\n——這是一場由三個男人演出的乏味劇碼。"
  },
  Stage_7660_Name = {
    Text = "嚮導，巫師和奴隸"
  },
  Stage_7661_Desc = {
    Text = "迎著風與黃沙，戰士義無反顧地奔向太陽。"
  },
  Stage_7661_Name = {
    Text = "太陽遠征"
  },
  Stage_7662_Desc = {
    Text = "朋友們，停下打鬧和紛爭吧。\n祭祀的火焰已經升起，請享受這死亡前最後的寧靜……"
  },
  Stage_7662_Name = {Text = "紅祭禮"},
  Stage_7663_Desc = {
    Text = "嚴格意義來講，這並非一出悲劇。\n戰士的字典裡沒有「悲劇」。"
  },
  Stage_7663_Name = {
    Text = "悲劇的謝幕"
  },
  Stage_7664_Desc = {
    Text = "駛向陸地，駛向一線生機。"
  },
  Stage_7664_Name = {
    Text = "悲劇的起航"
  },
  Stage_7665_Desc = {
    Text = "潛藏在宇宙深處的彎曲視界。 \n它能帶你從黑暗抵達另一處黑暗。"
  },
  Stage_7666_Desc = {
    Text = "「門」即將開啟，你從中窺見一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是渾濁的。"
  },
