  Stage_7673_Name = {
    Text = "幻夢深潛Ⅰ"
  },
  Stage_7674_Desc = {
    Text = "坍塌的偶像注視著自己的子民。\n看他們生存、繁衍、互相爭鬥，然後將自己徹底遺忘。\n坍塌的偶像懷念著自己的子民。"
  },
  Stage_7674_Name = {
    Text = "幻夢深潛Ⅲ"
  },
  Stage_7675_Desc = {
    Text = "位於北約克郡的海邊小鎮——斯卡伯勒。這裡擁有高聳的懸崖與金色的海灣，是一處優雅迷人的度假勝地。"
  },
  Stage_7676_Desc = {
    Text = "坍塌的偶像注視著自己的子民。\n看他們生存、繁衍、互相爭鬥，然後將自己徹底遺忘。\n坍塌的偶像懷念著自己的子民。"
  },
  Stage_7676_Name = {
    Text = "幻夢深潛Ⅰ"
  },
  Stage_7677_Desc = {
    Text = "一隻小老鼠，一隻小老鼠。\n跑啊，跑啊，她用切肉刀割掉它的尾巴。"
  },
  Stage_7677_Name = {
    Text = "布朗出擊"
  },
  Stage_7678_Desc = {
    Text = "坍塌的偶像注視著自己的子民。\n看他們生存、繁衍、互相爭鬥，然後將自己徹底遺忘。\n坍塌的偶像懷念著自己的子民。"
  },
  Stage_7678_Name = {
    Text = "幻夢深潛Ⅶ"
  },
  Stage_7679_Desc = {
    Text = "坍塌的偶像注視著自己的子民。\n看他們生存、繁衍、互相爭鬥，然後將自己徹底遺忘。\n坍塌的偶像懷念著自己的子民。"
  },
  Stage_7679_Name = {
    Text = "幻夢深潛Ⅵ"
  },
  Stage_7680_Desc = {
    Text = "噢，手臂，惱人的手臂！它們總是揪著我的頭髮不放。"
  },
  Stage_7681_Desc = {
    Text = "吧唧咕嘰，裂開了。\n吧唧咕嘰，斷掉了。"
  },
  Stage_7681_Name = {Text = "娃娃館"},
  Stage_7682_Desc = {
    Text = "沒錯，寶貝。盡情地哭吧，把你的痛苦當作絕世名作一樣裝裱起來。"
  },
  Stage_7682_Name = {
    Text = "少女和眼淚"
  },
  Stage_7683_Desc = {
    Text = "是的，是的。眼睛是心靈的牢籠，靈魂是禁錮肉身的枷鎖。"
  },
  Stage_7683_Name = {
    Text = "解剖的憂鬱"
  },
  Stage_7684_Desc = {
    Text = "甜蜜的，香醇的，孩子們的摯愛。\n高雅的，超脫的，成年人的嚮往。"
  },
  Stage_7684_Name = {
    Text = "甜蜜的藝術"
  },
  Stage_76854_Desc = {
    Text = "不可見的災難復甦，物理世界的歷史與存在正在墜入深淵。"
  },
