    Text = "融災禁區·第3波·Ⅲ級警報"
  },
  Stage_77098_Desc = {
    Text = "黑暗自深淵湧現，闖入者於緊攥心臟的恐懼中掙扎，在被黑暗吞沒之前。"
  },
  Stage_77098_Name = {
    Text = "融災禁區·第3波·V級警報"
  },
  Stage_77099_Desc = {
    Text = "舊日災厄於此刻蘇生，跨越現世的界碑，引燃墮落的汪洋。"
  },
  Stage_77099_Name = {
    Text = "融災禁區·第1波·Ⅲ級警報"
  },
  Stage_7709_Desc = {
    Text = "皚皚雪原，百合繁盛。"
  },
  Stage_77100_Desc = {
    Text = "黑暗自深淵湧現，闖入者於緊攥心臟的恐懼中掙扎，在被黑暗吞沒之前。"
  },
  Stage_77100_Name = {
    Text = "融災禁區·第5波·V級警報"
  },
  Stage_77101_Desc = {
    Text = "黑暗自深淵湧現，闖入者於緊攥心臟的恐懼中掙扎，在被黑暗吞沒之前。"
  },
  Stage_77101_Name = {
    Text = "融災禁區·第4波·V級警報"
  },
  Stage_77102_Desc = {
    Text = "舊日災厄於此刻蘇生，跨越現世的界碑，引燃墮落的汪洋。"
  },
  Stage_77102_Name = {
    Text = "融災禁區·第4波·Ⅲ級警報"
  },
  Stage_77103_Desc = {
    Text = "舊日災厄於此刻蘇生，跨越現世的界碑，引燃墮落的汪洋。"
  },
  Stage_77103_Name = {
    Text = "融災禁區·第5波·Ⅲ級警報"
  },
  Stage_7710_Desc = {
    Text = "日記是記憶的碎片。\n調查中總是會發現日記的。"
  },
  Stage_7710_Name = {
    Text = "記憶碎片"
  },
  Stage_7711_Desc = {
    Text = "這是一方為她開闢的天地，是偉大的愛意與可怖的囚籠。"
  },
  Stage_7712_Desc = {
    Text = "當勳貴們痛失權柄，當豪富們傾家蕩產，他們寸步難行，就像你現在這樣。"
  },
  Stage_7712_Name = {
    Text = "飛越瘋人院"
  },
  Stage_7713_Desc = {
    Text = "世間的交鋒不止於兵刃相接的戰場，有時也存在於瘋人之口。"
  },
  Stage_7713_Name = {
    Text = "瘋人之口"
  },
  Stage_7714_Desc = {
    Text = "纏繞在迷霧中的軌跡，無數腳步在其上徘徊，每一個踏點都是對命運的追問。"
  },
  Stage_7715_Desc = {
    Text = "寂靜燃燒的火焰，向旅人許下虛妄的諾言。"
  },
  Stage_7715_Name = {
    Text = "誘蛾之火"
  },
  Stage_7716_Desc = {
    Text = "獻上血肉鑄就的現實吧，它們是永不饜足的深淵。"
  },
  Stage_7716_Name = {
    Text = "器質殘像Ⅴ"
  },
  Stage_7717_Desc = {
    Text = "風雨仍在醞釀，一切尚未終結。"
  },
  Stage_7717_Name = {
    Text = "現實重啟"
  },
  Stage_7718_Desc = {
    Text = "駛向陸地，駛向一線生機。"
  },
  Stage_7718_Name = {
    Text = "悲劇的起航"
  },
  Stage_7719_Desc = {
    Text = "那絕非受到期待的生命，只是污濁的寄生蟲罷了。"
  },
  Stage_7720_Desc = {
    Text = "在無盡夜幕的漆黑中追逐著那誘人的光明，猶如一隻逐火之蛾，不顧一切地向著命運的焰火翱翔。"
  },
  Stage_7721_Desc = {
    Text = "夜色被暗流侵蝕，星辰失聲。潛藏著轉折與風雨的危機之月，靜默映照著未知的未來。"
  },
  Stage_7721_Name = {
    Text = "危機之月"
  },
  Stage_7722_Desc = {
    Text = "在命運的狂風中顫抖、掙扎，但它不會真正地飄零。"
  },
  Stage_7722_Name = {
    Text = "搖搖欲墜"
  },
  Stage_7723_Desc = {
    Text = "在過往歲月中飄搖的友誼，結下了新的希望。"
  },
  Stage_7723_Name = {
    Text = "舊友新朋"
  },
  Stage_7724_Desc = {
    Text = "祂的國度是宇宙軀殼，祂的欲望無邊無際。"
  },
  Stage_7724_Name = {
    Text = "蠕蟲之所Ⅲ"
  },
  Stage_7725_Desc = {
    Text = "獻上血肉鑄就的現實吧，它們是永不饜足的深淵。"
  },
  Stage_7725_Name = {
    Text = "器質殘像Ⅱ"
  },
  Stage_7726_Desc = {
    Text = "它們原本是悲傷、扭曲和懵懂組成的無意識集合，\n卻被打扮成幸福的小孩、大人和寵物。\n因著從未品嘗過幸福的滋味，它們成了最糟糕的演員。"
  },
  Stage_7726_Name = {
    Text = "蠟像之秘Ⅰ"
  },
  Stage_7727_Desc = {
    Text = "它以乖巧的姿態靠在床沿，暗淡的紐扣眼睛望著虛空。\n小小的身軀承受了主人的全部眼淚，卻無法出言安慰。"
  },
  Stage_7727_Name = {
    Text = "玩偶之淚Ⅰ"
  },
  Stage_7728_Desc = {
    Text = "「它是唯一，它是全部，它是開啟真相之門的希望。」\n無數鑰匙圍成了一個圈。它們自天空中墜落，帶給人們沉甸甸的希望。\n也帶來沉甸甸的墳墓。"
  },
  Stage_7728_Name = {
    Text = "幻夢深潛Ⅰ"
  },
  Stage_7729_Desc = {
    Text = "「它是唯一，它是全部，它是開啟真相之門的希望。」\n無數鑰匙圍成了一個圈。它們自天空中墜落，帶給人們沉甸甸的希望。\n也帶來沉甸甸的墳墓。"
  },
  Stage_7729_Name = {
    Text = "幻夢深潛Ⅲ"
  },
  Stage_7730_Desc = {
