  },
  Stage_7740_Name = {
    Text = "幻夢深潛Ⅳ"
  },
  Stage_7741_Desc = {
    Text = "「它是唯一，它是全部，它是開啟真相之門的希望。」\n無數鑰匙圍成了一個圈。它們自天空中墜落，帶給人們沉甸甸的希望。\n也帶來沉甸甸的墳墓。"
  },
  Stage_7741_Name = {
    Text = "幻夢深潛Ⅴ"
  },
  Stage_7742_Desc = {
    Text = "坍塌的偶像注視著自己的子民。\n看他們生存、繁衍、互相爭鬥，然後將自己徹底遺忘。\n坍塌的偶像懷念著自己的子民。"
  },
  Stage_7742_Name = {
    Text = "幻夢深潛Ⅰ"
  },
  Stage_7743_Desc = {
    Text = "早在群星誕生之前，它們便存在於此。\n它們既是虛無，也是一切。"
  },
  Stage_7743_Name = {
    Text = "渾濁殘像Ⅰ"
  },
  Stage_7744_Desc = {
    Text = "它們在黑暗中扭曲、融合，然後被小心翼翼地保管在造像裡。\n這是一次蓄謀已久的重逢。"
  },
  Stage_7744_Name = {
    Text = "深海之遺·間隙Ⅰ"
  },
  Stage_7745_Desc = {
    Text = "她以己身承納聖骸，以教義訓導眷眾，以毒牙布散信仰。"
  },
  Stage_7745_Name = {
    Text = "虔誠之握Ⅰ"
  },
  Stage_7746_Desc = {
    Text = "「門」已被開啟，幻夢即將清醒。\n噓……不可注視，不可諦聽。"
  },
  Stage_7746_Name = {
    Text = "深海之遺·間隙Ⅳ"
  },
  Stage_7747_Desc = {
    Text = "拉伊小鎮位於倫蒂尼恩東北部，隱沒在綿延的山脈中。\n沉默的鄉民、無處不在的視線……當心，這裡的一切都不太尋常。"
  },
  Stage_7747_Name = {
    Text = "錯亂異鎮Ⅰ"
  },
  Stage_7749_Desc = {
    Text = "是的，是的。眼睛是心靈的牢籠，靈魂是禁錮肉身的枷鎖。"
  },
  Stage_7749_Name = {
    Text = "解剖的憂鬱"
  },
  Stage_7750_Desc = {
    Text = "虛無乃吾等之源頭，亦為吾等之歸宿。"
  },
  Stage_7750_Name = {
    Text = "不朽的低語"
  },
  Stage_7751_Desc = {
    Text = "沒錯，寶貝。盡情地哭吧，把你的痛苦當作絕世名作一樣裝裱起來。"
  },
  Stage_7751_Name = {
    Text = "少女和眼淚"
  },
  Stage_7752_Desc = {
    Text = "它一刻不停地追逐那些打破規則的僭越者。\n至於何為「規則」，何為「打破」？\n獵犬從不思考——那只會阻礙它奔襲的速度。"
  },
  Stage_7753_Desc = {
    Text = "真實，這殘酷的真實。"
  },
  Stage_7753_Name = {
    Text = "面紗之下"
  },
  Stage_7754_Desc = {
    Text = "「門」即將開啟，你從中窺見一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是渾濁的。"
  },
  Stage_7754_Name = {
    Text = "血肉之沼·輪轉間隙Ⅱ"
  },
  Stage_7755_Desc = {
    Text = "後來，勇士回到故鄉，娶了公主為妻，過上了幸福平靜的生活。\n真的嗎？假的。"
  },
  Stage_7755_Name = {Text = "後記"},
  Stage_7756_Desc = {
    Text = "「門」即將開啟，你從中窺見一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是渾濁的。"
  },
  Stage_7756_Name = {
    Text = "血肉之沼·輪轉間隙Ⅰ"
  },
  Stage_7757_Desc = {
    Text = "「門」即將開啟，你從中窺見一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是渾濁的。"
  },
  Stage_7757_Name = {
    Text = "血肉之沼·輪轉間隙Ⅰ"
  },
  Stage_7758_Desc = {
    Text = "「門」即將開啟，你從中窺見一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是渾濁的。"
  },
  Stage_7758_Name = {
    Text = "血肉之沼·輪轉間隙Ⅰ"
  },
  Stage_7759_Desc = {
    Text = "當雨幕落下，鮮血湧出，我們迎來再度相聚的時刻。\n好久不見，守密人。"
  },
  Stage_7760_Desc = {
    Text = "荒蕪的鐵路橋下，龐大臃腫的怪物發出古怪的低吼。要抵達拉伊瘋人院，就必須跨過這裡。"
  },
  Stage_7760_Name = {
    Text = "船到橋頭自然直"
  },
  Stage_7761_Desc = {
    Text = "成為天才藥理師的第一步。"
  },
  Stage_7761_Name = {
    Text = "製劑淬煉Ⅳ"
  },
  Stage_7762_Desc = {
    Text = "成為天才藥理師的第一步。"
  },
  Stage_7762_Name = {
    Text = "製劑淬煉Ⅴ"
  },
  Stage_7763_Desc = {
    Text = "成為天才藥理師的第一步。"
  },
  Stage_7763_Name = {
    Text = "製劑淬煉Ⅱ"
  },
  Stage_7764_Desc = {
    Text = "成為天才藥理師的第一步。"
  },
  Stage_7764_Name = {
    Text = "製劑淬煉Ⅲ"
  },
  Stage_7765_Desc = {
    Text = "成為天才藥理師的第一步。"
  },
