  },
  Stage_77988_Name = {
    Text = "克珀珊特試玩關卡"
  },
  Stage_77989_Name = {
    Text = "阿拉克涅试玩關卡"
  },
  Stage_7798_Desc = {
    Text = "它以乖巧的姿態靠在床沿，暗淡的紐扣眼睛望著虛空。\n小小的身軀承受了主人的全部眼淚，卻無法出言安慰。"
  },
  Stage_7798_Name = {
    Text = "玩偶之淚Ⅳ"
  },
  Stage_77991_Name = {
    Text = "蘭提戈斯試玩關卡"
  },
  Stage_77994_Name = {
