  },
  Stage_77998_Name = {
    Text = "禿鷲試玩關卡"
  },
  Stage_77999_Name = {
    Text = "卡拉布試玩關卡"
  },
  Stage_7799_Desc = {
    Text = "坍塌的偶像注視著自己的子民。\n看他們生存、繁衍、互相爭鬥，然後將自己徹底遺忘。\n坍塌的偶像懷念著自己的子民。"
  },
  Stage_7799_Name = {
    Text = "幻夢深潛Ⅰ"
  },
  Stage_78001_Name = {
    Text = "凱蒂古拉試玩關卡"
  },
  Stage_78002_Name = {
    Text = "波呂克斯試玩關卡"
  },
