  },
  Stage_7813_Name = {
    Text = "幻夢深潛Ⅵ"
  },
  Stage_7814_Desc = {
    Text = "那是意圖斬破海洋之人的巨刃，是意圖踏平諸海之人的野心。"
  },
  Stage_7814_Name = {
    Text = "狂徒與巨刃"
  },
  Stage_7815_Desc = {
    Text = "現實埋下了禍種，命運卻指引著相遇。"
  },
  Stage_7815_Name = {
    Text = "命運的種子"
  },
  Stage_7816_Desc = {
    Text = "跨越諸海之使徒。"
  },
  Stage_7817_Desc = {
    Text = "在一艘船上，除了船長，還有誰是值得相信的呢？"
  },
  Stage_7817_Name = {Text = "船員"},
  Stage_7818_Desc = {
    Text = "退無可退之時，訓練有素的夥伴往往是破局的關鍵——拉蒙娜再次教會了你這點。"
  },
  Stage_7818_Name = {
    Text = "無路可逃"
  },
  Stage_7819_Desc = {
    Text = "踏破諸海而過的，除了敵人，或許還有希望的微光。"
  },
  Stage_7820_Desc = {
    Text = "夜晚的港口，淳樸的居民，熱情的款待。"
  },
  Stage_7821_Desc = {
    Text = "「門」即將開啟，你從中窺見一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是渾濁的。"
  },
  Stage_7821_Name = {
    Text = "深海之遺·輪轉間隙Ⅱ"
  },
  Stage_7822_Desc = {
    Text = "「門」即將開啟，你從中窺見一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是渾濁的。"
  },
  Stage_7822_Name = {
    Text = "深海之遺·輪轉間隙Ⅱ"
  },
  Stage_7823_Desc = {
    Text = "「門」即將開啟，你從中窺見一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是渾濁的。"
  },
  Stage_7823_Name = {
    Text = "深海之遺·輪轉間隙Ⅱ"
  },
  Stage_7824_Desc = {
    Text = "第二顆心臟在墨菲體內跳動著，阻止「降生儀式」迫在眉睫。"
  },
  Stage_7824_Name = {
    Text = "另一個奇蹟"
  },
  Stage_7825_Desc = {
    Text = "突出重圍永遠不簡單，但好在，這一次守密人找到了最亮的恒星。"
  },
  Stage_7826_Desc = {
    Text = "羅傑斯蠟像館坐落在南華克街的最深處，靠近泰姆河的支流。\n它毫不起眼，卻有眾多先鋒藝術愛好者慕名而來。"
  },
  Stage_7826_Name = {
    Text = "狂躁蠟館Ⅰ"
  },
  Stage_7827_Desc = {
    Text = "他不會是祂，祂不可能是他。\n沒錯……沒錯，只有我的神明，才是真正的他。"
  },
  Stage_7830_Desc = {
    Text = "此處埋葬著一所大學，千瘡百孔，疲憊不堪\n它曾為人類存續奉獻了一點希望與勇氣\n至於結果如何，你現在都看到了"
  },
  Stage_7830_Name = {
    Text = "幻夢深潛Ⅴ"
  },
