  Stage_7833_Desc = {
    Text = "此處埋葬著一所大學，千瘡百孔，疲憊不堪\n它曾為人類存續奉獻了一點希望與勇氣\n至於結果如何，你現在都看到了"
  },
  Stage_7833_Name = {
    Text = "幻夢深潛Ⅰ"
  },
  Stage_7834_Desc = {
    Text = "這裡肆虐的並非普通疾病。"
  },
  Stage_7835_Desc = {
    Text = "在籠罩濟貧院的濃厚迷霧之中，觸碰切割、消失與死亡。"
  },
  Stage_7835_Name = {
    Text = "誰殺死了知更鳥"
  },
  Stage_7836_Desc = {
    Text = "祂的國度是宇宙軀殼，祂的欲望無邊無際。"
  },
  Stage_7836_Name = {
    Text = "蠕蟲之所Ⅴ"
  },
  Stage_7837_Desc = {
    Text = "你與拉蒙娜前往倫蒂尼恩東區的莉莉安濟貧院，展開你作為新晉守密人的第一次調查。\n一切都會很順利，對吧？"
  },
  Stage_7838_Desc = {
    Text = "甜蜜的，香醇的，孩子們的摯愛。\n高雅的，超脫的，成年人的嚮往。"
  },
  Stage_7838_Name = {
    Text = "甜蜜的藝術"
  },
  Stage_7839_Desc = {
    Text = "良心的負重，和誓言等同。"
  },
  Stage_7840_Desc = {
    Text = "危險來自內部。"
  },
  Stage_7840_Name = {
    Text = "內在的危險"
  },
  Stage_7841_Desc = {
    Text = "我多想永遠不用長大，每一天都和你這樣看星星。\n我多想快一點快一點長大，就能保護你們所有人。"
  },
  Stage_7841_Name = {
    Text = "我們的秘密"
  },
  Stage_7842_Desc = {
    Text = "剪斷木偶身上的細線，她就再也不會舞蹈。"
  },
  Stage_7842_Name = {
    Text = "飛鳥不在的夜"
  },
  Stage_7843_Desc = {
    Text = "你想要知道的一切，就在你的眼前，只是你從未發現。"
  },
  Stage_7843_Name = {
    Text = "藏於帽檐下"
  },
  Stage_7844_Desc = {
    Text = "拉蒙娜回歸了隊伍。彌薩格調查員的旅程繼續。"
  },
  Stage_7844_Name = {
    Text = "昨日重現"
  },
  Stage_7845_Desc = {
    Text = "人類的腿腳無法勝過敏捷的四足野生生物，但頭腦可以。只是，在捕獲“地獄犬”之後，等待著你們的又是什麼呢？"
  },
  Stage_7847_Desc = {
    Text = "在地鐵內，你們遭到了神秘刺客的襲擊……"
  },
  Stage_7847_Name = {
    Text = "人生無友"
  },
  Stage_7848_Desc = {
    Text = "與達芙黛爾夫人的往來，永遠是由交易構成的。達芙黛爾出現，向你們提出了交易，而神秘的襲擊者是否會認可這一交易呢？"
  },
  Stage_7849_Desc = {
    Text = "追溯地獄犬“刻耳柏洛斯”的流言，彌薩格的調查員們來到倫蒂尼恩遠郊的小鎮拉伊，探尋失蹤案背後的隱秘……"
  },
  Stage_7849_Name = {
    Text = "三思而後行"
  },
  Stage_7850_Desc = {
    Text = "一個好消息，一個壞消息。消失的線索不會重現，但新的案件已在暗中醞釀。相信吧，調查員不會再兩手空空。"
  },
  Stage_7850_Name = {
    Text = "好消息，壞消息"
  },
  Stage_7851_Desc = {
    Text = "癲狂的語調，濃烈的腥氣，這就是來自拉伊的歡迎儀式。"
  },
  Stage_7851_Name = {
    Text = "歡迎來到拉伊"
  },
  Stage_7852_Desc = {
    Text = "它以乖巧的姿態靠在床沿，暗淡的紐扣眼睛望著虛空。\n小小的身軀承受了主人的全部眼淚，卻無法出言安慰。"
  },
  Stage_7852_Name = {
    Text = "玩偶之淚Ⅲ"
  },
  Stage_7855_Desc = {
    Text = "他不會是祂，祂不可能是他。\n沒錯……沒錯，只有我的神明，才是真正的他。"
  },
  Stage_7856_Desc = {
    Text = "早在群星誕生之前，它們便存在於此。\n它們既是虛無，也是一切。"
  },
  Stage_7856_Name = {
    Text = "渾濁殘像Ⅳ"
  },
  Stage_7857_Desc = {
    Text = "它們無言地守護著海洋的秘密，靈魂和宇宙一樣深沉。"
  },
  Stage_7857_Name = {
    Text = "海淵殘像Ⅱ"
  },
  Stage_7858_Desc = {
    Text = "怎會有永恆不落的夕陽？"
  },
  Stage_7859_Desc = {
    Text = "當雨幕落下，鮮血湧出，我們迎來再度相聚的時刻。\n好久不見，守密人。"
  },
  Stage_7860_Desc = {
    Text = "它們像捉摸不定的魔法師，遊走在時空的夾縫裡。\n沒有仇恨，沒有恐懼，也沒有憐憫。"
  },
  Stage_7860_Name = {
    Text = "維度殘像Ⅰ"
  },
  Stage_7861_Desc = {
    Text = "它一刻不停地追逐那些打破規則的僭越者。\n至於何為「規則」，何為「打破」？\n獵犬從不思考——那只會阻礙它奔襲的速度。"
  },
  Stage_7862_Desc = {
    Text = "它們無言地守護著海洋的秘密，靈魂和宇宙一樣深沉。"
  },
  Stage_7862_Name = {
    Text = "海淵殘像Ⅲ"
  },
  Stage_7863_Desc = {
    Text = "它們無言地守護著海洋的秘密，靈魂和宇宙一樣深沉。"
  },
  Stage_7863_Name = {
    Text = "海淵殘像Ⅰ"
  },
  Stage_7864_Desc = {
    Text = "倫蒂尼恩以燦爛的工業文明，以及籠罩市區的鉛灰色濃霧聞名。\n霧氣無處不在，對路人來說是更像是一種偶然、無意義的不便。"
  },
  Stage_7864_Name = {
    Text = "怪霧之都Ⅰ"
  },
  Stage_7865_Desc = {
    Text = "是什麼蒙蔽了她的雙眼？\n是愛、憐憫、正義和過分的感恩嗎？"
  },
  Stage_7865_Name = {Text = "超脫"},
  Stage_7866_Desc = {
    Text = "孩子向母親伸出雙手，祈求一個充滿疼痛的擁抱。\n即使注射針刺破纖嫩表皮，手術刀劃開潔白肌膚，束縛帶捆紮柔弱關節。\n蔓延的無邊疼痛依然無法阻止她們相擁。\n因為，這是最溫暖的擁抱。自胚胎脫出母體，生出嫌隙，磨出鋒銳，相互傷害，最終回歸親密，融為一體。"
  },
  Stage_7867_Desc = {
    Text = "你沉睡在夜晚的寂靜之中，\n沒有剩下任何的疑惑或爭端，\n就像擁有永恆的擁抱，\n我們躺在平靜的安定之中。"
  },
  Stage_7867_Name = {Text = "房間"},
  Stage_7868_Desc = {
    Text = "皚皚雪原，百合繁盛。"
  },
  Stage_7869_Desc = {
    Text = "黎明總會到來，太陽照常升起。"
  },
  Stage_7869_Name = {Text = "尾聲"},
  Stage_7870_Desc = {
    Text = "她以己身承納聖骸，以教義訓導眷眾，以毒牙布散信仰。"
  },
  Stage_7870_Name = {
    Text = "虔誠之握Ⅱ"
  },
  Stage_7871_Desc = {
    Text = "鋒銳的利刺打破絕對的圓弧，並非“刻耳柏洛斯”之物自裂隙生出。"
  },
  Stage_7871_Name = {
    Text = "殼中裂縫"
  },
  Stage_7872_Desc = {
    Text = "現實埋下了禍種，命運卻指引著相遇。"
  },
  Stage_7872_Name = {
    Text = "命運的種子"
  },
  Stage_78738_Name = {
    Text = "本源沉睡之主試玩關卡"
  },
  Stage_7873_Desc = {
    Text = "它們在黑暗中扭曲、融合，然後被小心翼翼地保管在造像裡。\n這是一次蓄謀已久的重逢。"
  },
  Stage_7873_Name = {
    Text = "深海之遺·間隙Ⅴ"
  },
  Stage_7874_Desc = {
    Text = "在一艘船上，除了船長，還有誰是值得相信的呢？"
  },
  Stage_7874_Name = {Text = "船員"},
  Stage_7875_Desc = {
    Text = "跨越諸海之使徒。"
  },
  Stage_7876_Desc = {
    Text = "踏破諸海而過的，除了敵人，或許還有希望的微光。"
  },
  Stage_78773_Name = {
    Text = "本源深海淑女試玩關卡"
  },
  Stage_7877_Desc = {
    Text = "它們原本是悲傷、扭曲和懵懂組成的無意識集合，\n卻被打扮成幸福的小孩、大人和寵物。\n因著從未品嘗過幸福的滋味，它們成了最糟糕的演員。"
  },
  Stage_7877_Name = {
    Text = "蠟像之秘Ⅱ"
  },
  Stage_7878_Desc = {
    Text = "夜晚的港口，淳樸的居民，熱情的款待。"
  },
  Stage_7879_Desc = {
    Text = "來歷不明的造像在黑暗中遊蕩、戰慄。\n它們踏著古老的節拍，循著來自遠方的笛聲起舞。"
  },
  Stage_7879_Name = {
    Text = "血肉之沼·間隙Ⅷ"
  },
  Stage_7880_Desc = {
    Text = "突出重圍永遠不簡單，但好在，這一次守密人找到了最亮的恒星。"
  },
  Stage_7881_Desc = {
    Text = "第二顆心臟在墨菲體內跳動著，阻止「降生儀式」迫在眉睫。"
  },
  Stage_7881_Name = {
    Text = "另一個奇蹟"
  },
  Stage_7882_Desc = {
    Text = "來歷不明的造像在黑暗中遊蕩、戰慄。\n它們踏著古老的節拍，循著來自遠方的笛聲起舞。"
  },
  Stage_7882_Name = {
    Text = "混沌之域·間隙Ⅶ"
  },
  Stage_7883_Desc = {
    Text = "真實，這殘酷的真實。"
  },
  Stage_7883_Name = {
    Text = "面紗之下"
  },
  Stage_7884_Desc = {
    Text = "寂靜燃燒的火焰，向旅人許下虛妄的諾言。"
  },
  Stage_7884_Name = {
    Text = "誘蛾之火"
  },
  Stage_7885_Desc = {
    Text = "在命運的狂風中顫抖、掙扎，但它不會真正地飄零。"
  },
  Stage_7885_Name = {
    Text = "搖搖欲墜"
  },
  Stage_7886_Desc = {
    Text = "纏繞在迷霧中的軌跡，無數腳步在其上徘徊，每一個踏點都是對命運的追問。"
  },
  Stage_7887_Desc = {
    Text = "坍塌的偶像注視著自己的子民。\n看他們生存、繁衍、互相爭鬥，然後將自己徹底遺忘。\n坍塌的偶像懷念著自己的子民。"
  },
  Stage_7887_Name = {
    Text = "幻夢深潛Ⅳ"
  },
  Stage_7888_Desc = {
    Text = "一堆粗魯的、未消化的物質。人們稱其為排泄物，或是混沌。 \n世界從排泄物中誕生。"
  },
  Stage_7889_Desc = {
    Text = "當離去的被人遺忘，一切都將回歸常態。\n但那些消散的記憶，總會有人記得。"
  },
  Stage_7890_Desc = {
    Text = "「它是唯一，它是全部，它是開啟真相之門的希望。」\n無數鑰匙圍成了一個圈。它們自天空中墜落，帶給人們沉甸甸的希望。\n也帶來沉甸甸的墳墓。"
  },
  Stage_7890_Name = {
    Text = "幻夢深潛Ⅴ"
  },
  Stage_7891_Desc = {
    Text = "坍塌的偶像注視著自己的子民。\n看他們生存、繁衍、互相爭鬥，然後將自己徹底遺忘。\n坍塌的偶像懷念著自己的子民。"
  },
  Stage_7891_Name = {
    Text = "幻夢深潛Ⅰ"
  },
  Stage_7892_Desc = {
    Text = "坍塌的偶像注視著自己的子民。\n看他們生存、繁衍、互相爭鬥，然後將自己徹底遺忘。\n坍塌的偶像懷念著自己的子民。"
  },
  Stage_7892_Name = {
    Text = "幻夢深潛Ⅱ"
  },
  Stage_7893_Desc = {
    Text = "坍塌的偶像注視著自己的子民。\n看他們生存、繁衍、互相爭鬥，然後將自己徹底遺忘。\n坍塌的偶像懷念著自己的子民。"
  },
  Stage_7893_Name = {
    Text = "幻夢深潛Ⅲ"
  },
  Stage_7894_Desc = {
    Text = "坍塌的偶像注視著自己的子民。\n看他們生存、繁衍、互相爭鬥，然後將自己徹底遺忘。\n坍塌的偶像懷念著自己的子民。"
  },
  Stage_7894_Name = {
    Text = "幻夢深潛Ⅳ"
  },
  Stage_7895_Desc = {
    Text = "坍塌的偶像注視著自己的子民。\n看他們生存、繁衍、互相爭鬥，然後將自己徹底遺忘。\n坍塌的偶像懷念著自己的子民。"
  },
  Stage_7895_Name = {
    Text = "幻夢深潛Ⅴ"
  },
  Stage_7896_Desc = {
    Text = "坍塌的偶像注視著自己的子民。\n看他們生存、繁衍、互相爭鬥，然後將自己徹底遺忘。\n坍塌的偶像懷念著自己的子民。"
  },
  Stage_7896_Name = {
    Text = "幻夢深潛Ⅵ"
  },
  Stage_7897_Desc = {
    Text = "坍塌的偶像注視著自己的子民。\n看他們生存、繁衍、互相爭鬥，然後將自己徹底遺忘。\n坍塌的偶像懷念著自己的子民。"
  },
  Stage_7897_Name = {
    Text = "幻夢深潛Ⅶ"
  },
  Stage_7898_Desc = {
    Text = "在籠罩濟貧院的濃厚迷霧之中，觸碰切割、消失與死亡。"
  },
  Stage_7898_Name = {
    Text = "誰殺死了知更鳥"
  },
  Stage_7899_Desc = {
    Text = "這裡肆虐的並非普通疾病。"
  },
  Stage_7900_Desc = {
    Text = "你與拉蒙娜前往倫蒂尼恩東區的莉莉安濟貧院，展開你作為新晉守密人的第一次調查。\n一切都會很順利，對吧？"
  },
  Stage_7901_Desc = {
    Text = "良心的負重，和誓言等同。"
  },
  Stage_7902_Desc = {
    Text = "甜蜜的，香醇的，孩子們的摯愛。\n高雅的，超脫的，成年人的嚮往。"
  },
  Stage_7902_Name = {
    Text = "甜蜜的藝術"
  },
  Stage_7903_Desc = {
    Text = "我多想永遠不用長大，每一天都和你這樣看星星。\n我多想快一點快一點長大，就能保護你們所有人。"
  },
  Stage_7903_Name = {
    Text = "我們的秘密"
  },
  Stage_7904_Desc = {
    Text = "危險來自內部。"
  },
  Stage_7904_Name = {
    Text = "內在的危險"
  },
  Stage_7905_Desc = {
    Text = "「門」已被開啟，幻夢即將清醒。\n噓……不可注視，不可諦聽。"
  },
  Stage_7905_Name = {
    Text = "血肉之沼·輪轉間隙Ⅳ"
  },
  Stage_7906_Desc = {
    Text = "「門」已被開啟，幻夢即將清醒。\n噓……不可注視，不可諦聽。"
  },
  Stage_7906_Name = {
    Text = "血肉之沼·輪轉間隙Ⅳ"
  },
  Stage_7907_Desc = {
    Text = "「門」已被開啟，幻夢即將清醒。\n噓……不可注視，不可諦聽。"
  },
  Stage_7907_Name = {
    Text = "血肉之沼·輪轉間隙Ⅳ"
  },
  Stage_7908_Desc = {
    Text = "剪斷木偶身上的細線，她就再也不會舞蹈。"
  },
  Stage_7908_Name = {
    Text = "飛鳥不在的夜"
  },
  Stage_7909_Desc = {
    Text = "拉蒙娜回歸了隊伍。彌薩格調查員的旅程繼續。"
  },
  Stage_7909_Name = {
    Text = "昨日重現"
  },
  Stage_7910_Desc = {
    Text = "你想要知道的一切，就在你的眼前，只是你從未發現。"
  },
  Stage_7910_Name = {
    Text = "藏於帽檐下"
  },
  Stage_7912_Desc = {
    Text = "人類的腿腳無法勝過敏捷的四足野生生物，但頭腦可以。只是，在捕獲“地獄犬”之後，等待著你們的又是什麼呢？"
  },
  Stage_7913_Desc = {
    Text = "與達芙黛爾夫人的往來，永遠是由交易構成的。達芙黛爾出現，向你們提出了交易，而神秘的襲擊者是否會認可這一交易呢？"
  },
  Stage_7914_Desc = {
    Text = "在地鐵內，你們遭到了神秘刺客的襲擊……"
  },
  Stage_7914_Name = {
    Text = "人生無友"
  },
  Stage_7915_Desc = {
    Text = "追溯地獄犬“刻耳柏洛斯”的流言，彌薩格的調查員們來到倫蒂尼恩遠郊的小鎮拉伊，探尋失蹤案背後的隱秘……"
  },
  Stage_7915_Name = {
    Text = "三思而後行"
  },
  Stage_7916_Desc = {
    Text = "癲狂的語調，濃烈的腥氣，這就是來自拉伊的歡迎儀式。"
  },
  Stage_7916_Name = {
    Text = "歡迎來到拉伊"
  },
  Stage_7917_Desc = {
    Text = "一個好消息，一個壞消息。消失的線索不會重現，但新的案件已在暗中醞釀。相信吧，調查員不會再兩手空空。"
  },
  Stage_7917_Name = {
    Text = "好消息，壞消息"
  },
  Stage_7918_Desc = {
    Text = "這裡沉睡著一座古老城市的廢墟。\n它和它的主人一樣嗜睡。"
  },
  Stage_7918_Name = {
    Text = "波納佩之墟Ⅳ"
  },
  Stage_7919_Desc = {
    Text = "艾爾沃斯位於卡達斯的極點，終年被不融的冰雪覆蓋，\n厚實而堅硬的冰殼下，隱約潛藏著生命的搏動。"
  },
  Stage_7919_Name = {
    Text = "失序山脈Ⅲ"
  },
  Stage_7920_Desc = {
    Text = "此處埋葬著一所大學，千瘡百孔，疲憊不堪\n它曾為人類存續奉獻了一點希望與勇氣\n至於結果如何，你現在都看到了"
  },
  Stage_7920_Name = {
    Text = "幻夢深潛Ⅶ"
  },
  Stage_7921_Desc = {
    Text = "它們在黑暗中扭曲、融合，然後被小心翼翼地保管在造像裡。\n這是一次蓄謀已久的重逢。"
  },
  Stage_7921_Name = {
    Text = "血肉之沼·間隙Ⅰ"
  },
  Stage_7922_Desc = {
    Text = "獻上血肉鑄就的現實吧，它們是永不饜足的深淵。"
  },
  Stage_7922_Name = {
    Text = "器質殘像Ⅳ"
  },
  Stage_7923_Desc = {
    Text = "羅傑斯蠟像館坐落在南華克街的最深處，靠近泰姆河的支流。\n它毫不起眼，卻有眾多先鋒藝術愛好者慕名而來。"
  },
  Stage_7923_Name = {
    Text = "狂躁蠟館Ⅳ"
  },
  Stage_7924_Desc = {
    Text = "「它是唯一，它是全部，它是開啟真相之門的希望。」\n無數鑰匙圍成了一個圈。它們自天空中墜落，帶給人們沉甸甸的希望。\n也帶來沉甸甸的墳墓。"
  },
  Stage_7924_Name = {
    Text = "幻夢深潛Ⅱ"
  },
  Stage_7925_Desc = {
    Text = "「它是唯一，它是全部，它是開啟真相之門的希望。」\n無數鑰匙圍成了一個圈。它們自天空中墜落，帶給人們沉甸甸的希望。\n也帶來沉甸甸的墳墓。"
  },
  Stage_7925_Name = {
