  Stage_7930_Name = {
    Text = "幻夢深潛Ⅴ"
  },
  Stage_7931_Desc = {
    Text = "祂的國度是宇宙軀殼，祂的欲望無邊無際。"
  },
  Stage_7931_Name = {
    Text = "蠕蟲之所Ⅱ"
  },
  Stage_7932_Desc = {
    Text = "這裡沉睡著一座古老城市的廢墟。\n它和它的主人一樣嗜睡。"
  },
  Stage_7932_Name = {
    Text = "波納佩之墟Ⅱ"
  },
  Stage_7933_Desc = {
    Text = "真實，這殘酷的真實。"
  },
  Stage_7933_Name = {
    Text = "面紗之下"
  },
  Stage_7934_Desc = {
    Text = "虛無乃吾等之源頭，亦為吾等之歸宿。"
  },
  Stage_7934_Name = {
    Text = "不朽的低語"
  },
  Stage_7935_Desc = {
    Text = "來歷不明的造像在黑暗中遊蕩、戰慄。\n它們踏著古老的節拍，循著來自遠方的笛聲起舞。"
  },
  Stage_7935_Name = {
    Text = "深海之遺·間隙Ⅷ"
  },
  Stage_7936_Desc = {
    Text = "拉伊小鎮位於倫蒂尼恩東北部，隱沒在綿延的山脈中。\n沉默的鄉民、無處不在的視線……當心，這裡的一切都不太尋常。"
  },
  Stage_7936_Name = {
    Text = "錯亂異鎮Ⅱ"
  },
  Stage_7937_Desc = {
    Text = "「每把鑰匙都有唯一的編號，只對應唯一的調查員。」\n「因此，每把鑰匙的隕落也對應著唯一的調查員之死。」\n「真好啊。就連死亡都是獨一無二的。」"
  },
  Stage_7937_Name = {
    Text = "幻夢深潛Ⅴ"
  },
