  Stage_7944_Name = {
    Text = "幻夢深潛Ⅱ"
  },
  Stage_7945_Desc = {
    Text = "她是夢境與現實交錯的界限，是每個仰望夜空的靈魂內心深處的反射。"
  },
  Stage_7945_Name = {
    Text = "倒錯的群星"
  },
  Stage_7945_StageInitStateText = {Text = "海魘"},
  Stage_7946_Desc = {
    Text = "潛藏在宇宙深處的彎曲視界。 \n它能帶你從黑暗抵達另一處黑暗。"
  },
  Stage_7947_Desc = {
    Text = "「門」即將開啟，你從中窺見一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是渾濁的。"
  },
  Stage_7947_Name = {
    Text = "混沌之域·間隙Ⅲ"
  },
  Stage_7948_Desc = {
    Text = "這裡沉睡著一座古老城市的廢墟。\n它和它的主人一樣嗜睡。"
  },
  Stage_7948_Name = {
    Text = "波納佩之墟Ⅴ"
  },
  Stage_7949_Desc = {
    Text = "它以乖巧的姿態靠在床沿，暗淡的紐扣眼睛望著虛空。\n小小的身軀承受了主人的全部眼淚，卻無法出言安慰。"
  },
  Stage_7949_Name = {
    Text = "玩偶之淚Ⅱ"
  },
  Stage_7950_Desc = {
    Text = "為了您的生命健康，遠離尼古丁。"
  },
  Stage_7950_Name = {
    Text = "煙與紫羅蘭"
  },
  Stage_7951_Desc = {
    Text = "來歷不明的造像在黑暗中遊蕩、戰慄。\n它們踏著古老的節拍，循著來自遠方的笛聲起舞。"
  },
  Stage_7951_Name = {
    Text = "血肉之沼·間隙Ⅱ"
  },
  Stage_7952_Desc = {
    Text = "獻上血肉鑄就的現實吧，它們是永不饜足的深淵。"
  },
  Stage_7952_Name = {
    Text = "器質殘像Ⅲ"
  },
  Stage_7953_Desc = {
    Text = "坍塌的偶像注視著自己的子民。\n看他們生存、繁衍、互相爭鬥，然後將自己徹底遺忘。\n坍塌的偶像懷念著自己的子民。"
  },
  Stage_7953_Name = {
    Text = "幻夢深潛Ⅱ"
  },
  Stage_7954_Desc = {
    Text = "然後她消失了，回到黑暗中。\n人們仰望高處，豎起眼睛，注視著她掠過的天空。"
  },
  Stage_7955_Desc = {
    Text = "在她美貌的祭壇上，我願供奉我的眼淚，我的歎息以及我的赤心。"
  },
  Stage_7955_Name = {
    Text = "伽拉忒亞"
  },
  Stage_7956_Desc = {
    Text = "坍塌的偶像注視著自己的子民。\n看他們生存、繁衍、互相爭鬥，然後將自己徹底遺忘。\n坍塌的偶像懷念著自己的子民。"
  },
  Stage_7956_Name = {
    Text = "幻夢深潛Ⅴ"
  },
  Stage_79574_Desc = {
    Text = "露出的心臟，古舊的標本，暗淡的銀鑰……\n正如飛蛾撲火，她所期待的，是由你為她帶來的告別。"
  },
  Stage_79575_Desc = {
    Text = "悠久的銀光賜予少女第三次生命。\n最後的淚水不再流淌，永恆的痛苦就此開始。\n第一滴眼淚開始落下，嶄新的人生開啟新章。\n赴死之人重新啟程，去尋找真正的自己。"
  },
