  },
  Stage_79601_Desc = {
    Text = "無形之火以萬千生靈為薪，焚燒世間萬象。\n不容哀嚎，不容駐足，不容一絲一毫痕跡留存。\n其怒無窮無盡，無聲咆哮永不停歇。\n因總有抗逆命運之人，妄圖贖下注定化為灰燼的柴薪。"
  },
  Stage_79601_Name = {
    Text = "燃燒的世界·之一"
  },
  Stage_79602_Desc = {
    Text = "跟著靈擺搖晃的節奏，聆聽四周悅耳的蟲鳴，放鬆勞累緊繃的神經，克萊門汀醫生將帶你入夢。\n歡迎來到心靈的殿堂。"
  },
  Stage_79602_Name = {
    Text = "侵夢之時·之五"
  },
  Stage_79603_Desc = {
    Text = "跟著靈擺搖晃的節奏，聆聽四周悅耳的蟲鳴，放鬆勞累緊繃的神經，克萊門汀醫生將帶你入夢。\n歡迎來到心靈的殿堂。"
  },
  Stage_79603_Name = {
    Text = "侵夢之時·之四"
  },
  Stage_79604_Desc = {
    Text = "跟著靈擺搖晃的節奏，聆聽四周悅耳的蟲鳴，放鬆勞累緊繃的神經，克萊門汀醫生將帶你入夢。\n歡迎來到心靈的殿堂。"
  },
  Stage_79604_Name = {
    Text = "侵夢之時·癲狂"
  },
  Stage_79605_Desc = {
    Text = "跟著靈擺搖晃的節奏，聆聽四周悅耳的蟲鳴，放鬆勞累緊繃的神經，克萊門汀醫生將帶你入夢。\n歡迎來到心靈的殿堂。"
  },
  Stage_79605_Name = {
    Text = "侵夢之時·之六"
  },
  Stage_79606_Desc = {
    Text = "跟著靈擺搖晃的節奏，聆聽四周悅耳的蟲鳴，放鬆勞累緊繃的神經，克萊門汀醫生將帶你入夢。\n歡迎來到心靈的殿堂。"
  },
  Stage_79606_Name = {
    Text = "侵夢之時·之一"
  },
  Stage_79607_Desc = {
    Text = "跟著靈擺搖晃的節奏，聆聽四周悅耳的蟲鳴，放鬆勞累緊繃的神經，克萊門汀醫生將帶你入夢。\n歡迎來到心靈的殿堂。"
  },
  Stage_79607_Name = {
    Text = "侵夢之時·之三"
  },
  Stage_79608_Desc = {
    Text = "跟著靈擺搖晃的節奏，聆聽四周悅耳的蟲鳴，放鬆勞累緊繃的神經，克萊門汀醫生將帶你入夢。\n歡迎來到心靈的殿堂。"
  },
  Stage_79608_Name = {
    Text = "侵夢之時·之二"
  },
  Stage_7960_Desc = {
    Text = "多麼幸福的沉睡，它讓我的天使回到我身邊。"
  },
  Stage_7961_Desc = {
    Text = "日記是記憶的碎片。\n調查中總是會發現日記的。"
  },
  Stage_7961_Name = {
    Text = "記憶碎片"
  },
  Stage_7962_Desc = {
    Text = "皚皚雪原，百合繁盛。"
  },
  Stage_7963_Desc = {
    Text = "當勳貴們痛失權柄，當豪富們傾家蕩產，他們寸步難行，就像你現在這樣。"
  },
  Stage_7963_Name = {
    Text = "飛越瘋人院"
  },
  Stage_7964_Desc = {
    Text = "這是一方為她開闢的天地，是偉大的愛意與可怖的囚籠。"
  },
  Stage_7965_Desc = {
    Text = "世間的交鋒不止於兵刃相接的戰場，有時也存在於瘋人之口。"
  },
  Stage_7965_Name = {
    Text = "瘋人之口"
  },
  Stage_7966_Desc = {
    Text = "寂靜燃燒的火焰，向旅人許下虛妄的諾言。"
  },
  Stage_7966_Name = {
    Text = "誘蛾之火"
  },
  Stage_7967_Desc = {
    Text = "纏繞在迷霧中的軌跡，無數腳步在其上徘徊，每一個踏點都是對命運的追問。"
  },
  Stage_7968_Desc = {
    Text = "它一刻不停地追逐那些打破規則的僭越者。\n至於何為「規則」，何為「打破」？\n獵犬從不思考——那只會阻礙它奔襲的速度。"
  },
  Stage_7969_Desc = {
    Text = "她以己身承納聖骸，以教義訓導眷眾，以毒牙布散信仰。"
  },
  Stage_7969_Name = {
    Text = "虔誠之握Ⅰ"
  },
  Stage_7970_Desc = {
    Text = "風雨仍在醞釀，一切尚未終結。"
  },
  Stage_7970_Name = {
    Text = "現實重啟"
  },
  Stage_7971_Desc = {
    Text = "那絕非受到期待的生命，只是污濁的寄生蟲罷了。"
  },
  Stage_7972_Desc = {
    Text = "駛向陸地，駛向一線生機。"
  },
  Stage_7972_Name = {
    Text = "悲劇的起航"
  },
  Stage_7973_Desc = {
    Text = "夜色被暗流侵蝕，星辰失聲。潛藏著轉折與風雨的危機之月，靜默映照著未知的未來。"
  },
  Stage_7973_Name = {
    Text = "危機之月"
  },
  Stage_7974_Desc = {
    Text = "在無盡夜幕的漆黑中追逐著那誘人的光明，猶如一隻逐火之蛾，不顧一切地向著命運的焰火翱翔。"
  },
  Stage_7975_Desc = {
    Text = "在過往歲月中飄搖的友誼，結下了新的希望。"
  },
  Stage_7975_Name = {
    Text = "舊友新朋"
  },
  Stage_7976_Desc = {
    Text = "在命運的狂風中顫抖、掙扎，但它不會真正地飄零。"
  },
  Stage_7976_Name = {
    Text = "搖搖欲墜"
  },
  Stage_7977_Desc = {
    Text = "迎著風與黃沙，戰士義無反顧地奔向太陽。"
  },
  Stage_7977_Name = {
    Text = "太陽遠征"
  },
  Stage_7978_Desc = {
    Text = "蠕動著、流淌著……原生質的腫泡正從枷鎖的縫隙中溜走。\n這是她為「自由」付出的代價。"
  },
  Stage_7978_Name = {
    Text = "漆黑之鏈Ⅴ"
  },
  Stage_7979_Desc = {
    Text = "一堆粗魯的、未消化的物質。人們稱其為排泄物，或是混沌。 \n世界從排泄物中誕生。"
  },
  Stage_7980_Desc = {
    Text = "來歷不明的造像在黑暗中遊蕩、戰慄。\n它們踏著古老的節拍，循著來自遠方的笛聲起舞。"
  },
  Stage_7980_Name = {
    Text = "超維之旅·間隙Ⅷ"
  },
  Stage_7981_Desc = {
    Text = "它們在黑暗中扭曲、融合，然後被小心翼翼地保管在造像裡。\n這是一次蓄謀已久的重逢。"
  },
  Stage_7981_Name = {
    Text = "血肉之沼·間隙Ⅴ"
  },
  Stage_7982_Desc = {
    Text = "然後她消失了，回到黑暗中。\n人們仰望高處，豎起眼睛，注視著她掠過的天空。"
  },
  Stage_7983_Desc = {
    Text = "一隻小老鼠，一隻小老鼠。\n跑啊，跑啊，她用切肉刀割掉它的尾巴。"
  },
  Stage_7983_Name = {
    Text = "布朗出擊"
  },
  Stage_7984_Desc = {
    Text = "你沉睡在夜晚的寂靜之中，\n沒有剩下任何的疑惑或爭端，\n就像擁有永恆的擁抱，\n我們躺在平靜的安定之中。"
  },
  Stage_7984_Name = {Text = "房間"},
  Stage_7985_Desc = {
    Text = "倫蒂尼恩以燦爛的工業文明，以及籠罩市區的鉛灰色濃霧聞名。\n霧氣無處不在，對路人來說是更像是一種偶然、無意義的不便。"
  },
  Stage_7985_Name = {
    Text = "怪霧之都Ⅲ"
  },
  Stage_7986_Desc = {
    Text = "在她美貌的祭壇上，我願供奉我的眼淚，我的歎息以及我的赤心。"
  },
  Stage_7986_Name = {
    Text = "伽拉忒亞"
  },
  Stage_7987_Desc = {
    Text = "吧唧咕嘰，裂開了。\n吧唧咕嘰，斷掉了。"
  },
  Stage_7987_Name = {Text = "娃娃館"},
  Stage_7988_Desc = {
    Text = "規則，不就是用來打破的嗎？"
  },
  Stage_7988_Name = {
    Text = "三條規則"
  },
  Stage_7989_Desc = {
    Text = "位於北約克郡的海邊小鎮——斯卡伯勒。這裡擁有高聳的懸崖與金色的海灣，是一處優雅迷人的度假勝地。"
  },
  Stage_7990_Desc = {
    Text = "噢，手臂，惱人的手臂！它們總是揪著我的頭髮不放。"
  },
  Stage_7991_Desc = {
    Text = "她從人類的眼淚與排泄物中學到不少實用心理學知識——比所有書籍中學到的還要多。"
  },
  Stage_7991_Name = {
    Text = "診療手冊"
  },
  Stage_7992_Desc = {
    Text = "為了您的生命健康，遠離尼古丁。"
  },
  Stage_7992_Name = {
    Text = "煙與紫羅蘭"
  },
  Stage_7993_Desc = {
    Text = "位於北約克郡的海邊小鎮——斯卡伯勒。這裡擁有高聳的懸崖與金色的海灣，是一處優雅迷人的度假勝地。"
  },
  Stage_7994_Desc = {
    Text = "為了您的生命健康，遠離尼古丁。"
  },
  Stage_7994_Name = {
    Text = "煙與紫羅蘭"
  },
  Stage_7995_Desc = {
    Text = "一隻小老鼠，一隻小老鼠。\n跑啊，跑啊，她用切肉刀割掉它的尾巴。"
  },
  Stage_7995_Name = {
    Text = "布朗出擊"
  },
  Stage_7996_Desc = {
    Text = "然後她消失了，回到黑暗中。\n人們仰望高處，豎起眼睛，注視著她掠過的天空。"
  },
  Stage_7997_Desc = {
    Text = "在她美貌的祭壇上，我願供奉我的眼淚，我的歎息以及我的赤心。"
  },
  Stage_7997_Name = {
    Text = "伽拉忒亞"
  },
  Stage_7999_Desc = {
    Text = "噢，手臂，惱人的手臂！它們總是揪著我的頭髮不放。"
  },
  Stage_8000_Desc = {
    Text = "是的，是的。眼睛是心靈的牢籠，靈魂是禁錮肉身的枷鎖。"
  },
  Stage_8000_Name = {
    Text = "解剖的憂鬱"
  },
  Stage_8001_Desc = {
    Text = "沒錯，寶貝。盡情地哭吧，把你的痛苦當作絕世名作一樣裝裱起來。"
  },
  Stage_8001_Name = {
    Text = "少女和眼淚"
  },
  Stage_8002_Desc = {
    Text = "「手」掀開夜的帷幕，悄悄來到這個世界。"
  },
  Stage_8002_Name = {
    Text = "幻夢深潛Ⅰ"
  },
  Stage_8003_Desc = {
    Text = "「手」掀開夜的帷幕，悄悄來到這個世界。"
  },
  Stage_8003_Name = {
    Text = "幻夢深潛Ⅲ"
  },
  Stage_8004_Desc = {
    Text = "「手」掀開夜的帷幕，悄悄來到這個世界。"
  },
  Stage_8004_Name = {
    Text = "幻夢深潛Ⅱ"
  },
  Stage_8005_Desc = {
    Text = "「手」掀開夜的帷幕，悄悄來到這個世界。"
  },
  Stage_8005_Name = {
    Text = "幻夢深潛Ⅴ"
  },
  Stage_8006_Desc = {
    Text = "「手」掀開夜的帷幕，悄悄來到這個世界。"
  },
  Stage_8006_Name = {
    Text = "幻夢深潛Ⅳ"
  },
  Stage_8007_Desc = {
    Text = "「手」掀開夜的帷幕，悄悄來到這個世界。"
  },
  Stage_8007_Name = {
    Text = "幻夢深潛Ⅶ"
  },
  Stage_8008_Desc = {
    Text = "「手」掀開夜的帷幕，悄悄來到這個世界。"
  },
  Stage_8008_Name = {
    Text = "幻夢深潛Ⅵ"
  },
  Stage_8009_Desc = {
    Text = "這裡沉睡著一座古老城市的廢墟。\n它和它的主人一樣嗜睡。"
  },
  Stage_8009_Name = {
    Text = "波納佩之墟Ⅰ"
  },
  Stage_8010_Desc = {
    Text = "我們還會不斷相遇，在不同的時間與空間維度裡"
  },
  Stage_8010_Name = {
    Text = "後會有期"
  },
  Stage_8011_Desc = {
    Text = "潛藏在宇宙深處的彎曲視界。 \n它能帶你從黑暗抵達另一處黑暗。"
  },
  Stage_8012_Desc = {
    Text = "潛藏在宇宙深處的彎曲視界。 \n它能帶你從黑暗抵達另一處黑暗。"
  },
  Stage_8013_Desc = {
    Text = "沒有人能摘下神王賜下的冠冕，沒有人。"
  },
  Stage_8013_Name = {
    Text = "利莫里亞的「榮光」"
  },
  Stage_8014_Desc = {
    Text = "在過往歲月中飄搖的友誼，結下了新的希望。"
  },
  Stage_8014_Name = {
    Text = "舊友新朋"
  },
  Stage_8015_Desc = {
    Text = "夜色被暗流侵蝕，星辰失聲。潛藏著轉折與風雨的危機之月，靜默映照著未知的未來。"
  },
  Stage_8015_Name = {
    Text = "危機之月"
  },
  Stage_8016_Desc = {
    Text = "是的，貪婪是他的原罪，他會因此懺悔。"
  },
  Stage_8016_Name = {Text = "湮滅"},
  Stage_8017_Desc = {
    Text = "緘默的守護者發出了新聲。"
  },
  Stage_8017_Name = {
    Text = "超載保護"
  },
  Stage_8018_Desc = {
    Text = "在無盡夜幕的漆黑中追逐著那誘人的光明，猶如一隻逐火之蛾，不顧一切地向著命運的焰火翱翔。"
  },
  Stage_8019_Desc = {
    Text = "「門」已被開啟，幻夢即將清醒。\n噓……不可注視，不可諦聽。"
  },
  Stage_8019_Name = {
    Text = "混沌之域·輪轉間隙Ⅲ"
  },
  Stage_8020_Desc = {
    Text = "「門」已被開啟，幻夢即將清醒。\n噓……不可注視，不可諦聽。"
  },
  Stage_8020_Name = {
    Text = "混沌之域·輪轉間隙Ⅲ"
  },
  Stage_8021_Desc = {
    Text = "「門」已被開啟，幻夢即將清醒。\n噓……不可注視，不可諦聽。"
  },
  Stage_8021_Name = {
    Text = "混沌之域·輪轉間隙Ⅲ"
  },
  Stage_8022_Desc = {
    Text = "那絕非受到期待的生命，只是污濁的寄生蟲罷了。"
  },
  Stage_8023_Desc = {
    Text = "多麼幸福的沉睡，它讓我的天使回到我身邊。"
  },
  Stage_80242_Desc = {
    Text = "故事最後，世界仍在燃燒，我已做好告別的準備。\n但我們終將重逢。"
  },
  Stage_80242_Name = {
    Text = "燃燒的世界，再見"
  },
  Stage_80243_Desc = {
    Text = "人是一種社會性動物，他們受到社會的影響，又影響著社會。\n所以，告訴我，你被生活和環境塑造成了什麼樣的自己？"
  },
  Stage_80243_Name = {
    Text = "認知重構實驗"
  },
  Stage_80244_Desc = {
    Text = "原諒我沒有什麼禮物贈送給你。\n這一枚小小的蟲蛹，是我對你最深重的祝福：陷入絕境時，請你一定要破繭重生。"
  },
  Stage_80244_Name = {
    Text = "友誼的蟲蛹"
  },
  Stage_80245_Desc = {
    Text = "火焰，帶來光明，也帶來疼痛與傷害。\n當整個世界都在燃燒，我願將生命化為一滴淚水，彙聚成痛苦的海洋。"
  },
  Stage_80245_Name = {
    Text = "你好，燃燒的世界"
  },
  Stage_80246_Desc = {
    Text = "勇者是孤獨的，人類無法真正走進他，龍也無法真正理解他。\n究竟是屠龍，還是化身為龍，這是一個問題。"
  },
  Stage_80246_Name = {
    Text = "孤獨的勇者"
  },
  Stage_80247_Desc = {
    Text = "我對世界滿懷夢想，希望鮮花一直盛開，希望微笑永恆長存。\n但生命只給了我一個夢。"
  },
  Stage_80247_Name = {
    Text = "我有許多夢想"
  },
  Stage_80248_Desc = {
    Text = "群體是流動的琥珀，每個靈魂都在折射他人的光芒，又在透明牢籠裡看見自己的倒影。"
  },
  Stage_80248_Name = {
    Text = "社會性動物"
  },
  Stage_80249_Desc = {
    Text = "我是我的朋友，也是我的敵人。\n這場合作與廝殺不會停止，直到場上只留下一人。"
  },
  Stage_8024_Desc = {
    Text = "無論金屬軀殼多麼沉重，靈魂只佔21克。"
  },
  Stage_80250_Desc = {
    Text = "小小的蝴蝶，穿過夢境，飛向現實。\n或許它太過愚蠢，但蝴蝶的選擇，與人不同。"
  },
  Stage_80250_Name = {Text = "蝴蝶飛"},
  Stage_80251_Desc = {
    Text = "讓我來看看，看看是什麼樣的成分與結構，組成了“你”與“我”。"
  },
  Stage_80252_Desc = {
    Text = "哦，朋友，我們都會做夢。\n只是有的人會讓夢成為現實，而有的人的現實，就像夢一樣荒誕無經。"
  },
  Stage_80252_Name = {
    Text = "不受控的夢"
  },
  Stage_80253_Desc = {
    Text = "我要在失落的記憶裡起舞，忘記愛我的人和我愛的人，只和自己永恆地起舞，舞到時間的盡頭。"
  },
  Stage_80253_Name = {
    Text = "失落的記憶"
  },
  Stage_80254_Desc = {
    Text = "逃，逃，小狗狗快逃。\n用你的驚慌失措與痛苦無助，為我們表演一場滑稽戲。"
  },
  Stage_80255_Desc = {
    Text = "在看著你，我在看著你。\n每時每刻，無時無刻，就那樣看著你。"
  },
  Stage_80255_Name = {
    Text = "他者的凝視"
  },
  Stage_80256_Desc = {
    Text = "回憶並不可靠，因為隨著我在其中的翻找，它開始損毀和褪色。究竟用什麼辦法才可以讓你的身影永恆固定？\n如果回憶不牢固，那就刻在生命裡。"
  },
  Stage_80257_Desc = {
    Text = "前三槍只是預奏。\n最後的兩槍裡，一槍帶走他的生命，一槍帶走他的靈魂。"
  },
  Stage_80257_Name = {
    Text = "五聲槍響"
  },
  Stage_80258_Desc = {
    Text = "“好奇”向你拋出了一個問題，哪怕明知答案滿是荊棘，會讓你焚毀殆盡，你也無法拒絕。\n你終究是那只無法拒絕“好奇”的貓。"
  },
  Stage_80258_Name = {
    Text = "好奇心害死貓"
  },
  Stage_80259_Desc = {
    Text = "世界是個大型的療養院，每個人都在發瘋，或者隱藏自己的瘋狂。\n所以，要來一場心理諮詢嗎？"
  },
  Stage_80259_Name = {
    Text = "諮詢邀請"
  },
  Stage_8025_Desc = {
    Text = "這是一方為她開闢的天地，是偉大的愛意與可怖的囚籠。"
  },
  Stage_80260_Desc = {
    Text = "哦，朋友，我們都會做夢。\n只是有的人會讓夢成為現實，而有的人的現實，就像夢一樣荒誕無經。"
  },
  Stage_80260_Name = {
    Text = "不受控的夢"
  },
  Stage_80261_Desc = {
    Text = "我要在失落的記憶裡起舞，忘記愛我的人和我愛的人，只和自己永恆地起舞，舞到時間的盡頭。"
  },
  Stage_80261_Name = {
    Text = "失落的記憶"
  },
  Stage_80262_Desc = {
    Text = "逃，逃，小狗狗快逃。\n用你的驚慌失措與痛苦無助，為我們表揚一場滑稽戲。"
  },
  Stage_80263_Desc = {
    Text = "回憶並不可靠，因為隨著我在其中的翻找，它開始損毀和褪色。究竟用什麼辦法才可以讓你的身影永恆固定？\n如果回憶不牢固，那就刻在生命裡。"
  },
  Stage_80264_Desc = {
    Text = "前三槍只是預奏。\n最後的兩槍裡，一槍帶走他的生命，一槍帶走他的靈魂。"
  },
  Stage_80264_Name = {
    Text = "五聲槍響"
  },
  Stage_80265_Desc = {
    Text = "世界是個大型的療養院，每個人都在發瘋，或者隱藏自己的瘋狂。\n所以，要來一場心理諮詢嗎？"
  },
  Stage_80265_Name = {
    Text = "諮詢邀請"
  },
  Stage_80266_Desc = {
    Text = "火焰，帶來光明，也帶來疼痛與傷害。\n當整個世界都在燃燒，我願將生命化為一滴淚水，彙聚成痛苦的海洋。"
  },
  Stage_80266_Name = {
    Text = "你好，燃燒的世界"
  },
  Stage_80267_Desc = {
    Text = "勇者是孤獨的，人類無法真正走進他，龍也無法真正理解他。\n究竟是屠龍，還是化身為龍，這是一個問題。"
  },
  Stage_80267_Name = {
    Text = "孤獨的勇者"
  },
  Stage_80268_Desc = {
    Text = "人是一種社會性動物，他們受到社會的影響，又影響著社會。\n所以，告訴我，你被生活和環境塑造成了什麼樣的自己？"
  },
  Stage_80268_Name = {
    Text = "認知重構實驗"
  },
  Stage_80269_Desc = {
    Text = "我對世界滿懷夢想，希望鮮花一直盛開，希望微笑永恆長存。\n但生命只給了我一個夢。"
  },
  Stage_80269_Name = {
    Text = "我有許多夢想"
  },
  Stage_8026_Desc = {
    Text = "當勳貴們痛失權柄，當豪富們傾家蕩產，他們寸步難行，就像你現在這樣。"
  },
  Stage_8026_Name = {
    Text = "飛越瘋人院"
  },
  Stage_80270_Desc = {
    Text = "我是我的朋友，也是我的敵人。\n這場合作與廝殺不會停止，直到場上只留下一人。"
  },
  Stage_80271_Desc = {
    Text = "小小的蝴蝶，穿過夢境，飛向現實。\n或許它太過愚蠢，但蝴蝶的選擇，與人不同。"
  },
  Stage_80271_Name = {Text = "蝴蝶飛"},
  Stage_8027_Desc = {
    Text = "世間的交鋒不止於兵刃相接的戰場，有時也存在於瘋人之口。"
  },
  Stage_8027_Name = {
    Text = "瘋人之口"
  },
  Stage_8028_Desc = {
    Text = "剪斷木偶身上的細線，她就再也不會舞蹈。"
  },
  Stage_8028_Name = {
    Text = "飛鳥不在的夜"
  },
  Stage_8029_Desc = {
    Text = "不要回頭！多麼貴重的叮囑，別再步俄耳甫斯的後塵。"
  },
  Stage_8029_Name = {
    Text = "不要回頭"
  },
  Stage_8030_Desc = {
    Text = "誰能詮釋“春天”的含義？\n蟄伏於靜寂虛空中的死亡與遺忘，融入朦朧的春日蜃景。"
  },
  Stage_8031_Desc = {
    Text = "日記是記憶的碎片。\n調查中總是會發現日記的。"
  },
  Stage_8031_Name = {
    Text = "記憶碎片"
  },
  Stage_8032_Desc = {
    Text = "初次見面，我的主人。"
  },
  Stage_8033_Desc = {
    Text = "它們在黑暗中扭曲、融合，然後被小心翼翼地保管在造像裡。\n這是一次蓄謀已久的重逢。"
  },
  Stage_8033_Name = {
    Text = "血肉之沼·間隙Ⅵ"
  },
  Stage_8034_Desc = {
    Text = "早在群星誕生之前，它們便存在於此。\n它們既是虛無，也是一切。"
  },
  Stage_8034_Name = {
    Text = "渾濁殘像Ⅲ"
  },
  Stage_8035_Desc = {Text = "隨機4"},
  Stage_8035_Name = {
    Text = "月沼之鏡Ⅳ"
  },
  Stage_8036_Desc = {Text = "隨機5"},
  Stage_8036_Name = {
    Text = "月沼之鏡Ⅴ"
  },
  Stage_8037_Desc = {
    Text = "「門」即將開啟，你從中窺見一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是渾濁的。"
  },
  Stage_8037_Name = {
    Text = "混沌之域·輪轉間隙Ⅰ"
  },
  Stage_8038_Desc = {Text = "隨機1"},
  Stage_8038_Name = {
    Text = "月沼之鏡Ⅰ"
  },
  Stage_8039_Desc = {
    Text = "「門」即將開啟，你從中窺見一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是渾濁的。"
  },
  Stage_8039_Name = {
    Text = "混沌之域·輪轉間隙Ⅰ"
  },
  Stage_8040_Desc = {
    Text = "「門」即將開啟，你從中窺見一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是渾濁的。"
  },
  Stage_8040_Name = {
    Text = "混沌之域·輪轉間隙Ⅰ"
  },
  Stage_8041_Desc = {
    Text = "拉蒙娜回歸了隊伍。彌薩格調查員的旅程繼續。"
  },
  Stage_8041_Name = {
    Text = "昨日重現"
  },
  Stage_8042_Desc = {
    Text = "荒蕪的鐵路橋下，龐大臃腫的怪物發出古怪的低吼。要抵達拉伊瘋人院，就必須跨過這裡。"
  },
  Stage_8042_Name = {
    Text = "船到橋頭自然直"
  },
  Stage_8043_Desc = {
    Text = "你想要知道的一切，就在你的眼前，只是你從未發現。"
  },
  Stage_8043_Name = {
    Text = "藏於帽檐下"
  },
  Stage_8044_Desc = {
    Text = "人生就像一個螺旋，曾經逃脫過的夢魘，總是會在午夜再一次襲來。"
  },
  Stage_8044_Name = {
    Text = "回到出發點"
  },
  Stage_8045_Desc = {
    Text = "拉蒙娜與蘿坦的絮語聲中，守密人陷入牢籠中的夢境。"
  },
  Stage_8045_Name = {
    Text = "不要修理未損之物"
  },
  Stage_8046_Desc = {
    Text = "神說，他們生來便該歷經苦難，流盡鮮血。\n就像太陽本該升起，雨水本該墜落。\n一切都是最好的安排。"
  },
  Stage_8047_Desc = {
    Text = "羅傑斯蠟像館坐落在南華克街的最深處，靠近泰姆河的支流。\n它毫不起眼，卻有眾多先鋒藝術愛好者慕名而來。"
  },
  Stage_8047_Name = {
    Text = "狂躁蠟館Ⅱ"
  },
  Stage_8048_Desc = {
    Text = "它是這裡唯一的活物，它所見的一切由它統治。\n——它是至高無上的國王。"
  },
  Stage_8048_Name = {
    Text = "野獸王國"
  },
  Stage_8049_Desc = {
    Text = "祂的國度是宇宙軀殼，祂的欲望無邊無際。"
  },
  Stage_8049_Name = {
    Text = "蠕蟲之所Ⅰ"
  },
  Stage_8050_Desc = {
    Text = "「手」掀開夜的帷幕，悄悄來到這個世界。"
  },
  Stage_8050_Name = {
    Text = "幻夢深潛Ⅴ"
  },
  Stage_8051_Desc = {
    Text = "坍塌的偶像注視著自己的子民。\n看他們生存、繁衍、互相爭鬥，然後將自己徹底遺忘。\n坍塌的偶像懷念著自己的子民。"
  },
  Stage_8051_Name = {
    Text = "幻夢深潛Ⅱ"
  },
  Stage_8052_Desc = {
    Text = "坍塌的偶像注視著自己的子民。\n看他們生存、繁衍、互相爭鬥，然後將自己徹底遺忘。\n坍塌的偶像懷念著自己的子民。"
  },
  Stage_8052_Name = {
    Text = "幻夢深潛Ⅲ"
  },
  Stage_8053_Desc = {
    Text = "這是一部沒有結尾的電影，她已在幕間沉睡多年。\n她夢見夏日午後的玫瑰，也夢見灰燼和風……"
  },
  Stage_8053_Name = {
    Text = "菲林詩社"
  },
  Stage_8054_Desc = {
    Text = "坍塌的偶像注視著自己的子民。\n看他們生存、繁衍、互相爭鬥，然後將自己徹底遺忘。\n坍塌的偶像懷念著自己的子民。"
  },
  Stage_8054_Name = {
    Text = "幻夢深潛Ⅵ"
  },
  Stage_8055_Desc = {
