  },
  Stage_8055_Name = {
    Text = "幻夢深潛Ⅶ"
  },
  Stage_8056_Desc = {
    Text = "坍塌的偶像注視著自己的子民。\n看他們生存、繁衍、互相爭鬥，然後將自己徹底遺忘。\n坍塌的偶像懷念著自己的子民。"
  },
  Stage_8056_Name = {
    Text = "幻夢深潛Ⅳ"
  },
  Stage_8057_Desc = {
    Text = "坍塌的偶像注視著自己的子民。\n看他們生存、繁衍、互相爭鬥，然後將自己徹底遺忘。\n坍塌的偶像懷念著自己的子民。"
  },
  Stage_8057_Name = {
    Text = "幻夢深潛Ⅴ"
  },
  Stage_8058_Desc = {
    Text = "當雨幕落下，鮮血湧出，我們迎來再度相聚的時刻。\n好久不見，守密人。"
  },
  Stage_8060_Desc = {
    Text = "當影子潛入黑夜，水滴匯入雨水。\n屬於獵殺的時刻即將來臨……"
  },
  Stage_8060_Name = {
    Text = "暴雨將至"
  },
  Stage_8062_Desc = {
    Text = "我們是蟲豸、骨頭與眼淚的集合。\n今夜我們在此相聚，隻為一見那流淌著無數彩虹的河流。"
  },
  Stage_8062_Name = {
    Text = "獵顱集會"
  },
  Stage_8063_Desc = {
    Text = "「它是唯一，它是全部，它是開啟真相之門的希望。」\n無數鑰匙圍成了一個圈。它們自天空中墜落，帶給人們沉甸甸的希望。\n也帶來沉甸甸的墳墓。"
  },
  Stage_8063_Name = {
    Text = "幻夢深潛Ⅰ"
  },
