  },
  Stage_8070_Desc = {
    Text = "它們在黑暗中扭曲、融合，然後被小心翼翼地保管在造像裡。\n這是一次蓄謀已久的重逢。"
  },
  Stage_8070_Name = {
    Text = "深海之遺·間隙Ⅵ"
  },
  Stage_8071_Desc = {
    Text = "它們原本是悲傷、扭曲和懵懂組成的無意識集合，\n卻被打扮成幸福的小孩、大人和寵物。\n因著從未品嘗過幸福的滋味，它們成了最糟糕的演員。"
  },
  Stage_8071_Name = {
    Text = "蠟像之秘Ⅲ"
  },
  Stage_8072_Desc = {
    Text = "它一刻不停地追逐那些打破規則的僭越者。\n至於何為「規則」，何為「打破」？\n獵犬從不思考——那只會阻礙它奔襲的速度。"
  },
  Stage_8073_Desc = {
    Text = "它們像捉摸不定的魔法師，遊走在時空的夾縫裡。\n沒有仇恨，沒有恐懼，也沒有憐憫。"
  },
  Stage_8073_Name = {
    Text = "維度殘像Ⅴ"
  },
  Stage_8074_Desc = {
    Text = "蠕動著、流淌著……原生質的腫泡正從枷鎖的縫隙中溜走。\n這是她為「自由」付出的代價。"
  },
  Stage_8074_Name = {
    Text = "漆黑之鏈Ⅰ"
  },
