  },
  Stage_8093_Name = {
    Text = "混沌之域·輪轉間隙Ⅱ"
  },
  Stage_8094_Desc = {
    Text = "來歷不明的造像在黑暗中遊蕩、戰慄。\n它們踏著古老的節拍，循著來自遠方的笛聲起舞。"
  },
  Stage_8094_Name = {
    Text = "混沌之域·間隙Ⅱ"
  },
  Stage_8095_Desc = {
    Text = "「門」即將開啟，你從中窺見一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是渾濁的。"
  },
  Stage_8095_Name = {
    Text = "超維之旅·間隙Ⅲ"
  },
  Stage_8096_Desc = {
    Text = "它們在黑暗中扭曲、融合，然後被小心翼翼地保管在造像裡。\n這是一次蓄謀已久的重逢。"
  },
  Stage_8096_Name = {
    Text = "混沌之域·間隙Ⅵ"
  },
  Stage_8097_Desc = {
    Text = "它們像捉摸不定的魔法師，遊走在時空的夾縫裡。\n沒有仇恨，沒有恐懼，也沒有憐憫。"
  },
  Stage_8097_Name = {
    Text = "維度殘像Ⅲ"
  },
  Stage_80984_Name = {
    Text = "催眠妖蟲試玩關卡"
  },
  Stage_8098_Desc = {
    Text = "她以己身承納聖骸，以教義訓導眷眾，以毒牙布散信仰。"
  },
  Stage_8098_Name = {
    Text = "虔誠之握Ⅳ"
  },
  Stage_8099_Desc = {
    Text = "早在群星誕生之前，它們便存在於此。\n它們既是虛無，也是一切。"
  },
  Stage_8099_Name = {
    Text = "渾濁殘像Ⅱ"
  },
  Stage_8100_Desc = {
    Text = "它們無言地守護著海洋的秘密，靈魂和宇宙一樣深沉。"
  },
  Stage_8100_Name = {
    Text = "海淵殘像Ⅳ"
  },
  Stage_8101_Desc = {
    Text = "它們在黑暗中扭曲、融合，然後被小心翼翼地保管在造像裡。\n這是一次蓄謀已久的重逢。"
  },
  Stage_8101_Name = {
    Text = "超維之旅·間隙Ⅵ"
  },
  Stage_8102_Desc = {
    Text = "「門」即將開啟，你從中窺見一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是渾濁的。"
  },
  Stage_8102_Name = {
    Text = "深海之遺·輪轉間隙Ⅰ"
  },
  Stage_8103_Name = {
    Text = "海之使徒試玩關卡"
  },
  Stage_8104_Desc = {
    Text = "羅傑斯蠟像館坐落在南華克街的最深處，靠近泰姆河的支流。\n它毫不起眼，卻有眾多先鋒藝術愛好者慕名而來。"
  },
  Stage_8104_Name = {
    Text = "狂躁蠟館Ⅲ"
  },
  Stage_8105_Desc = {
    Text = "怎會有永恆不落的夕陽？"
  },
  Stage_8106_Desc = {
    Text = "鋒銳的利刺打破絕對的圓弧，並非“刻耳柏洛斯”之物自裂隙生出。"
  },
  Stage_8106_Name = {
    Text = "殼中裂縫"
  },
  Stage_8107_Desc = {
    Text = "是什麼蒙蔽了她的雙眼？\n是愛、憐憫、正義和過分的感恩嗎？"
  },
  Stage_8107_Name = {Text = "超脫"},
  Stage_8108_Desc = {
    Text = "它們像捉摸不定的魔法師，遊走在時空的夾縫裡。\n沒有仇恨，沒有恐懼，也沒有憐憫。"
  },
  Stage_8108_Name = {
    Text = "維度殘像Ⅳ"
  },
  Stage_8109_Desc = {
    Text = "「門」即將開啟，你從中窺見一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是渾濁的。"
  },
  Stage_8109_Name = {
    Text = "深海之遺·輪轉間隙Ⅰ"
  },
  Stage_8110_Desc = {
    Text = "追溯地獄犬“刻耳柏洛斯”的流言，彌薩格的調查員們來到倫蒂尼恩遠郊的小鎮拉伊，探尋失蹤案背後的隱秘……"
  },
  Stage_8110_Name = {
    Text = "三思而後行"
  },
  Stage_8111_Desc = {
    Text = "一個好消息，一個壞消息。消失的線索不會重現，但新的案件已在暗中醞釀。相信吧，調查員不會再兩手空空。"
  },
  Stage_8111_Name = {
    Text = "好消息，壞消息"
  },
  Stage_8112_Desc = {
    Text = "謎一般的水仙夫人。"
  },
  Stage_8112_Name = {
    Text = "你好，達芙黛爾夫人"
  },
  Stage_8113_Desc = {
    Text = "癲狂的語調，濃烈的腥氣，這就是來自拉伊的歡迎儀式。"
  },
  Stage_8113_Name = {
    Text = "歡迎來到拉伊"
  },
  Stage_8114_Desc = {
    Text = "人類的腿腳無法勝過敏捷的四足野生生物，但頭腦可以。只是，在捕獲“地獄犬”之後，等待著你們的又是什麼呢？"
  },
  Stage_8115_Desc = {
    Text = "達芙黛爾請來了你們的“答案”，新的棋子邁入棋盤，帶來關於風雪的夢境。"
  },
  Stage_8117_Desc = {
    Text = "在地鐵內，你們遭到了神秘刺客的襲擊……"
  },
  Stage_8117_Name = {
    Text = "人生無友"
  },
  Stage_81181_Desc = {
