  },
  Stage_81203_Name = {Text = "獻祭"},
  Stage_81204_Desc = {
    Text = "年輕的領航員啊，你終將被鹹水擁入懷中，化為引路的磷火。"
  },
  Stage_81204_Name = {
    Text = "領航員挽歌"
  },
  Stage_81205_Desc = {
    Text = "黑暗降臨前，並非光明，而是不那麼黑暗的黑暗。\n因為總有人，會舉起火把。"
  },
  Stage_81205_Name = {
    Text = "黑暗降臨前"
  },
  Stage_81206_Desc = {
    Text = "星盤是航海者的雙眼，它能夠幫助我們在夜晚的天空中找到方向。"
  },
  Stage_81206_Name = {
    Text = "斑駁星盤·之三"
  },
  Stage_81207_Desc = {
