  Stage_81208_Name = {
    Text = "斑駁星盤·之四"
  },
  Stage_81209_Desc = {
    Text = "這份古老的海圖被塗得密密麻麻，上面記滿了從它誕生以來所有持有者的遭遇。"
  },
  Stage_81209_Name = {
    Text = "古老海圖·之六"
  },
  Stage_8120_Desc = {
    Text = "危險來自內部。"
