  Stage_8124_Desc = {
    Text = "「手」掀開夜的帷幕，悄悄來到這個世界。"
  },
  Stage_8124_Name = {
    Text = "幻夢深潛Ⅳ"
  },
  Stage_8125_Desc = {
    Text = "這裡肆虐的並非普通疾病。"
  },
  Stage_8126_Desc = {
    Text = "你與拉蒙娜前往倫蒂尼恩東區的莉莉安濟貧院，展開你作為新晉守密人的第一次調查。\n一切都會很順利，對吧？"
  },
  Stage_8127_Desc = {
    Text = "幽靈藏於幽暗之處——地底或是人心。"
  },
  Stage_8127_Name = {
    Text = "地下的幽靈"
  },
  Stage_8128_Desc = {
    Text = "沒有供給呼吸的氧氣，沒有火柴般微弱的光亮，這裡是絕對的漆黑之夢。"
  },
  Stage_8128_Name = {
    Text = "漆黑之夢"
  },
  Stage_8129_Desc = {
    Text = "「每把鑰匙都有唯一的編號，只對應唯一的調查員。」\n「因此，每把鑰匙的隕落也對應著唯一的調查員之死。」\n「真好啊。就連死亡都是獨一無二的。」"
  },
  Stage_8129_Name = {
    Text = "幻夢深潛Ⅶ"
  },
