  },
  Stage_8135_Desc = {
    Text = "「每把鑰匙都有唯一的編號，只對應唯一的調查員。」\n「因此，每把鑰匙的隕落也對應著唯一的調查員之死。」\n「真好啊。就連死亡都是獨一無二的。」"
  },
  Stage_8135_Name = {
    Text = "幻夢深潛Ⅰ"
  },
  Stage_8137_Desc = {
    Text = "她是夢境與現實交錯的界限，是每個仰望夜空的靈魂內心深處的反射。"
  },
  Stage_8137_Name = {
    Text = "倒錯的群星"
  },
  Stage_8138_Desc = {
    Text = "一堆粗魯的、未消化的物質。人們稱其為排泄物，或是混沌。 \n世界從排泄物中誕生。"
  },
  Stage_8139_Desc = {
    Text = "蠕動著、流淌著……原生質的腫泡正從枷鎖的縫隙中溜走。\n這是她為「自由」付出的代價。"
  },
  Stage_8139_Name = {
    Text = "漆黑之鏈Ⅳ"
  },
  Stage_8140_Desc = {
    Text = "它們在黑暗中扭曲、融合，然後被小心翼翼地保管在造像裡。\n這是一次蓄謀已久的重逢。"
  },
  Stage_8140_Name = {
    Text = "混沌之域·間隙Ⅴ"
  },
  Stage_8141_Desc = {
    Text = "這裡沉睡著一座古老城市的廢墟。\n它和它的主人一樣嗜睡。"
  },
  Stage_8141_Name = {
    Text = "波納佩之墟Ⅲ"
  },
  Stage_8142_Desc = {
    Text = "是什麼蒙蔽了她的雙眼？\n是愛、憐憫、正義和過分的感恩嗎？"
  },
  Stage_8142_Name = {Text = "超脫"},
  Stage_8143_Desc = {
    Text = "鋒銳的利刺打破絕對的圓弧，並非“刻耳柏洛斯”之物自裂隙生出。"
  },
  Stage_8143_Name = {
    Text = "殼中裂縫"
  },
  Stage_8144_Desc = {
    Text = "怎會有永恆不落的夕陽？"
  },
  Stage_8145_Desc = {
    Text = "「手」掀開夜的帷幕，悄悄來到這個世界。"
  },
  Stage_8145_Name = {
    Text = "幻夢深潛Ⅰ"
  },
  Stage_8146_Desc = {
    Text = "來歷不明的造像在黑暗中遊蕩、戰慄。\n它們踏著古老的節拍，循著來自遠方的笛聲起舞。"
  },
  Stage_8146_Name = {
    Text = "深海之遺·間隙Ⅱ"
  },
  Stage_8147_Desc = {
    Text = "吧唧咕嘰，裂開了。\n吧唧咕嘰，斷掉了。"
  },
  Stage_8147_Name = {Text = "娃娃館"},
  Stage_8148_Desc = {
    Text = "「門」已被開啟，幻夢即將清醒。\n噓……不可注視，不可諦聽。"
  },
  Stage_8148_Name = {
    Text = "混沌之域·輪轉間隙Ⅳ"
  },
  Stage_8149_Desc = {
    Text = "「門」已被開啟，幻夢即將清醒。\n噓……不可注視，不可諦聽。"
  },
  Stage_8149_Name = {
    Text = "混沌之域·輪轉間隙Ⅳ"
  },
  Stage_8150_Desc = {
    Text = "「門」已被開啟，幻夢即將清醒。\n噓……不可注視，不可諦聽。"
  },
  Stage_8150_Name = {
    Text = "混沌之域·輪轉間隙Ⅳ"
  },
  Stage_8151_Desc = {
    Text = "既視感與現實正在將守密人撕成兩半，一半留給記憶，一半留在眼前。"
  },
  Stage_8152_Desc = {
    Text = "夜晚的港口，淳樸的居民，熱情的款待。"
  },
  Stage_8153_Desc = {
    Text = "老套的開局：落單的失憶守密人。\n不同的是，這次是在孤獨的大海上醒來。"
  },
  Stage_8153_Name = {Text = "風暴眼"},
  Stage_8154_Desc = {
    Text = "跨越諸海之使徒。"
  },
  Stage_8155_Desc = {
    Text = "在一艘船上，除了船長，還有誰是值得相信的呢？"
  },
  Stage_8155_Name = {Text = "船員"},
  Stage_8156_Desc = {
    Text = "退無可退之時，訓練有素的夥伴往往是破局的關鍵——拉蒙娜再次教會了你這點。"
  },
  Stage_8156_Name = {
    Text = "無路可逃"
  },
  Stage_8157_Desc = {
    Text = "踏破諸海而過的，除了敵人，或許還有希望的微光。"
  },
  Stage_8158_Desc = {
    Text = "那是意圖斬破海洋之人的巨刃，是意圖踏平諸海之人的野心。"
  },
  Stage_8158_Name = {
    Text = "狂徒與巨刃"
  },
  Stage_8159_Desc = {
    Text = "那是她縈繞不散的一場噩夢，也是糾纏她一生的扭曲現實。"
  },
  Stage_8159_Name = {
    Text = "扭曲的現實"
  },
  Stage_8160_Desc = {
    Text = "它們在黑暗中扭曲、融合，然後被小心翼翼地保管在造像裡。\n這是一次蓄謀已久的重逢。"
  },
  Stage_8160_Name = {
    Text = "超維之旅·間隙Ⅴ"
  },
  Stage_8161_Desc = {
    Text = "倫蒂尼恩以燦爛的工業文明，以及籠罩市區的鉛灰色濃霧聞名。\n霧氣無處不在，對路人來說是更像是一種偶然、無意義的不便。"
  },
  Stage_8161_Name = {
    Text = "怪霧之都Ⅳ"
  },
  Stage_8162_Desc = {
    Text = "潛藏在宇宙深處的彎曲視界。 \n它能帶你從黑暗抵達另一處黑暗。"
  },
  Stage_8163_Desc = {
    Text = "虛無乃吾等之源頭，亦為吾等之歸宿。"
  },
  Stage_8163_Name = {
    Text = "不朽的低語"
  },
  Stage_8164_Desc = {
    Text = "荒蕪的鐵路橋下，龐大臃腫的怪物發出古怪的低吼。要抵達拉伊瘋人院，就必須跨過這裡。"
  },
  Stage_8164_Name = {
    Text = "船到橋頭自然直"
  },
  Stage_8165_Desc = {
    Text = "艾爾沃斯位於卡達斯的極點，終年被不融的冰雪覆蓋，\n厚實而堅硬的冰殼下，隱約潛藏著生命的搏動。"
  },
  Stage_8165_Name = {
    Text = "失序山脈Ⅰ"
  },
  Stage_8166_Desc = {
    Text = "來歷不明的造像在黑暗中遊蕩、戰慄。\n它們踏著古老的節拍，循著來自遠方的笛聲起舞。"
  },
  Stage_8166_Name = {
    Text = "混沌之域·間隙Ⅷ"
  },
  Stage_8167_Desc = {
    Text = "「它是唯一，它是全部，它是開啟真相之門的希望。」\n無數鑰匙圍成了一個圈。它們自天空中墜落，帶給人們沉甸甸的希望。\n也帶來沉甸甸的墳墓。"
  },
  Stage_8167_Name = {
    Text = "幻夢深潛Ⅳ"
  },
  Stage_8168_Desc = {
    Text = "「門」即將開啟，你從中窺見一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是渾濁的。"
  },
  Stage_8168_Name = {
    Text = "血肉之沼·間隙Ⅲ"
  },
  Stage_8169_Desc = {
    Text = "「它是唯一，它是全部，它是開啟真相之門的希望。」\n無數鑰匙圍成了一個圈。它們自天空中墜落，帶給人們沉甸甸的希望。\n也帶來沉甸甸的墳墓。"
  },
  Stage_8169_Name = {
    Text = "幻夢深潛Ⅵ"
  },
  Stage_8170_Desc = {
    Text = "「它是唯一，它是全部，它是開啟真相之門的希望。」\n無數鑰匙圍成了一個圈。它們自天空中墜落，帶給人們沉甸甸的希望。\n也帶來沉甸甸的墳墓。"
  },
  Stage_8170_Name = {
    Text = "幻夢深潛Ⅶ"
  },
  Stage_8171_Desc = {
    Text = "「它是唯一，它是全部，它是開啟真相之門的希望。」\n無數鑰匙圍成了一個圈。它們自天空中墜落，帶給人們沉甸甸的希望。\n也帶來沉甸甸的墳墓。"
  },
  Stage_8171_Name = {
    Text = "幻夢深潛Ⅰ"
  },
  Stage_8172_Desc = {
    Text = "「它是唯一，它是全部，它是開啟真相之門的希望。」\n無數鑰匙圍成了一個圈。它們自天空中墜落，帶給人們沉甸甸的希望。\n也帶來沉甸甸的墳墓。"
  },
  Stage_8172_Name = {
    Text = "幻夢深潛Ⅱ"
  },
  Stage_8173_Desc = {
    Text = "來歷不明的造像在黑暗中遊蕩、戰慄。\n它們踏著古老的節拍，循著來自遠方的笛聲起舞。"
  },
  Stage_8173_Name = {
    Text = "超維之旅·間隙Ⅱ"
  },
  Stage_8174_Desc = {
    Text = "他不會是祂，祂不可能是他。\n沒錯……沒錯，只有我的神明，才是真正的他。"
  },
  Stage_81757_Desc = {
    Text = "光輝的神國逐漸顯現於你裂開的眼瞳裡。\n在那裡，你將獲得應許，擁有一切。"
  },
  Stage_81757_Name = {
    Text = "神國的低喃"
  },
  Stage_81758_Desc = {
    Text = "通過那象牙的雕塑，祂的目光降落人世間。\n從此， 你我都沉淪於祂的意志中。"
  },
  Stage_81758_Name = {
    Text = "聖象的注視"
  },
  Stage_81759_Desc = {
    Text = "無垠的宇宙在你的體內彙聚，猶如群星奔向正位之刻。\n回應這來自虛空的召喚吧！祂的子嗣。祂的傀儡。"
  },
  Stage_81759_Name = {
    Text = "虛空的召喚"
  },
  Stage_8175_Desc = {
    Text = "現實埋下了禍種，命運卻指引著相遇。"
  },
  Stage_8175_Name = {
    Text = "命運的種子"
  },
  Stage_81760_Desc = {
    Text = "虛幻與現實的罅隙，祭禮已經開始。\n歡呼吧，呐喊吧，你的喜悅與痛苦將穿越維度，成為神國降臨的頌樂。"
  },
  Stage_81760_Name = {
    Text = "祭禮的回應"
  },
  Stage_81761_Desc = {
    Text = "一切的狂喜已經過去。\n你拖著分裂的身軀，伸出觸手，對世界發出覺醒後的第一聲恐怖而褻瀆的嘶吼。\n\n「神國終將降臨。」"
  },
  Stage_81761_Name = {
    Text = "無妄的皈依"
  },
  Stage_81762_Desc = {
    Text = "啊，傾聽這混沌的聲音，傾聽這無盡的幻樂。\n神已經降下了聖諭，而你作為祂的子嗣與傀儡，將忠誠執行到底。"
  },
  Stage_81762_Name = {
    Text = "神王的聖諭"
  },
  Stage_81763_Desc = {
    Text = "加速的心跳只是血肉悸動的前兆。\n不必恐慌，那只是你的血脈在覺醒的聲音。"
  },
  Stage_81763_Name = {
    Text = "軀殼的悸動"
  },
  Stage_8176_Desc = {
    Text = "第二顆心臟在墨菲體內跳動著，阻止「降生儀式」迫在眉睫。"
  },
  Stage_8176_Name = {
    Text = "另一個奇蹟"
  },
  Stage_8177_Desc = {
    Text = "突出重圍永遠不簡單，但好在，這一次守密人找到了最亮的恒星。"
  },
  Stage_81781_Desc = {
    Text = "不可見的災難復甦，物理世界的歷史與存在正在墜入深淵。"
  },
  Stage_81781_Name = {
    Text = "融災禁區·第3波·癲狂"
  },
  Stage_81782_Desc = {
    Text = "不可見的災難復甦，物理世界的歷史與存在正在墜入深淵。"
  },
