  },
  Stage_81789_Name = {
    Text = "融災禁區·第3波·癲狂"
  },
  Stage_8178_Desc = {
    Text = "人以自身意志改造世界，也以此意志改變自身。"
  },
  Stage_8178_Name = {Text = "決意"},
