  },
  Stage_83248_Name = {
    Text = "融災禁區·第5波·困難"
  },
  Stage_83249_Desc = {
    Text = "漆黑的潮水漫過警戒界限，輕微的波動亦昭示著足以吞噬掉以輕心者的險惡。"
  },
  Stage_83249_Name = {
    Text = "融災禁區·第5波·普通"
  },
  Stage_83250_Desc = {
    Text = "漆黑的潮水漫過警戒界限，輕微的波動亦昭示著足以吞噬掉以輕心者的險惡。"
  },
  Stage_83250_Name = {
    Text = "融災禁區·第4波·普通"
  },
  Stage_88880_Desc = {
    Text = "我持著你曾點燃的火。\n你曾引領我的，我將作你的眼，帶你重見光明。\n你所行的路，我將替你前進，所有銹蝕的柵欄都將在這火前走向坍塌。"
  },
  Stage_88880_Name = {
    Text = "傳燭者·之三"
  },
  Stage_88881_Desc = {
    Text = "一座定格的城，固化了一片文明的標本。"
  },
  Stage_88881_Name = {Text = "標本"},
  Stage_88882_Desc = {
    Text = "他生來便愚笨、遲鈍，囿於簡單的生活中，盲目又執拗。\n但誰說愚者不能走出一條全新的路？所有禁錮不過是未孵化的風暴，即便他一無所知，仍會用翅膀無畏地飛向未知的天空。"
  },
  Stage_88882_Name = {
    Text = "愚者·癲狂"
  },
  Stage_88883_Desc = {
    Text = "我夢到了久遠的舊日。\n那時你指著書中如鋪灑在藍絲絨布上的、深邃的群星，說以後要挑選一個晴朗的夜晚，一同在月亮身旁飛翔，看看天空之上到底有怎樣的景象。"
  },
  Stage_88883_Name = {
    Text = "昨日之夢·之六"
  },
  Stage_88884_Desc = {
    Text = "他一直擁有兩道影子，如今他將另一道弄丟了。\n他孤單地走在寂靜的夜空下，唱起兒時與他一同編撰的歌謠。\n飛鳥，飛鳥，你在哪……\n影子，影子，快回家……"
  },
  Stage_88884_Name = {
    Text = "孤獨之旅·之五"
  },
  Stage_88885_Desc = {
    Text = "我持著你曾點燃的火。\n你曾引領我的，我將作你的眼，帶你重見光明。\n你所行的路，我將替你前進，所有銹蝕的柵欄都將在這火前走向坍塌。"
  },
  Stage_88885_Name = {
    Text = "傳燭者·之四"
  },
  Stage_88886_Desc = {
    Text = "我持著你曾點燃的火。\n你曾引領我的，我將作你的眼，帶你重見光明。\n你所行的路，我將替你前進，所有銹蝕的柵欄都將在這火前走向坍塌。"
  },
  Stage_88886_Name = {
    Text = "傳燭者·之二"
  },
  Stage_88887_Desc = {
    Text = "若生於籠中，可該天生受縛？\n若深埋地底，偏要破土重生。"
  },
  Stage_88887_Name = {
    Text = "破開囚籠·之五"
  },
  Stage_88888_Desc = {
    Text = "若生於籠中，可該天生受縛？\n若深埋地底，偏要破土重生。"
  },
