  },
  Stage_88890_Name = {
    Text = "傳燭者·之六"
  },
  Stage_88891_Desc = {
    Text = "那沙如海，風息時，波濤低伏；風驟時，生靈盡滅。\n他於無盡沙海中，若海燕般不屈地飛翔。"
  },
  Stage_88891_Name = {
    Text = "無盡沙·之一"
  },
  Stage_88892_Desc = {
    Text = "那沙如海，風息時，波濤低伏；風驟時，生靈盡滅。\n他於無盡沙海中，若海燕般不屈地飛翔。"
  },
  Stage_88892_Name = {
    Text = "無盡沙·之六"
  },
  Stage_88893_Desc = {
    Text = "從他睜開了眼，那眼就無法再閉上。\n從他見過了天，那天就始終在心中。\n若那自由需用死亡換取，他便將毫不猶豫地獻出自己的生命。"
  },
