  Stage_88900_Name = {
    Text = "傳燭者·之五"
  },
  Stage_88901_Desc = {
    Text = "他熟練地解開身上的鐐銬，向著牢籠之外不斷奔跑。他記得每一次轉彎、每一個暗哨，為此他已經準備了太久太久，畢竟，這已不是他的第一次出逃。"
  },
  Stage_88902_Desc = {
    Text = "從他睜開了眼，那眼就無法再閉上。\n從他見過了天，那天就始終在心中。\n若那自由需用死亡換取，他便將毫不猶豫地獻出自己的生命。"
  },
