  Stage_89731_Desc = {
    Text = "那滴緩緩墜下的淚啊，晶瑩如純潔的冰花。"
  },
  Stage_89731_Name = {Text = "一滴淚"},
  Stage_89732_Desc = {
    Text = "奔跑、躲藏、追蹤、拉扯，獵人已舉起了黑洞洞的槍口。"
  },
  Stage_89732_Name = {Text = "圍獵"},
  Stage_90490_Desc = {
    Text = "於混沌中誕生的喚醒體與你站在一起，你的銀鑰發出亢奮的顫鳴。\n與他們一起戰鬥，掌握激發銀鑰潛能的方法。"
  },
  Stage_90662_Desc = {
    Text = "當墓園的鐘聲奏響，彌漫的黑霧將於夢境中消散。\n推開沉重的棺木吧，那宏偉的王城，已降臨你身前。"
  },
  Stage_90662_Name = {
    Text = "夢境之下"
  },
  Stage_90663_Desc = {
    Text = "聆聽吧，這海洋的慟哭。\n信徒們虔誠地懇求。懇求主回應他們的禱告，懇求主恩賞他們的血。"
  },
  Stage_90664_Desc = {
    Text = "「沉眠於此地的屍骨，遊蕩於夜空的魂靈啊——\n以食屍鬼之王、葬骸城之主的名，我將邀請你們，重新回到你們眷戀的土地。\n我將邀請你們與我一同，享用這敵人贈予的饜饗！」"
  },
  Stage_90664_Name = {
    Text = "萬靈之舞"
  },
  Stage_90665_Desc = {
    Text = "長相廝守的誓言，早在竭誠盡忠之前。"
  },
  Stage_90666_Desc = {
    Text = "罪孽？陰謀？死亡？\n畫家無暇關心這些。他的眼裡，只有屍體們所構成的宏偉圖景。"
  },
  Stage_90666_Name = {Text = "畫家"},
  Stage_90667_Desc = {
    Text = "長相廝守的誓言，早在竭誠盡忠之前。"
  },
  Stage_90670_Desc = {
    Text = "在葬骸城君主的所有品質中，對美食的品味至關重要。"
  },
  Stage_90670_Name = {
    Text = "王與屍體烹飪藝術"
  },
  Stage_90671_Desc = {
    Text = "一位血親的記憶。一個城邦王室的故事。一段沉重恢弘的歷史。\n一位平民的記憶。一個平凡家族的故事。一條可有可無的注腳。\n對於葬骸城的王來說，它們不應、也不會有任何區別。"
  },
  Stage_90671_Name = {
    Text = "卑微的注腳"
  },
  Stage_90672_Desc = {
    Text = "「絃樂已升上中天，一切繁文縟節都已隨霧色消散。\n我親愛的臣民們，歡呼吧。撕開裹屍布下的偽善，露出那原始的饑渴之相。\n今夜，詩人的喉管將為我們吟誦。\n今夜，母親的雙臂將擁我們入懷。」"
  },
  Stage_90672_Name = {
    Text = "月光、骸骨與舞"
  },
  Stage_90674_Desc = {
    Text = "他是葬骸城的君王。他是這場宴會的主人。\n他向所有賓客張開雙臂，邀請他們離開舞池。\n墓園遍地的屍骸上，他與深淵共舞。"
  },
  Stage_90676_Desc = {
    Text = "當墓園的鐘聲奏響，彌漫的黑霧將於夢境中消散。\n推開沉重的棺木吧，那宏偉的王城，已降臨你身前。"
  },
  Stage_90676_Name = {
    Text = "夢境之下"
  },
  Stage_90679_Desc = {
    Text = "在葬骸城君主的所有品質中，對美食的品味至關重要。"
  },
  Stage_90679_Name = {
    Text = "王與屍體烹飪藝術"
  },
  Stage_90680_Desc = {
    Text = "夢裡的聲音，湮沒的文明，故友的蹤跡……\n你想知曉的一切，在遠海之上等待著你。"
  },
  Stage_90680_Name = {
    Text = "遠海之上"
  },
  Stage_90681_Desc = {
    Text = "聆聽吧，這海洋的慟哭。\n信徒們虔誠地懇求。懇求主回應他們的禱告，懇求主恩賞他們的血。"
  },
  Stage_90684_Desc = {
    Text = "眼前這個蒼老的食屍鬼是誰？他為何衣衫破爛？他為何淚流滿面？\n他為何痛哭著，用最溫和、最嘶啞的聲音，呼喚著那個叫做伊萊娜的名字？\n她什麼也想不起來。\n月光落在她的屍體上，美得如同婚禮那天，她身上隨風翕動的紗幔。"
  },
  Stage_90684_Name = {
    Text = "婚紗與葬禮"
  },
  Stage_90685_Desc = {
    Text = "眼前這個蒼老的食屍鬼是誰？他為何衣衫破爛？他為何淚流滿面？\n他為何痛哭著，用最溫和、最嘶啞的聲音，呼喚著那個叫做伊萊娜的名字？\n她什麼也想不起來。\n月光落在她的屍體上，美得如同婚禮那天，她身上隨風翕動的紗幔。"
  },
