  Stage_90691_Name = {
    Text = "月光、骸骨與舞"
  },
  Stage_90985_Desc = {
    Text = "所有阻攔者將恐懼匍匐，所有光輝盡歸於羅馬。\n那潔白的花冠與月桂葉，將戴在最勇猛的戰士頭上。"
  },
  Stage_90986_Desc = {
    Text = "歡呼聲與鮮花、美酒與盛宴、黃金與珍寶。\n享受吧，大笑吧，這是勇士應得的榮耀！"
  },
  Stage_90986_Name = {
    Text = "榮耀凱旋·之五"
  },
  Stage_90987_Desc = {
    Text = "所有阻攔者將恐懼匍匐，所有光輝盡歸於羅馬。\n那潔白的花冠與月桂葉，將戴在最勇猛的戰士頭上。"
  },
  Stage_90988_Desc = {
    Text = "無論獵物藏在何處，專業的獵手都將嗅到那甘美的香味。"
  },
  Stage_90988_Name = {
    Text = "兇猛獵手·癲狂"
  },
  Stage_90989_Desc = {
    Text = "征服的號角吹響，戰士們已踏上征程。\n我們前進，我們不可抵擋，我們必將勝利。"
  },
  Stage_90989_Name = {
    Text = "遠征號角·之二"
  },
  Stage_90990_Desc = {
    Text = "征服的號角吹響，戰士們已踏上征程。\n我們前進，我們不可抵擋，我們必將勝利。"
  },
  Stage_90990_Name = {
    Text = "遠征號角·之四"
  },
  Stage_90991_Desc = {
    Text = "我承認我們過去有些嫌隙，但這並不妨礙我們暫時共同將矛頭指向這個可惡的、可恨的、卑鄙的現代科技。"
  },
