  Stage_91019_Name = {
    Text = "榮耀凱旋·之六"
  },
  Stage_91088_Desc = {
    Text = "他們是主僕、是兇手與死者、是同一片廢墟的遺物。\n循著血脈的饑渴，他們在同一扇門前不期而遇。"
  },
  Stage_91088_Name = {
    Text = "奴隸與奴隸主"
  },
  Stage_91091_Desc = {
    Text = "誰說舊日的榮光不可歸來？\n看著吧，可惡的現代科技，羅馬的力量終將戰勝一切！"
  },
  Stage_91091_Name = {
    Text = "羅馬的力量"
  },
  Stage_94464_Desc = {
    Text = "來自深海的喚醒體，帶著潛藏於海底的偉力來到你面前。\n與他們一起戰鬥，掌握使用觸腕力量的方法。"
  },
  Stage_94464_Name = {
    Text = "深海之觸"
  },
  Stage_94465_Desc = {
    Text = "血肉是生命的本初，亦是生命的終結。死即為生，由純粹血肉所構築的喚醒體們最清楚這一點。\n與他們一起戰鬥，掌握駕馭血肉之力的方法。"
  },
  Stage_94466_Desc = {
    Text = "於超維中穿行的喚醒體們並不完全了解這片空間的秘密，在你解開它們的那一天，你將窺見令你驚異的力量。\n與他們一起戰鬥，掌握利用超維空間進行戰鬥的方法。"
  },
  Stage_94466_Name = {
    Text = "超維之域"
  },
  Stage_94806_Desc = {
    Text = "美好的假日怎麼能被粗魯和暴力所破壞，要打，就在排球場上一決勝負吧！"
  },
  Stage_94806_Name = {
    Text = "文明決鬥"
  },
  Stage_94808_Desc = {
    Text = "既然作為冠軍，總該有一些小小的特權。"
  },
  Stage_94808_Name = {
    Text = "冠軍與大亂鬥"
  },
  Stage_94811_Desc = {
    Text = "要拿下第一名的人，怎麼會在同一個地方跌倒兩次！"
  },
  Stage_94811_Name = {
    Text = "決勝一球"
  },
  Stage_94817_Desc = {
    Text = "人們習慣用規則控制不可避免的熵增。事實上每一個人都有自己的原則，而當幾十個原則碰撞在一起，這裡最終的原則就會變成——沒有原則！"
  },
  Stage_94817_Name = {
    Text = "配對原則"
  },
  Stage_94824_Desc = {
    Text = "靜謐的夜晚，柔和的海風，在群星溫柔的照耀下，總是適合吐露一些秘密的心事。"
  },
  Stage_94824_Name = {
    Text = "只有夜風知道"
  },
  Stage_94832_Desc = {
    Text = "她的心中清楚地知曉：一腔孤勇不能換來無可匹敵的勝利，過去如此，現在依然。"
  },
  Stage_94832_Name = {Text = "險勝"},
  Stage_94837_Desc = {
    Text = "如果這一刻的歡樂能夠定格，我希望那份記憶的期限是永遠。"
  },
  Stage_94837_Name = {
    Text = "一張照片"
  },
  Stage_94841_Desc = {
    Text = "海濱即是假日的標準答案，酷暑之下，誰能拒絕踩著清涼的浪花，於遮陽傘下躲避烈日的炙烤呢？等等……為什麼太陽會掉下來啊？！"
  },
  Stage_94841_Name = {
    Text = "高溫預警"
  },
  Stage_94843_Desc = {
    Text = "在激昂的賽場上，每位選手都將一展自己的風采……導播，把那些無法播出的風采通通掐掉。"
  },
