  },
  Stage_95380_Desc = {
    Text = "祂沒有帶走聲音，因為祂想聆聽負罪者置身於煉獄中的哀嚎。\n億萬光點於極晝中起舞、共鳴，它們的聲音伴隨著那哀嚎，於煉獄中交織成完美的歌。"
  },
  Stage_95380_Name = {
    Text = "煉獄之歌·之五"
  },
  Stage_95706_Desc = {
    Text = "那些的悽苦的、美麗的、承載了太多記憶的靈魂，正是每道食材獨一無二的緣由。\n讓每個層次，與你的舌尖對抗、廝殺，然後你們融為一體。\n——每個亡者終其一生所等待的，是被吞食的這一刻。"
  },
  Stage_95706_Name = {
    Text = "靈龕盛筵·之六"
  },
  Stage_95707_Desc = {
    Text = "0.5英寸的深度，和經絡的方向垂直。\n沿著脖脊與扇骨，將骨與肉分離。\n身軀，即是烹飪者的棋盤。"
  },
  Stage_95707_Name = {
    Text = "骨血剝離·之六"
  },
  Stage_95708_Desc = {
    Text = "聞到了麼？橡木、雪松與香根草帶來的清香。\n它的主人在這美麗的棺木裡躺了三百年。\n由此，它獲得了成為這場宴席主菜的殊榮。"
  },
  Stage_95708_Name = {
    Text = "沉棺開啟·之六"
  },
  Stage_95709_Desc = {
    Text = "聞到了麼？橡木、雪松與香根草帶來的清香。\n它的主人在這美麗的棺木裡躺了三百年。\n由此，它獲得了成為這場宴席主菜的殊榮。"
  },
  Stage_95709_Name = {
    Text = "沉棺開啟·之二"
  },
  Stage_95710_Desc = {
    Text = "鹽粒。歐芹。香茅。橄欖。迷迭香。\n一個忠告：無論再好的食材，也永遠不要輕視香料。\n在這棋盤之上，香料便是烹飪者的棋子。"
  },
  Stage_95710_Name = {
    Text = "腐殖調香·之三"
  },
  Stage_95711_Desc = {
    Text = "我們歌頌品味與永恆，火焰則是是它們的反義詞。\n可這世上最雋永、最美妙的風味，又偏偏來自於火焰。\n一種絕妙的諷刺，不是嗎？"
  },
  Stage_95712_Desc = {
    Text = "0.5英寸的深度，和經絡的方向垂直。\n沿著脖脊與扇骨，將骨與肉分離。\n身軀，即是烹飪者的棋盤。"
  },
