    Text = "那些的悽苦的、美麗的、承載了太多記憶的靈魂，正是每道食材獨一無二的緣由。\n讓每個層次，與你的舌尖對抗、廝殺，然後你們融為一體。\n——每個亡者終其一生所等待的，是被吞食的這一刻。"
  },
  Stage_95720_Name = {
    Text = "靈龕盛筵·之一"
  },
  Stage_95721_Desc = {
    Text = "我們歌頌品味與永恆，火焰則是是它們的反義詞。\n可這世上最雋永、最美妙的風味，又偏偏來自於火焰。\n一種絕妙的諷刺，不是嗎？"
  },
  Stage_95722_Desc = {
    Text = "0.5英寸的深度，和經絡的方向垂直。\n沿著脖脊與扇骨，將骨與肉分離。\n身軀，即是烹飪者的棋盤。"
  },
