  },
  Stage_95725_Name = {
    Text = "靈龕盛筵·之五"
  },
  Stage_95727_Desc = {
    Text = "聞到了麼？橡木、雪松與香根草帶來的清香。\n它的主人在這美麗的棺木裡躺了三百年。\n由此，它獲得了成為這場宴席主菜的殊榮。"
  },
  Stage_95727_Name = {
    Text = "沉棺開啟·之五"
  },
  Stage_95728_Desc = {
    Text = "鹽粒。歐芹。香茅。橄欖。迷迭香。\n一個忠告：無論再好的食材，也永遠不要輕視香料。\n在這棋盤之上，香料便是烹飪者的棋子。"
  },
