  },
  Stage_95742_Name = {
    Text = "腐殖調香·之四"
  },
  Stage_97057_Desc = {
    Text = "狂熱的舞者圍繞著虛妄的偶像旋轉，無人問津信仰的殘骸，只有歡愉的漩渦在失控中越卷越緊。\n這一刻，所有羞恥與顧忌在狂熱的旋轉中化為烏有，眾生隻為幻影而狂舞。 \n皮克曼大笑著，邀請你加入這狂熱的舞蹈。"
  },
  Stage_97057_Name = {
    Text = "金牛瘋舞·之四"
  },
  Stage_97058_Desc = {
    Text = "靈感，是甘於平庸者的禁果。\n而在此畫卷之上，誇張的構圖昭示著藝術的真諦。\n靈感如疾風驟雨降臨，無需邀請便闖入心房。\n那一刻，潛藏的不安與渴望悉數覺醒，像洞穿黑夜的火光，把內心照得通透又熾熱。"
  },
  Stage_97058_Name = {
    Text = "靈感侵染·之三"
  },
  Stage_97059_Desc = {
    Text = "有誰見過如此瘋狂的線條？\n每一道軌跡都掙脫了透視法則的鎖鏈，像暴動的囚徒般在紙面狂奔。\n它們交錯、廝殺、互相吞噬，用扭曲的舞蹈繪出皮克曼眼中的真實。"
  },
  Stage_97059_Name = {
    Text = "線魂肆虐·之三"
  },
  Stage_97060_Desc = {
    Text = "有誰見過如此瘋狂的線條？\n每一道軌跡都掙脫了透視法則的鎖鏈，像暴動的囚徒般在紙面狂奔。\n它們交錯、廝殺、互相吞噬，用扭曲的舞蹈繪出皮克曼眼中的真實。"
  },
  Stage_97060_Name = {
    Text = "線魂肆虐·之五"
  },
  Stage_97061_Desc = {
    Text = "平凡的畫家？不，不。\n鮮紅的筆觸翻湧而出，詭異的渦流迅速將蒼白與清明淹沒。\n明豔與陰鬱交織的赤色蔓延開來，讓整幅作品染上躁動與生命的氣息。\n只有這血一般的色彩，才是世間最鮮活真實的存在！"
  },
  Stage_97061_Name = {
    Text = "血色蔓延·癲狂"
  },
  Stage_97062_Desc = {
    Text = "平凡的畫家？不，不。\n鮮紅的筆觸翻湧而出，詭異的渦流迅速將蒼白與清明淹沒。\n明豔與陰鬱交織的赤色蔓延開來，讓整幅作品染上躁動與生命的氣息。\n只有這血一般的色彩，才是世間最鮮活真實的存在！"
  },
  Stage_97063_Desc = {
    Text = "狂熱的舞者圍繞著虛妄的偶像旋轉，無人問津信仰的殘骸，只有歡愉的漩渦在失控中越卷越緊。\n這一刻，所有羞恥與顧忌在狂熱的旋轉中化為烏有，眾生隻為幻影而狂舞。 \n皮克曼大笑著，邀請你加入這狂熱的舞蹈。"
  },
  Stage_97063_Name = {
    Text = "金牛瘋舞·之五"
  },
  Stage_97064_Desc = {
    Text = "靈感，是甘於平庸者的禁果。\n而在此畫卷之上，誇張的構圖昭示著藝術的真諦。\n靈感如疾風驟雨降臨，無需邀請便闖入心房。\n那一刻，潛藏的不安與渴望悉數覺醒，像洞穿黑夜的火光，把內心照得通透又熾熱。"
  },
  Stage_97064_Name = {
    Text = "靈感侵染·之四"
  },
  Stage_97065_Desc = {
    Text = "未知的苦難在色彩深處咆哮。殘酷的景象浮現，彼岸的烈焰、扭曲的影子擁擠著相互纏繞。\n此時的畫布成了罪與罰的囚牢，每一寸都閃爍著熾烈的懲戒與痛苦。\n世界已然顛倒，一切良善覆沒，在燃燒與苦難的地獄中揭示出靈魂的真相。\n看到了嗎？這才是藝術之美。"
  },
  Stage_97065_Name = {
    Text = "地獄之變·之五"
  },
  Stage_97066_Desc = {
    Text = "靈魂在畫布上熊熊燃燒，清透的光油緩慢流淌，血色定格為永恆的世界，瘋癲才是真實的酒釀。\n唯有捨棄世俗的清醒，衝進混沌的極樂，才終於觸及了藝術本身。\n啊，我願永恆地沉淪在這終極的狂喜與絕望！ \n來吧，於這癲狂的盛宴後，迎來美麗的新世界。"
  },
  Stage_97066_Name = {
    Text = "狂歡定格·癲狂"
  },
  Stage_97067_Desc = {
    Text = "平凡的畫家？不，不。\n鮮紅的筆觸翻湧而出，詭異的渦流迅速將蒼白與清明淹沒。\n明豔與陰鬱交織的赤色蔓延開來，讓整幅作品染上躁動與生命的氣息。\n只有這血一般的色彩，才是世間最鮮活真實的存在！"
  },
  Stage_97068_Desc = {
    Text = "皮克曼狂躁的筆觸翻攪油彩，畫筆沾滿血肉與靈魂的苦澀。\n亂神般的軌跡在畫布上蜿蜒，夢魘與幻象悄然浮現於色彩的深淵。\n畫中世界，在這場失控的迷離中逐漸扭曲、沉淪……"
  },
