  Stage_97104_Name = {
    Text = "夢魘堆壘·之六"
  },
  Stage_97105_Desc = {
    Text = "未知的苦難在色彩深處咆哮。殘酷的景象浮現，彼岸的烈焰、扭曲的影子擁擠著相互纏繞。\n此時的畫布成了罪與罰的囚牢，每一寸都閃爍著熾烈的懲戒與痛苦。\n世界已然顛倒，一切良善覆沒，在燃燒與苦難的地獄中揭示出靈魂的真相。\n看到了嗎？這才是藝術之美。"
  },
  Stage_97105_Name = {
    Text = "地獄之變·之四"
  },
  Stage_97227_Desc = {
    Text = "祭品已至，鮮血盈滿，端坐於寰宇的至高之主啊！請接您的信者前往永恆的國！"
  },
  Stage_97228_Desc = {
    Text = "黑日降臨了，不是麼？"
  },
  Stage_97229_Desc = {
    Text = "背叛恰到好處的發生了，「遭人蠱惑」、「迫不得已」、「為了生存」，多麼完美的背叛理由啊。\n可惜，它挑錯了背叛的對象。"
  },
  Stage_97230_Desc = {
    Text = "謎底揭曉，你猜對了麼？\n覺得很俗套？我覺得還蠻有趣的，畢竟……我也不在乎有不有趣~"
  },
  Stage_97230_Name = {
    Text = "幕後禍首"
  },
  Stage_97231_Desc = {
    Text = "我們不會忘記每一份恩情，也不會遺忘每一筆仇恨。這是我們生活在這個殘酷世界，最後的奢靡。"
  },
  Stage_97231_Name = {
    Text = "永不遺忘"
  },
  Stage_97232_Desc = {
    Text = "抬起你宿醉的腦袋，端起你骯髒的酒杯。忘掉昨夜的一切，新的派對就要到來。\n我的朋友，歡迎來到這座表現主義的樂園。"
  },
  Stage_97232_Name = {
    Text = "野獸主義酒館"
  },
  Stage_97233_Desc = {
    Text = "當最後一滴酒從杯中落下，埋葬一切的槍聲應約響起。"
  },
  Stage_97233_Name = {
    Text = "乾涸之酒"
  },
  Stage_97288_Desc = {
    Text = "模擬戰鬥"
  },
  Stage_97288_Name = {Text = "模擬戰3"},
  Stage_97615_Desc = {
    Text = "神喚萬物萬事各行其道。\n虯結根莖埋入腐土，爪牙鱗羽撕咬爬行。繁花生於枯骨之上，羸弱吞於強大腹中。\n祂賜予眾生相互糾纏廝殺的權利。"
  },
  Stage_97615_Name = {
    Text = "第五日·癲狂"
  },
  Stage_97616_Desc = {
    Text = "神將群星歸於正位，使日月各司其職。\n光與暗的殘骸以癲狂軌跡行路，指引給千萬年迷茫的靈魂歸途。\n祂賜予虔信者復得的權利。"
  },
  Stage_97616_Name = {
    Text = "第三日·癲狂"
  },
  Stage_97617_Desc = {
    Text = "神使無形的胚種生長在世間。\n有鰭者洄遊在海，有翼者翱翔於天。\n祂賜予喃喃絮語伴祂們在深海呼吸，癲亂狂吟伴祂們在雲層穿行。"
  },
  Stage_97618_Desc = {
    Text = "神使無形的胚種生長在世間。\n有鰭者洄遊在海，有翼者翱翔於天。\n祂賜予喃喃絮語伴祂們在深海呼吸，癲亂狂吟伴祂們在雲層穿行。"
  },
  Stage_97619_Desc = {
    Text = "神讓天與地，地與海分離。\n蒼穹懸垂下黏稠而搏動的帷幕，硫磺與海鹽的氣息在深淵中蒸騰昇起。\n祂賜予海的子民行於各處的權利。"
  },
  Stage_97620_Desc = {
    Text = "神喚萬物萬事各行其道。\n虯結根莖埋入腐土，爪牙鱗羽撕咬爬行。繁花生於枯骨之上，羸弱吞於強大腹中。\n祂賜予眾生相互糾纏廝殺的權利。"
  },
  Stage_97621_Desc = {
    Text = "神喚萬物萬事各行其道。\n虯結根莖埋入腐土，爪牙鱗羽撕咬爬行。繁花生於枯骨之上，羸弱吞於強大腹中。\n祂賜予眾生相互糾纏廝殺的權利。"
  },
  Stage_97622_Desc = {
    Text = "神讓天與地，地與海分離。\n蒼穹懸垂下黏稠而搏動的帷幕，硫磺與海鹽的氣息在深淵中蒸騰昇起。\n祂賜予海的子民行於各處的權利。"
  },
  Stage_97623_Desc = {
    Text = "神為什麼在腐爛，神為什麼滴下膿血。\n神明，請指引我，請醒來，救救我啊——無論什麼都好！\n哦，神啊，神啊……\n不過是荒謬的錯誤與虛假的謊言。"
  },
  Stage_97624_Desc = {
    Text = "神使無形的胚種生長在世間。\n有鰭者洄遊在海，有翼者翱翔於天。\n祂賜予喃喃絮語伴祂們在深海呼吸，癲亂狂吟伴祂們在雲層穿行。"
  },
  Stage_97625_Desc = {
    Text = "神塑出無智無識的偽形。\n被裹挾來一同沉淪的祭品無法逃脫命運，神沒有予以啟示，神沒有回應，無目無口的嬰孩帶來虛假的教義。\n祂賜清醒者以迷醉的權利。"
  },
  Stage_97626_Desc = {
    Text = "神讓天與地，地與海分離。\n蒼穹懸垂下黏稠而搏動的帷幕，硫磺與海鹽的氣息在深淵中蒸騰昇起。\n祂賜予海的子民行於各處的權利。"
  },
  Stage_97627_Desc = {
    Text = "神為什麼在腐爛，神為什麼滴下膿血。\n神明，請指引我，請醒來，救救我啊——無論什麼都好！\n哦，神啊，神啊……\n不過是荒謬的錯誤與虛假的謊言。"
  },
  Stage_97628_Desc = {
    Text = "神讓天與地，地與海分離。\n蒼穹懸垂下黏稠而搏動的帷幕，硫磺與海鹽的氣息在深淵中蒸騰昇起。\n祂賜予海的子民行於各處的權利。"
  },
  Stage_97628_Name = {
    Text = "第二日·癲狂"
  },
  Stage_97629_Desc = {
    Text = "神於混沌中以光分別晝夜。\n蠕動光斑將永暗撕裂，祂的子民不必再擔心黑暗的威脅。\n祂賜予眾人在夜晚安睡的權利。"
  },
  Stage_97630_Desc = {
    Text = "神將群星歸於正位，使日月各司其職。\n光與暗的殘骸以癲狂軌跡行路，指引給千萬年迷茫的靈魂歸途。\n祂賜予虔信者復得的權利。"
  },
