  Stage_97807_Desc = {
    Text = "母親，是一句人們從出生至死亡之時都會呢喃的咒語。\n沒有孩子想要長大，沒有孩子不渴望母親充滿愛的懷抱。\n你要扮演那殘酷的命運，再一次將她從母親的懷抱中扯去嗎？"
  },
  Stage_97807_Name = {
    Text = "完美童話·癲狂"
  },
  Stage_97808_Desc = {
    Text = "美的文字往往誕生於痛苦。\n她察覺到那些美的時候，就已經知曉那些早已到來的、潛藏於生活影子中的悲劇。\n美啊，美就是短暫而破碎的一切。"
  },
  Stage_97808_Name = {
    Text = "詩意花園·之六"
  },
  Stage_97809_Desc = {
    Text = "如果這一刻的歡樂能夠定格，我希望那份記憶的期限是永遠。"
  },
  Stage_97809_Name = {
    Text = "一張照片"
  },
  Stage_97810_Desc = {
    Text = "美的文字往往誕生於痛苦。\n她察覺到那些美的時候，就已經知曉那些早已到來的、潛藏於生活影子中的悲劇。\n美啊，美就是短暫而破碎的一切。"
  },
  Stage_97810_Name = {
    Text = "詩意花園·之二"
  },
  Stage_97811_Desc = {
    Text = "她不曾忘記她的理想，哪怕是在失去靈魂之後。\n因科學而死的人，曾經也熱烈地為科學而活。"
  },
