  },
  Stage_97830_Desc = {
    Text = "你漫步在熟悉又陌生的校園，看著熱鬧又平凡的一切，你會為此欣喜著迷嗎？還是會悲傷於從來不曾擁有這些？"
  },
  Stage_97830_Name = {
    Text = "故地重遊·之四"
  },
  Stage_97831_Desc = {
    Text = "太陽早已死去，留在天空的不過是一具風化的屍體。\n正如這個衰朽的世界，在那些厚重灰塵中遺留下的，究竟是生命，還是生命臨死前活動的幻影？"
  },
  Stage_97831_Name = {
    Text = "直面黑陽·之五"
  },
  Stage_97832_Desc = {
    Text = "美的文字往往誕生於痛苦。\n她察覺到那些美的時候，就已經知曉那些早已到來的、潛藏於生活影子中的悲劇。\n美啊，美就是短暫而破碎的一切。"
  },
  Stage_97832_Name = {
    Text = "詩意花園·之三"
  },
  Stage_97833_Desc = {
    Text = "美的文字往往誕生於痛苦。\n她察覺到那些美的時候，就已經知曉那些早已到來的、潛藏於生活影子中的悲劇。\n美啊，美就是短暫而破碎的一切。"
  },
  Stage_97833_Name = {
    Text = "詩意花園·之四"
  },
  Stage_97834_Desc = {
    Text = "母親，是一句人們從出生至死亡之時都會呢喃的咒語。\n沒有孩子想要長大，沒有孩子不渴望母親充滿愛的懷抱。\n你要扮演那殘酷的命運，再一次將她從母親的懷抱中扯去嗎？"
  },
  Stage_97834_Name = {
    Text = "完美童話·之一"
  },
  Stage_97835_Desc = {
    Text = "她的心中清楚地知曉：一腔孤勇不能換來無可匹敵的勝利，過去如此，現在依然。"
  },
  Stage_97835_Name = {Text = "險勝"},
  Stage_97836_Desc = {
    Text = "太陽早已死去，留在天空的不過是一具風化的屍體。\n正如這個衰朽的世界，在那些厚重灰塵中遺留下的，究竟是生命，還是生命臨死前活動的幻影？"
  },
  Stage_97836_Name = {
    Text = "直面黑陽·之一"
  },
  Stage_97837_Desc = {
    Text = "在激昂的賽場上，每位選手都將一展自己的風采……導播，把那些無法播出的風采通通掐掉。"
  },
  Stage_97837_Name = {
    Text = "開始吧！半決賽！"
  },
  Stage_97838_Desc = {
    Text = "母親，是一句人們從出生至死亡之時都會呢喃的咒語。\n沒有孩子想要長大，沒有孩子不渴望母親充滿愛的懷抱。\n你要扮演那殘酷的命運，再一次將她從母親的懷抱中扯去嗎？"
  },
  Stage_97838_Name = {
    Text = "完美童話·之五"
  },
  Stage_97839_Desc = {
    Text = "你漫步在熟悉又陌生的校園，看著熱鬧又平凡的一切，你會為此欣喜著迷嗎？還是會悲傷於從來不曾擁有這些？"
  },
  Stage_97839_Name = {
    Text = "故地重遊·癲狂"
  },
  Stage_97840_Desc = {
    Text = "她不曾忘記她的理想，哪怕是在失去靈魂之後。\n因科學而死的人，曾經也熱烈地為科學而活。"
  },
  Stage_97840_Name = {
    Text = "機械之夢·之二"
  },
  Stage_97841_Desc = {
    Text = "太陽早已死去，留在天空的不過是一具風化的屍體。\n正如這個衰朽的世界，在那些厚重灰塵中遺留下的，究竟是生命，還是生命臨死前活動的幻影？"
