  },
  Stage_97844_Desc = {
    Text = "你漫步在熟悉又陌生的校園，看著熱鬧又平凡的一切，你會為此欣喜著迷嗎？還是會悲傷於從來不曾擁有這些？"
  },
  Stage_97844_Name = {
    Text = "故地重遊·之六"
  },
  Stage_97845_Desc = {
    Text = "你漫步在熟悉又陌生的校園，看著熱鬧又平凡的一切，你會為此欣喜著迷嗎？還是會悲傷於從來不曾擁有這些？"
  },
  Stage_97845_Name = {
    Text = "故地重遊·之二"
  },
  Stage_97903_Desc = {
    Text = "回到久違的故鄉時，你已成為了那個最格格不入的「異鄉人」。"
  },
  Stage_97903_Name = {Text = "歸鄉"},
  Stage_97904_Desc = {
    Text = "如果要描摹你想要生活的地方，你會繪製怎樣一座屋舍，怎樣一片鬱鬱蔥蔥的樹林，和一個怎樣的自己？\n你畫出的一切，究竟是無瑕的理想，還是深埋的創傷？"
  },
  Stage_97904_Name = {
    Text = "心靈摹寫"
  },
  Stage_97905_Desc = {
    Text = "向希望前進的道路，需先親手斬斷希望。"
  },
  Stage_97905_Name = {Text = "清醒夢"},
  Stage_97906_Desc = {
    Text = "和他們告別吧，然後踏上與他們重逢的路。"
  },
  Stage_97906_Name = {Text = "你的夢"},
  Stage_97907_Desc = {
    Text = "最完美的結局亦是最虛假的結局，在所有幸福的笑容裡，你必須選擇清醒與真實。\n因為你，是那個唯一的守密人。"
  },
  Stage_97907_Name = {
    Text = "虛假結局"
  },
  Stage_97908_Desc = {
    Text = "那些落下的花瓣啊，像一場鮮紅的火。"
  },
  Stage_97908_Name = {
    Text = "當花瓣落下"
  },
  Stage_97909_Desc = {
    Text = "如果命運不曾殘忍，她們是否也會活成理想最初的模樣。"
  },
  Stage_97909_Name = {
    Text = "最初的願望"
  },
  Stage_97910_Desc = {
    Text = "白色的裙子、床鋪、房間，和美夢。"
  },
  Stage_97910_Name = {
    Text = "純白童話"
  },
  Stage_98000_Desc = {
    Text = "虛假終將破碎，在真正亙古不熄的偉大之物面前，任何陰謀與計算都顯得無力且渺小。\n白晝將至，火從琥珀色的北落師門墜隕而下，給萬物帶來平等的毀滅和死亡。"
  },
  Stage_98000_Name = {
    Text = "亙古不熄的太陽"
  },
  Stage_98829_Desc = {
    Text = "痛苦啊，是催人清醒的良藥。"
  },
  Stage_98829_Name = {
    Text = "沉默覺醒·之三"
  },
  Stage_98830_Desc = {
    Text = "傳說，雙生子的命運註定一生糾纏，無法分割。\n在那片孕育了無數生命的星空下，我們終將重逢。"
  },
  Stage_98830_Name = {
    Text = "雙生羽翼·之二"
  },
  Stage_98831_Desc = {
    Text = "托住那雙翅膀的風，正如他溫柔的雙手啊。"
  },
  Stage_98831_Name = {
    Text = "風的托舉·癲狂"
  },
  Stage_98832_Desc = {
    Text = "英勇的騎士，熱血的冒險，充滿希望與挑戰的旅途。\n如果故事止於書中的結局，該有多麼美好。"
  },
  Stage_98832_Name = {
    Text = "冒險童話·之一"
  },
  Stage_98833_Desc = {
    Text = "忘卻一切記憶後，你還是曾經那個你嗎？"
  },
  Stage_98833_Name = {
    Text = "遺忘毒藥·之五"
  },
  Stage_98834_Desc = {
    Text = "托住那雙翅膀的風，正如他溫柔的雙手啊。"
