  Stage_99725_Desc = {
    Text = "批判不是藝術家的職責，創造才是。"
  },
  Stage_99725_Name = {
    Text = "淤泥上的沙龍"
  },
  Stage_99726_Desc = {
    Text = "我們一直都被困在同一架天平上互相傾軋，但親愛的弟弟，哪怕不能毀去它，我們原本就可以選擇從那座天平上跳下。"
  },
  Stage_99726_Name = {
    Text = "傾倒的天平"
  },
  Stage_99727_Desc = {
    Text = "一對互相依偎的鳥兒，生來就只能在籠中歌唱。"
