  Stage_99727_Name = {Text = "雙生鳥"},
  Stage_99728_Desc = {
    Text = "目睹真實之人，應當如何忍受虛幻？"
  },
  Stage_99729_Desc = {
    Text = "命運有著最差勁的鐘表，它總讓失去來得太早，擁有又來得太遲。"
  },
  Stage_99729_Name = {
    Text = "失序命運"
  },
  Stage_99730_Desc = {
    Text = "飛翔吧，飛翔吧，嚮往自由的飛鳥啊。\n溫柔的風已將你托舉，穿越暴雨與雷電，那黑色的翅膀終會映照緋紅的朝陽。"
